Object.assign(window.TEM8_DICTIONARY, {"hammer":{"media":{"img":["media/pic/tools_diy_comp.jpg","media/thumb/hammer.jpg"],"uk":"media/uk/hammer__gb_1.mp3","us":"media/us/hammer__us_1.mp3"},"oxford":{"phon":"ˈhæmə(r)","pos":"noun","senses":[{"en":"a tool with a handle and a heavy metal head, used for breaking things or hitting nails","cn":"锤子；榔头","g":"[countable]","sc":"tool","ex":{"en":"a gentle tap with a hammer","cn":"用锤子轻轻敲击"}},{"en":"a tool with a handle and a wooden head, used by a person in charge of an auction (= a sale at which things are sold to the person who offers the most money) in order to get people’s attention when something is just being sold","cn":"（拍卖用的）木槌","g":"[countable]","sc":"tool","ex":{"en":"to come/go under the hammer (= to be sold at auction)","cn":"被拍卖"}},{"en":"a small wooden part inside a piano, that hits the strings to produce a sound","cn":"音槌","g":"[countable]","sc":"in piano"},{"en":"a part inside a gun that makes the gun fire","cn":"击铁","g":"[countable]","sc":"in gun"},{"en":"a metal ball attached to a wire, thrown as a sport","cn":"链球","g":"[countable]","sc":"sport"},{"en":"the event or sport of throwing the hammer","cn":"掷链球（运动）","g":"[singular]","sc":"sport"},{"en":"the first of three small bones in the middle ear that carry sound to the inner ear","cn":"锤骨（引导声波从中耳传至内耳的三块小骨之一）","g":"[countable]","lab":"anatomy","sc":"in ear"},{"en":"to hit something with a hammer","cn":"（用锤子）敲，锤打","g":"[intransitive, transitive]","sc":"hit with tool","ex":{"en":"I could hear somebody hammering next door.","cn":"我听到隔壁有人在锤打东西。"},"pos":"verb"},{"en":"to hit something hard many times, especially so that it makes a loud noise","cn":"反复敲打，连续击打（尤指发出大声）","g":"[intransitive, transitive]","lab":"figurative","sc":"hit many times","ex":{"en":"Someone was hammering at the door.","cn":"有人在砰砰地捶门。"},"pos":"verb"},{"en":"to kick or hit a ball very hard","cn":"猛踢；猛击","g":"[transitive]","lab":"informal","sc":"kick/hit ball","ex":{"en":"He hammered the ball into the net.","cn":"他一记猛射，将球踢进网。"},"pos":"verb"},{"en":"to defeat somebody very easily","cn":"轻易击败","g":"[transitive]","lab":"informal","sc":"defeat easily","ex":{"en":"Our team was hammered 5–1.","cn":"我队以 1:5 的悬殊比分败北。"},"pos":"verb"},{"en":"to affect somebody/something very badly","cn":"重创；严重打击","g":"[transitive]","lab":"informal","sc":"affect badly","ex":{"en":"Eastern counties were brutally hammered by the weekend flooding.","cn":"东部各县在周末的洪水中受灾惨重。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"锤子;榔头","en":"A hammer is a tool that consists of a heavy piece of metal at the end of a handle. It is used, for example, to hit nails into a piece of wood or a wall, or to break things into pieces.","ex":{"en":"He used a hammer and chisel to chip away at the wall.","cn":"他用榔头和凿子铲墙。"}},{"pos":"VERB 动词","cn":"用锤击;锤打","en":"If you hammer an object such as a nail, you hit it with a hammer.","ex":{"en":"To avoid damaging the tree, hammer a wooden peg into the hole","cn":"为了不毁坏树，用锤子将一个木栓钉进洞里。"}},{"pos":"VERB 动词","cn":"（反复）敲打","en":"If you hammer on a surface, you hit it several times in order to make a noise, or to emphasize something you are saying when you are angry.","ex":{"en":"We had to hammer and shout before they would open up","cn":"我们不停地拍门、叫喊，他们才开了门。"}},{"pos":"VERB 动词","cn":"强行灌输;反复强调","en":"If you hammer something such as an idea into people or you hammer at it, you keep repeating it forcefully so that it will have an effect on people.","ex":{"en":"He hammered it into me that I had not suddenly become a rotten goalkeeper","cn":"他反复告诉我，我并没有一下子变成个差劲的守门员。"}},{"pos":"VERB 动词","cn":"猛烈攻击;大力批评;严厉惩罚","en":"If you say that someone hammers another person, you mean that they attack, criticize, or punish the other person severely.","ex":{"en":"The report hammers the private motorist","cn":"该报告严词谴责了那个私家车司机。"}},{"pos":"V-PASSIVE 被动动词","cn":"（因税收政策变化、经济不景气等）使（企业）受到打击","en":"If you say that businesses are being hammered, you mean that they are being unfairly harmed, for example by a change in taxes or by bad economic conditions.","ex":{"en":"Look at the numbers of small businesses that are being hammered unmercifully","cn":"看看有多少小企业正在遭受无情的打击。"}},{"pos":"VERB 动词","cn":"（在体育比赛中）使惨败，大败","en":"In sports, if you say that one player or team hammered another, you mean that the first player or team defeated the second completely and easily.","ex":{"en":"He hammered the young Austrian player in four straight sets.","cn":"他直落4局轻取年轻的奥地利对手。"}},{"pos":"VERB 动词","cn":"（通常指因恐惧而心脏）快速跳动","en":"If someone's heart is hammering, it is beating very fast, usually because they are frightened.","ex":{"en":"My heart was hammering. The footsteps had stopped outside my door.","cn":"我的心怦怦直跳。脚步声已停在我的门外。"}},{"pos":"N-COUNT 可数名词","cn":"（机械设备中的）锤状物;（枪上的）击铁;(钢琴的）音槌","en":"In machines and instruments, a hammer is a part that hits another part. For example, in a gun the hammer causes the explosion which makes the bullet shoot out of it, and in a piano the hammers hit the strings and cause the sounds."},{"pos":"N-COUNT 可数名词","cn":"（田径运动中所掷的）链球","en":"In athletics, a hammer is a heavy weight on a piece of wire, which the athlete throws as far as possible.","ex":{"en":"Events like the hammer and the discus are not traditional crowd-pullers in the West.","cn":"掷链球和铁饼等在西方算不上传统的受欢迎项目。"}},{"pos":"PHRASE 短语","cn":"满腔热情地;劲头十足地","en":"If you say that someone was going at something hammer and tongs, you mean that they were doing it with great enthusiasm or energy.","ex":{"en":"He loved gardening. He went at it hammer and tongs as soon as he got back from work","cn":"他酷爱侍弄花草。只要下班一回到家，他就兴冲冲地忙活起来。"}},{"pos":"PHRASE 短语","cn":"被拍卖","en":"If you say that something goes, comes, or is under the hammer, you mean that it is going to be sold at an auction.","ex":{"en":"Ian Fleming's original unpublished notes are to go under the hammer at London auctioneers Sotheby's.","cn":"伊恩·弗莱明未出版的原版笔记将在伦敦的苏富比拍卖行进行拍卖。"}},{"pos":"","cn":"","en":"相关词组：hammer away hammer in hammer out"}]},"examples":[{"en":"( figurative ) The decision is a hammer blow for the steel industry.","cn":"这一决定对于钢铁业是一个沉重的打击。"},{"en":"Our team was hammered 5-1.","cn":"我队以 1:5 的悬殊比分败北。"}]},"hail":{"oxford":{"phon":"heɪl","pos":"verb","senses":[{"en":"to describe somebody/something as being very good or special, especially in newspapers, etc.","cn":"赞扬（或称颂）…为（尤用于报章等）","g":"[transitive, usually passive]","ex":{"en":"The conference was hailed as a great success.","cn":"会议被称颂为一次巨大的成功。"}},{"en":"to signal to a taxi or a bus, in order to get the driver to stop","cn":"招手叫（出租车或公共汽车）","g":"[transitive]","ex":{"en":"to hail a taxi/cab","cn":"打手势叫出租车"}},{"en":"to call to somebody in order to say hello to them or attract their attention","cn":"跟…打招呼；向…喊","g":"[transitive]","lab":"literary","ex":{"en":"A voice hailed us from the other side of the street.","cn":"街对面有个声音招呼我们。"}},{"en":"when it hails, small balls of ice fall like rain from the sky","cn":"下雹","g":"[intransitive]","ex":{"en":"It's hailing!","cn":"正下着冰雹！"}},{"en":"small balls of ice that fall like rain","cn":"雹；冰雹","g":"[uncountable]","ex":{"en":"We drove through hail and snow.","cn":"我们顶着冰雹和大雪开车。"},"pos":"noun"},{"en":"a large number or amount of something that is aimed at somebody in order to harm them","cn":"一阵像冰雹般袭来的事物；雹子般的一阵","g":"[singular]","ex":{"en":"a hail of arrows/bullets","cn":"一阵乱箭／弹雨"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"赞扬，称颂（人、事件或成就）","en":"If a person, event, or achievement is hailed as important or successful, they are praised publicly.","ex":{"en":"Faulkner has been hailed as the greatest American novelist of his generation","cn":"福克纳被誉为他那一代人中最伟大的美国小说家。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"雹子;冰雹","en":"Hail consists of small balls of ice that fall like rain from the sky.","ex":{"en":"...a sharp short-lived storm with heavy hail.","cn":"一阵短暂的大雹暴"}},{"pos":"VERB 动词","cn":"下雹;下冰雹","en":"When it hails, hail falls like rain from the sky.","ex":{"en":"It started to hail, huge great stones.","cn":"开始下雹，而且是很大的雹子。"}},{"pos":"N-SING 单数名词","cn":"雹子般的一阵","en":"A hail of things, usually small objects, is a large number of them that hit you at the same time and with great force.","ex":{"en":"The victim was hit by a hail of bullets","cn":"受害者被一阵弹雨击中。"}},{"pos":"VERB 动词","cn":"（人）生于，来自","en":"Someone who hails from a particular place was born there or lives there.","ex":{"en":"I hail from Brighton","cn":"我来自布赖顿。"}},{"pos":"VERB 动词","cn":"（人或物）来自","en":"If someone or something hails from a particular background, they come from it.","ex":{"en":"He hails from an affluent background","cn":"他出身于一个富有的家庭。"}},{"pos":"VERB 动词","cn":"招呼;喊","en":"If you hail someone, you call to them.","ex":{"en":"Jill saw him and hailed him","cn":"吉尔看到了他，并和他打招呼。"}},{"pos":"VERB 动词","cn":"招呼，叫（出租车）","en":"If you hail a taxi, you wave at it in order to stop it because you want the driver to take you somewhere.","ex":{"en":"I hurried away to hail a taxi.","cn":"我赶紧去叫出租车。"}},{"pos":"CONVENTION 惯用语","cn":"致意;致敬","en":"Hail is used as a word of greeting.","ex":{"en":"Hail to the new champion Bengali D'Albret.","cn":"向新科冠军本·贾利·达阿尔布雷致敬。"}}]},"media":{"uk":"media/uk/hail__gb_1.mp3","us":"media/us/hail__us_1.mp3"},"examples":[{"en":"Teenager Matt Brown is being hailed a hero for saving a young child from drowning.","cn":"因救起一名溺水儿童，少年马特 · 布朗被誉为英雄。"},{"en":"The conference was hailed as a great success.","cn":"会议被称颂为一次巨大的成功。"}]},"hair":{"media":{"img":["media/pic/hair_comp.jpg","media/thumb/ponytail.jpg"],"uk":"media/uk/hair__gb_1.mp3","us":"media/us/hair__us_1.mp3"},"oxford":{"phon":"heə(r)","pos":"noun","senses":[{"en":"the substance that looks like a mass of fine threads growing on a person's head","cn":"头发","g":"[uncountable]","lab":"North American English also","ex":{"en":"She has long dark hair.","cn":"她留着长长的黑发。"}},{"en":"hair growing on the body of a person or an animal","cn":"（人或动物身上的）毛","g":"[uncountable]","ex":{"en":"body/facial/pubic hair","cn":"体毛；脸毛；阴毛"}},{"en":"a piece of hair from a person or an animal","cn":"（一根）毛，头发","g":"[countable]","ex":{"en":"There's a hair in my soup.","cn":"我的汤里有根毛。"}},{"en":"having the type of hair mentioned","cn":"有…毛发（或头发）的","ex":{"en":"dark-haired","cn":"黑发的"}},{"en":"a thing that looks like a fine thread growing on the leaves and stems of some plants","cn":"（植物叶、茎上的）茸毛","g":"[countable]"},{"en":"a 'rock musical' play (1967) about hippies. It opened in New York and a year later in London. It was criticized (and attracted audiences) because in one scene the actors were naked and because the characters were against the Vietnam War and thought that drugs were fun. The songs include Let the Sunshine In and The Age of Aquarius. A film version appeared in 1979.","cn":"头发：关于嬉皮士的摇滚音乐剧（1967）。它在纽约开业，一年后在伦敦开业。它受到批评（并吸引了观众），因为在一个场景中，演员是赤裸裸的，并且因为角色反对越战，并认为毒品很有趣。歌曲包括《放进阳光》和《水瓶座的时代》。电影版本出现在1979年。","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"头发","en":"Your hair is the fine threads that grow in a mass on your head.","ex":{"en":"I wash my hair every night","cn":"我每晚都洗头。"}},{"pos":"N-VAR 可变名词","cn":"毛发;汗毛;体毛","en":"Hair is the short, fine threads that grow on different parts of your body.","ex":{"en":"The majority of men have hair on their chest","cn":"大多数男子长有胸毛。"}},{"pos":"N-VAR 可变名词","cn":"（动物的）毛;（马的）鬃，鬣","en":"Hair is the threads that cover the body of an animal such as a dog, or make up a horse's mane and tail.","ex":{"en":"I am allergic to cat hair.","cn":"我对猫毛过敏。"}},{"pos":"N-COUNT 可数名词","cn":"（昆虫、植物上的）茸毛","en":"Hairs are short, very fine threads that grow on some insects and plants.","ex":{"en":"The stinging nettle has a square stem and little hairs.","cn":"荨麻长有四方茎和细小茸毛。"}},{"pos":"PHRASE 短语","cn":"彻底放松;玩个痛快;无拘无束","en":"If you let your hair down, you relax completely and enjoy yourself.","ex":{"en":"...the world-famous Oktoberfest, a time when everyone in Munich really lets their hair down.","cn":"全球闻名的啤酒节，一个让所有身在慕尼黑的人都尽情放松的节日"}},{"pos":"PHRASE 短语","cn":"使…毛骨悚然","en":"Something that makes your hair stand on end shocks or frightens you very much.","ex":{"en":"This was the kind of smile that made your hair stand on end.","cn":"这是那种让人不寒而栗的微笑。"}},{"pos":"PHRASE 短语","cn":"非常整洁;衣冠楚楚","en":"If you say that someone has not a hair out of place, you are emphasizing that they are extremely smart and neatly dressed.","ex":{"en":"She had a lot of make-up on and not a hair out of place.","cn":"她化了浓妆，精致得让人挑不出一丝瑕疵。"}},{"pos":"PHRASE 短语","cn":"面不改色;毫不惊慌;泰然自若","en":"If you say that someone faced with a shock or a problem does not turn a hair, you mean that they do not show any surprise or fear, and remain completely calm.","ex":{"en":"No one seems to turn a hair at the thought of the divorced Princess marrying.","cn":"似乎没有人对离异的公主再婚感到丝毫地吃惊。"}},{"pos":"PHRASE 短语","cn":"在细节上过分纠缠","en":"If you say that someone is splitting hairs, you mean that they are making unnecessary distinctions between things when the differences between them are so small they are not important.","ex":{"en":"Don't split hairs. You know what I'm getting at.","cn":"别钻牛角尖了。你知道我指什么。"}}]},"examples":[{"en":"( informal ) I'll be down in a minute. I'm doing (= brushing, arranging, etc.) my hair.","cn":"我马上就下来。我在梳头呢。"},{"en":"I'm having my hair cut this afternoon.","cn":"我今天下午要去理发。"}]},"has":{"oxford":{"phon":"hɑː","pos":"exclamation","senses":[{"en":"the sound that people make when they are surprised or pleased or when they have discovered sth （","cn":"惊奇、高兴或有所发现时用）哈"},{"en":"the word for the sound that people make when they laugh （","cn":"笑声）哈"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Has is the third person singular of the present tense of have."}]},"media":{"uk":"media/uk/has__gb_1.mp3","us":"media/us/has__us_1.mp3"}},"hay":{"oxford":{"phon":"heɪ","pos":"noun","senses":[{"en":"grass that has been cut and dried and is used as food for animals","cn":"（用作饲料的）干草，草料","ex":{"en":"a bale of hay","cn":"一大捆干草"}},{"en":"a small amount of money","cn":"少量的钱","lab":"North American English, informal，，"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（作饲料用的）干草","en":"Hay is grass which has been cut and dried so that it can be used to feed animals.","ex":{"en":"...bales of hay.","cn":"一捆捆干草"}},{"pos":"PHRASE 短语","cn":"趁太阳好晒草;抓紧有利时机;不失良机","en":"If you say that someone is making hay or is making hay while the sun shines, you mean that they are taking advantage of a situation that is favourable to them while they have the chance to.","ex":{"en":"We knew that war was coming, and were determined to make hay while we could.","cn":"我们知道战争即将爆发，决心要趁早抓住有利时机。"}}]},"media":{"uk":"media/uk/hay__gb_1.mp3","us":"media/us/hay__us_1.mp3"},"examples":[{"en":"a bale of hay","cn":"一大捆干草"}]},"hard-won":{"oxford":{"phon":"ˌhɑːd ˈwʌn","pos":"adjective","senses":[{"en":"that you only get after fighting or working hard for it","cn":"经奋斗（或努力）得到的；来之不易的","ex":{"en":"She was not going to give up her hard-won freedom so easily.","cn":"她不会这么轻易地放弃得来不易的自由。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"来之不易的;努力争取的","en":"If you describe something that someone has gained or achieved as hard-won, you mean that they worked hard to gain or achieve it.","ex":{"en":"The dispute could destroy Australia's hard-won reputation for industrial stability.","cn":"这场纠纷可能会让澳大利亚劳资关系稳定这一来之不易的名声毁于一旦。"}}]},"media":{"uk":"media/uk/hard_won_1_gb_1.mp3","us":"media/us/hard_won_1_us_1.mp3"},"examples":[{"en":"She was not going to give up her hard-won freedom so easily.","cn":"她不会这么轻易地放弃得来不易的自由。"},{"en":"her hard-won independence","cn":"她得来不易的独立"}]},"happily":{"media":{"uk":"media/uk/happily__gb_1.mp3","us":"media/us/happily__us_1.mp3"},"oxford":{"phon":"ˈhæpɪli","pos":"adverb","senses":[{"en":"in a cheerful way; with feelings of pleasure","cn":"快乐地；高兴地；满足地","ex":{"en":"children playing happily on the beach","cn":"在海滩上嬉戏的孩子们"}},{"en":"by good luck","cn":"幸运地","ex":{"en":"Happily, the damage was only slight.","cn":"所幸的是，损伤不大。"}},{"en":"willingly","cn":"欣然；情愿地","ex":{"en":"I'll happily help, if I can.","cn":"如果我能帮忙，我倒很乐意。"}},{"en":"in a way that is suitable or appropriate","cn":"合适地；恰当地","lab":"formal","ex":{"en":"This suggestion did not fit very happily with our existing plans.","cn":"这个建议与我们目前的计划不太契合。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"幸运地;幸运的是","en":"You can add happily to a statement to indicate that you are glad that something happened or is true.","ex":{"en":"Happily, his neck injuries were not serious","cn":"很幸运，他脖子上的伤并不严重。"}}]},"examples":[{"en":"And they all lived happily ever after (= used as the end of a fairy tale ).","cn":"从此他们都过着幸福美满的生活（用作童话故事的结尾）。"},{"en":"This suggestion did not fit very happily with our existing plans.","cn":"这个建议与我们目前的计划不十分契合。"}]},"hardens":{"oxford":{"phon":"ˈhɑːdn","pos":"verb","senses":[{"en":"to become or make sth become firm, stiff or solid （","cn":"使）变硬，硬化"},{"en":"if your voice, face, etc. hardens , or you harden it, it becomes more serious or severe （","cn":"使声音、面孔等）更严肃，更严厉"}]}},"handsome":{"media":{"uk":"media/uk/handsome__gb_1.mp3","us":"media/us/handsome__us_1.mp3"},"oxford":{"phon":"ˈhænsəm","pos":"adjective","senses":[{"en":"attractive","cn":"英俊的；漂亮的；有魅力的","ex":{"en":"He had an interesting and rather handsome face.","cn":"他有一张有趣且相当英俊的脸。"}},{"en":"attractive, with large strong features rather than small light ones","cn":"健美的","ex":{"en":"a tall, handsome woman","cn":"一位高个头的健美女子"}},{"en":"beautiful to look at","cn":"美观的；悦目的","ex":{"en":"a handsome horse/house/city","cn":"漂亮的马／房子／城市"}},{"en":"large in amount or quantity","cn":"数量大的","ex":{"en":"They sold the house two years later at a handsome profit.","cn":"两年后他们卖了那所房子，获得一大笔利润。"}},{"en":"generous","cn":"大方的；慷慨的；气量大的","ex":{"en":"She paid him a handsome compliment.","cn":"她大大赞扬了他一番。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（男子）漂亮的，英俊的，帅气的","en":"A handsome man has an attractive face with regular features. →see usage note at:","ex":{"en":"...a tall, dark, handsome sheep farmer.","cn":"高个子、黑皮肤的英俊养羊人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（女子）端庄健美的","en":"A handsome woman has an attractive appearance with features that are large and regular rather than small and delicate.","ex":{"en":"...an extremely handsome woman with a beautiful voice.","cn":"有着甜美嗓音的非常健美的女子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（金额）相当大的，可观的，优厚的","en":"A handsome sum of money is a large or generous amount.","ex":{"en":"They will make a handsome profit on the property.","cn":"他们会从这片地产中赚取丰厚的利润。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（建筑物、庭院等）宽敞而美观的，堂皇的，雄伟的","en":"A place such as a building or garden that is handsome is large and well made with an attractive appearance.","ex":{"en":"...the ports of Dubrovnik and Zadar, with their handsome Renaissance buildings.","cn":"拥有雄伟的文艺复兴时期建筑的杜布罗夫尼克港和扎达尔港"}},{"pos":"ADJ 形容词","cn":"（获胜）比分悬殊的，遥遥领先的","en":"If someone has a handsome win or a handsome victory, they get many more points or votes than their opponent.","ex":{"en":"The opposition won a handsome victory in the election.","cn":"反对党在竞选中以高票获胜。"}}]},"examples":[{"en":"He was aptly described as ‘ tall, dark, and handsome ’.","cn":"他被恰如其分地描述为“高大黝黑、相貌堂堂”。"},{"en":"He's the most handsome man I've ever met.","cn":"他是我见过的最俊美的男子。"}]},"hates":{"oxford":{"phon":"hæt","pos":"noun","senses":[{"en":"a covering made to fit the head, often with a brim , (= a flat edge that sticks out) and worn out of doors （","cn":"常指带檐的）帽子"},{"en":"( informal ) a position or role, especially an official or professional role, when you have more than one such role （","cn":"双重的）职位，角色（尤指官职或职业角色）"}]},"media":{"img":["media/pic/hats_comp.jpg","media/thumb/panama.jpg"],"uk":"media/uk/hat__gb_1.mp3","us":"media/us/hat__us_1.mp3"}},"haves":{"media":{"uk":"media/uk/haves__gb_1.mp3","us":"media/us/haves__us_1.mp3"},"oxford":{"phon":"","pos":"noun","senses":[{"en":"people who have enough money and possessions","cn":"有钱人；富人"}]},"examples":[{"en":"the division between the haves and the have-nots","cn":"富人和穷人之间的差异"},{"en":"the widening gap between the haves and the have-nots","cn":"不断扩大的贫富差距"}],"collins":{"senses":[{"pos":"","cn":"","en":"haves and have-nots→see: ;"}]}},"hands-on":{"oxford":{"phon":"ˌhændz ˈɒn","pos":"adjective","senses":[{"en":"doing something rather than just talking about it","cn":"动手的；实际操作的","ex":{"en":"hands-on computer training","cn":"计算机操作培训"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（经历或工作）亲身实践的，实际操作的","en":"Hands-on experience or work involves actually doing a particular thing, rather than just talking about it or getting someone else to do it.","ex":{"en":"Ninety-nine per cent of primary pupils now have hands-on experience of computers","cn":"现在99%的小学生都亲手操作过电脑。"}}]},"media":{"uk":"media/uk/hands_on_1_gb_1.mp3","us":"media/us/hands_on_1_us_1.mp3"},"examples":[{"en":"to gain hands-on experience of industry","cn":"获得勤劳工作的实际经验"},{"en":"a hands-on style of management","cn":"事必躬亲的管理方式"}]},"havoc":{"media":{"uk":"media/uk/havoc__gb_1.mp3","us":"media/us/havoc__us_1.mp3"},"oxford":{"phon":"ˈhævək","pos":"noun","senses":[{"en":"a situation in which things are seriously damaged, destroyed or very confused","cn":"灾害；祸患；浩劫","ex":{"en":"The floods caused havoc throughout the area.","cn":"洪水给整个地区带来了灾害。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"大破坏;大毁坏;大混乱","en":"Havoc is great disorder, and confusion.","ex":{"en":"Rioters caused havoc in the centre of the town.","cn":"暴乱分子在市中心制造了极大混乱。"}},{"pos":"PHRASE 短语","cn":"给…造成混乱（或破坏）","en":"If one thing plays havoc with another or wreaks havoc on it, it prevents it from continuing or functioning as normal, or damages it.","ex":{"en":"Drug addiction soon played havoc with his career","cn":"毒瘾很快就毁掉了他的事业。"}}]},"examples":[{"en":"Continuing strikes are beginning to play havoc with the national economy.","cn":"持续的罢工开始严重破坏国家经济。"},{"en":"The floods caused havoc throughout the area.","cn":"洪水给整个地区带来了灾害。"}]},"halfpenny":{"media":{"uk":"media/uk/halfpenny__gb_1.mp3","us":"media/us/halfpenny__us_1.mp3"},"oxford":{"phon":"ˈhɑːfpeni","pos":"noun","senses":[{"en":"a British coin in use until 1971, worth half a penny. There were 480 halfpennies in a pound.","cn":"半便士硬币（1971 年前使用的英国硬币，480 半便士硬币为一英镑）"},{"en":"a British coin in use between 1971 and 1984, worth half a penny. There were 200 halfpennies in a pound.","cn":"半便士硬币（1971 至 1984 年间使用的英国硬币，200 半便士硬币为一英镑）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（英国旧币制中的）半便士硬币","en":"A halfpenny was a small British coin which was worth half a penny."}]}},"happen":{"media":{"uk":"media/uk/happen__gb_1.mp3","us":"media/us/happen__us_1.mp3"},"oxford":{"phon":"ˈhæpən","pos":"verb","senses":[{"en":"to take place, especially without being planned","cn":"（尤指偶然）发生，出现","g":"[intransitive]","ex":{"en":"You'll never guess what's happened!","cn":"你根本猜不到出了什么事！"}},{"en":"to take place as the result of something","cn":"（作为结果）出现，发生","g":"[intransitive]","ex":{"en":"She pressed the button but nothing happened.","cn":"她按下按钮，但什么反应也没有。"}},{"en":"to do or be something by chance","cn":"碰巧；恰好","g":"[transitive]","ex":{"en":"She happened to be out when we called.","cn":"我们打电话时她刚巧不在。"}},{"en":"used to tell somebody something, especially when you are disagreeing with them or annoyed by what they have said","cn":"（向对方表示异议或不悦等）","g":"[transitive]","ex":{"en":"That happens to be my mother you're talking about!","cn":"你们谈论的是我母亲！"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（偶然）发生，出现","en":"Something that happens occurs or is done without being planned.","ex":{"en":"We cannot say for sure what will happen","cn":"我们无法确定会发生什么事。"}},{"pos":"VERB 动词","cn":"（作为结果）发生，产生","en":"If something happens, it occurs as a result of a situation or course of action.","ex":{"en":"She wondered what would happen if her parents found her","cn":"她不知道如果父母找到自己会有什么结果。"}},{"pos":"VERB 动词","cn":"（尤指不愉快的事）发生（在…身上）;(某人)遭到;遇到","en":"When something, especially something unpleasant, happens to you, it takes place and affects you.","ex":{"en":"If we had been spotted at that point, I don't know what would have happened to us","cn":"如果当时我们被发现了，我不知道会有什么后果。"}},{"pos":"VERB 动词","cn":"碰巧;凑巧","en":"If you happen to do something, you do it by chance. If it happens that something is the case, it occurs by chance.","ex":{"en":"We happened to discover we had a friend in common","cn":"我们凑巧发现我们有一个共同的朋友。"}},{"pos":"PHRASE 短语","cn":"碰巧，恰恰（尤引出令人意外的事）","en":"You use as it happens in order to introduce a statement, especially one that is rather surprising.","ex":{"en":"She called Amy to see if she had any idea of her son's whereabouts. As it happened, Amy had.","cn":"她打电话给埃米，看她是否知道自己儿子的行踪。埃米还真就知道。"}}]},"examples":[{"en":"‘Sorry — I've spilt some wine.’ ‘Never mind. These things happen.’ “","cn":"对不起，我弄洒了些酒。” “没关系。这种事在所难免。”"},{"en":"What happens if nobody comes to the party?","cn":"要是没有人来参加聚会，会怎么样呢？"}]},"hard-boiled":{"oxford":{"phon":"ˌhɑːd ˈbɔɪld","pos":"adjective","senses":[{"en":"boiled until the inside is hard","cn":"煮老的；煮硬的"},{"en":"not showing much emotion","cn":"不动感情的；不流露情感的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（蛋）煮得老的，煮硬的","en":"A hard-boiled egg has been boiled in its shell until the whole of the inside is solid."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）不动感情的，强硬的","en":"You use hard-boiled to describe someone who is tough and does not show much emotion.","ex":{"en":"She's hard-boiled, tough and funny.","cn":"她冷峻、坚韧而风趣。"}}]},"media":{"uk":"media/uk/hard_boiled_1_gb_1.mp3","us":"media/us/hard_boiled_1_us_1.mp3"},"examples":[{"en":"a hard-boiled marketing executive","cn":"一位强悍的营销主管"}]},"hadn't":{"media":{"uk":"media/uk/hadn_t_1_gb_1.mp3","us":"media/us/hadn_t_1_us_1.mp3"},"oxford":{"phon":"ˈhædnt","pos":"short form","senses":[{"en":"had not","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（had not 的常用口语形式）","en":"Hadn't is the usual spoken form of 'had not'."}]},"examples":[{"en":"If I hadn’t seen it myself, I’d never have believed it.","cn":""}]},"harness":{"media":{"uk":"media/uk/harness__gb_1.mp3","us":"media/us/harness__us_1.mp3","img":["media/ldoce/img/abseiling.jpg"]},"oxford":{"phon":"ˈhɑːnɪs","pos":"noun","senses":[{"en":"a set of narrow pieces of leather and metal pieces that is put around the head and body of an animal, especially a horse, so that the animal can be controlled and fastened to a carriage, etc.","cn":"挽具；马具","ex":{"en":"The sight of horses in harness hauling timber was common a hundred years ago.","cn":"一百年前，套着挽具的马匹拉木材的情景很常见。"}},{"en":"a set of straps (= long narrow pieces of a strong material) for fastening something to a person’s body or to keep them from moving off or falling","cn":"（用于人，起固定或保护作用的）系带，保护带","ex":{"en":"She fastened the safety harness tightly around her waist before starting the descent.","cn":"她把安全带牢牢地系在腰部后才开始下降。"}},{"en":"to put a harness on a horse or other animal; to attach a horse or other animal to something with a harness","cn":"给（马等）上挽具；用挽具把…套到…上","lab":"figurative","ex":{"en":"to harness a horse","cn":"给马上挽具"},"pos":"verb"},{"en":"to control and use the force or strength of something to produce power or to achieve something","cn":"控制，利用（以产生能量等）","ex":{"en":"attempts to harness the sun’s rays as a source of energy","cn":"利用日光作为能源的尝试"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"控制（情感）;利用（自然力）","en":"If you harness something such as an emotion or natural source of energy, you bring it under your control and use it.","ex":{"en":"...the movement's ability to harness the anger of all Ukrainians","cn":"该运动之疏解所有乌克兰人怒气的能力"}},{"pos":"N-COUNT 可数名词","cn":"（系在身上用以携带装备或限制其移动的）系带，背带","en":"A harness is a set of straps which fit under a person's arms and fasten round their body in order to keep a piece of equipment in place or to prevent the person moving from a place."},{"pos":"N-COUNT 可数名词","cn":"马具;挽具","en":"A harness is a set of leather straps and metal links fastened round a horse's head or body so that the horse can have a carriage, cart, or plough fastened to it."},{"pos":"VERB 动词","cn":"给（马等）套上挽具","en":"If a horse or other animal is harnessed, a harness is put on it, especially so that it can pull a carriage, cart, or plough.","ex":{"en":"On Sunday the horses were harnessed to a heavy wagon for a daylong ride over the Border.","cn":"星期天，马匹被套在一辆沉重的马车上，准备踏上长达一天的穿越边境之旅。"}},{"pos":"PHRASE 短语","cn":"互相配合;通力合作","en":"People or things who are working in harness are working together in order to achieve a particular aim.","ex":{"en":"At Opera North he will be in harness with Paul Daniel, the conductor appointed music director last year.","cn":"在北方歌剧公司，他将和去年指挥指定的音乐总监保罗·丹尼尔通力合作。"}},{"pos":"PHRASE 短语","cn":"（常指停止工作一段时间后）正常工作的","en":"If you say that someone is in harness, you mean that they are working, often after a period of not working.","ex":{"en":"You can rest for three or four months and then the longing for work will return and you will be right back in harness.","cn":"你可以休息三四个月，然后又会开始渴望工作，并能很快回到正常的工作状态。"}}]},"examples":[{"en":"( figurative ) In some areas, the poor feel harnessed to their jobs.","cn":"有些地区的穷人感觉终身被套牢在他们的工作上。"},{"en":"We must harness the skill and creativity of our workforce.","cn":"我们必须尽量发挥全体职工的技能和创造力。"}]},"handles":{"oxford":{"phon":"ˈhændl","pos":"verb","senses":[{"en":"to deal with a situation, a person, an area of work or a strong emotion","cn":"处理，应付（局势、人、工作或感情）"},{"en":"to touch, hold or move sth with your hands （","cn":"用手）触，拿，搬动"}]}},"haircut":{"media":{"uk":"media/uk/haircut__gb_1.mp3","us":"media/us/haircut__us_1.mp3"},"oxford":{"phon":"ˈheəkʌt","pos":"noun","senses":[{"en":"the act of somebody cutting your hair","cn":"理发","ex":{"en":"You need a haircut.","cn":"你该理发了。"}},{"en":"the style in which somebody’s hair is cut","cn":"发型；发式","lab":"North American English also","ex":{"en":"What do you think of my new haircut?","cn":"你觉得我的新发型怎么样？"}},{"en":"a reduction in an amount of money or in the value of an asset","cn":"资金量减少；资产价值下降","ex":{"en":"The Prime Minister says he'd like to see banks take a bigger haircut from bad loans.","cn":"首相称他希望看到银行以更大力度削减不良贷款。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"理发","en":"If you have a haircut, someone cuts your hair for you.","ex":{"en":"Your hair is all right; it's just that you need a haircut.","cn":"你的头发还好;不过你该理发了。"}},{"pos":"N-COUNT 可数名词","cn":"发式;发型","en":"A haircut is the style in which your hair has been cut.","ex":{"en":"Who's that guy with the funny haircut?","cn":"那个发型怪怪的家伙是谁？"}}]},"examples":[{"en":"What do you think of my new haircut?","cn":"你觉得我的新发型怎么样？"},{"en":"I see you've had a haircut.","cn":"我看得出你理发了。"}]},"hardened":{"oxford":{"phon":"ˈhɑːdn","pos":"verb","senses":[{"en":"to become or make sth become firm, stiff or solid （","cn":"使）变硬，硬化"},{"en":"if your voice, face, etc. hardens , or you harden it, it becomes more serious or severe （","cn":"使声音、面孔等）更严肃，更严厉"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"硬心肠的;冷酷无情的;麻木不仁的","en":"If you describe someone as hardened, you mean that they have had so much experience of something bad or unpleasant that they are no longer affected by it in the way that other people would be.","ex":{"en":"...hardened criminals.","cn":"冷酷无情的罪犯"}}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41hardened.mp3","us":"media/ldoce/hwd/ame/f/laadhardened.mp3"}},"hare":{"oxford":{"phon":"heə(r)","pos":"noun","senses":[{"en":"an animal like a large rabbit with very strong back legs, that can run very fast","cn":"野兔"},{"en":"to run or go somewhere very fast","cn":"飞跑；疾走","ex":{"en":"He hared away down the street.","cn":"他沿着街道狂奔而去。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"野兔","en":"A hare is an animal like a rabbit but larger with long ears, long legs, and a small tail."},{"pos":"VERB 动词","cn":"飞跑;飞奔","en":"If you hare off somewhere, you go there very quickly.","ex":{"en":"...an over-protective mother who keeps haring off to ring the babysitter.","cn":"过于爱护孩子而不断地跑去给保姆打电话的母亲"}}]},"media":{"img":["media/pic/rabbit_hare.jpg","media/thumb/hare.jpg"],"uk":"media/uk/hare__gb_1.mp3","us":"media/us/hare__us_1.mp3"},"examples":[{"en":"He hared off down the road.","cn":"他沿着马路飞快地跑掉了。"}]},"ha":{"oxford":{"phon":"hɑː","pos":"exclamation","senses":[{"en":"the sound that people make when they are surprised or pleased, or when they have discovered something","cn":"（惊奇、高兴或有所发现时用）哈","ex":{"en":"Ha! It serves you right!","cn":"哈！你活该！"}},{"en":"the word for the sound that people make when they laugh","cn":"（笑声）哈"},{"en":"used to show that you do not think that something is funny","cn":"（认为某事并不可笑）","lab":"informal, ironic，，","ex":{"en":"Ha! Ha! Very funny! Now give me back my shoes.","cn":"哈！哈！真有意思！把我的鞋还给我。"}},{"en":"(in writing) hectare","cn":"（书写形式）公顷","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"See also:","cn":"（用在书面语中表示惊讶、生气或高兴）哈","en":"Ha is used in writing to represent a noise that people make to show they are surprised, annoyed, or pleased about something.","ex":{"en":"Ha! said Wren. Think I'd trust you?","cn":"“哈！”雷恩说，“你以为我会相信你？”"}}]},"media":{"uk":"media/uk/haar__gb_1.mp3","us":"media/us/haar__us_1.mp3"},"examples":[{"en":"Ha! Ha! Very funny! Now give me back my shoes.","cn":"哈！哈！真有意思！把我的鞋还给我。"},{"en":"Ha! I knew he was hiding something.","cn":"哈！我就知道他在隐瞒什么。"}]},"hard":{"media":{"uk":"media/uk/hard__gb_1.mp3","us":"media/us/hard__us_1.mp3"},"oxford":{"phon":"hɑːd","pos":"adjective","senses":[{"en":"difficult to do, understand or answer","cn":"难做的；难懂的；难以回答的","sc":"difficult","ex":{"en":"a hard choice/decision/question","cn":"艰难的选择／决定；难以回答的问题"}},{"en":"full of difficulty and problems, especially because of a lack of money","cn":"困苦的；艰苦的；艰难的","sc":"difficult","ex":{"en":"Times were hard at the end of the war.","cn":"战争后期生活很艰苦。"}},{"en":"needing or using a lot of physical strength or mental effort","cn":"耗费体力（或脑力）的；辛苦的","sc":"needing/using effort","ex":{"en":"It's hard work shovelling snow.","cn":"铲雪是个苦活儿。"}},{"en":"putting a lot of effort or energy into an activity","cn":"努力的；勤劳的","sc":"needing/using effort","ex":{"en":"She's a very hard worker.","cn":"她工作很卖力。"}},{"en":"done with a lot of strength or force","cn":"用力的；猛烈的","sc":"needing/using effort","ex":{"en":"He gave the door a good hard kick.","cn":"他狠狠踢了一下门。"}},{"en":"solid or stiff and difficult to bend or break","cn":"坚固的；坚硬的；结实的","sc":"solid/stiff","ex":{"en":"Wait for the concrete to go hard.","cn":"等待混凝土凝结。"}},{"en":"showing no kind feelings or sympathy","cn":"冷酷无情的；硬心肠的；无同情心的","sc":"without sympathy","ex":{"en":"My father was a hard man.","cn":"我父亲是个不讲情面的人。"}},{"en":"showing no signs of fear or weakness; ready to fight or compete","cn":"勇敢无畏的；不软弱退缩的","lab":"informal","sc":"not afraid","ex":{"en":"Come and get me if you think you're hard enough.","cn":"你要是觉得自己有种，就冲着我来吧。"}},{"en":"definitely true and based on information that can be proved","cn":"确凿的；可证实的；可靠的","g":"[only before noun]","sc":"facts/evidence","ex":{"en":"Is there any hard evidence either way?","cn":"不管正反，有什么确凿证据吗？"}},{"en":"very cold and severe","cn":"寒冷的；凛冽的","sc":"weather","ex":{"en":"It had been a hard winter.","cn":"那年的冬天特别冷。"}},{"en":"strongly alcoholic","cn":"酒精浓度高的；烈性的","g":"[only before noun]","lab":"informal","sc":"drink","ex":{"en":"hard liquor","cn":"烈酒"}},{"en":"containing calcium and other mineral salts that make mixing with soap difficult","cn":"硬的（含钙及镁等可溶性盐较多）","sc":"water","ex":{"en":"a hard water area","cn":"硬水区"}},{"en":"used to describe a letter c or g when pronounced as in ‘cat’ or ‘go’, rather than as in ‘city’ or ‘giant’","cn":"硬音的（如字母 c 或 g 在 cat 或 go 等词中的发音）","lab":"phonetics","sc":"consonants"},{"en":"with great effort; with difficulty","cn":"努力地；费力地；艰难地","sc":"with effort","ex":{"en":"to work hard","cn":"努力工作"},"pos":"adverb"},{"en":"with great force","cn":"猛力地；猛烈地","lab":"figurative","sc":"with force","ex":{"en":"Don't hit it so hard!","cn":"别这么用力打！"},"pos":"adverb"},{"en":"carefully and completely","cn":"认真而全面地；缜密地","sc":"carefully","ex":{"en":"to think hard","cn":"认真思考"},"pos":"adverb"},{"en":"heavily; a lot or for a long time","cn":"沉重地；大量地；长时间地","sc":"a lot","ex":{"en":"It was raining hard when we set off.","cn":"我们出发时正下着大雨。"},"pos":"adverb"},{"en":"at a sharp angle to the left/right","cn":"向左（或右）急转弯","sc":"left/right","ex":{"en":"Turn hard right at the next junction.","cn":"在下个路口处向右急转弯。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"硬的;坚硬的;坚固的","en":"Something that is hard is very firm and stiff to touch and is not easily bent, cut, or broken.","ex":{"en":"He shuffled his feet on the hard wooden floor","cn":"他拖着脚在硬木地板上走动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难做的;困难的","en":"Something that is hard is very difficult to do or deal with.","ex":{"en":"It's hard to tell what effect this latest move will have","cn":"很难说最近这次行动会有什么结果。"}},{"pos":"ADV-GRADED 副词","cn":"努力地;使劲地","en":"If you work hard doing something, you are very active or work intensely, with a lot of effort.","ex":{"en":"I'll work hard. I don't want to let him down","cn":"我会努力工作，我不想让他失望。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"累人的;费力的;费劲的","en":"Hard work involves a lot of activity and effort.","ex":{"en":"Coping with three babies is very hard work","cn":"照顾3个宝宝是非常累人的活儿。"}},{"pos":"ADV-GRADED 副词","cn":"仔细地;认真地","en":"If you look, listen, or think hard, you do it carefully and with a great deal of attention.","ex":{"en":"He looked at me hard","cn":"他使劲盯着我看。"}},{"pos":"ADV-GRADED 副词","cn":"猛力地;用力地","en":"If you strike or take hold of something hard, you strike or take hold of it with a lot of force.","ex":{"en":"I kicked a dustbin very hard and broke my toe.","cn":"我狠狠地踢了一脚垃圾箱，结果脚趾骨折了。"}},{"pos":"ADV-GRADED 副词","cn":"强烈地;猛烈的;长时间地","en":"You can use hard to indicate that something happens intensely and for a long time.","ex":{"en":"I've never seen Terry laugh so hard","cn":"我从未见过特里如此放声大笑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷酷无情的;心肠硬的","en":"If a person or their expression is hard, they show no kindness or sympathy.","ex":{"en":"His father was a hard man","cn":"他的父亲是个冷酷无情的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"苛刻的;严厉的;不友善的","en":"If you are hard on someone, you treat them severely or unkindly.","ex":{"en":"Don't be so hard on him.","cn":"别对他太苛刻了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有害的;不利的","en":"If you say that something is hard on a person or thing, you mean it affects them in a way that is likely to cause them damage or suffering.","ex":{"en":"The grey light was hard on the eyes","cn":"光线暗淡对眼睛不利。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（生活、一段日子）艰难的，艰苦的","en":"If you have a hard life or a hard period of time, your life or that period is difficult and unpleasant for you.","ex":{"en":"It had been a hard life for her","cn":"对她而言，那是一段非常艰苦的生活。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常寒冷的;凛冽的","en":"A hard winter or a hard frost is a very cold one.","ex":{"en":"...a prolonged period of hard frost","cn":"漫长的强霜冻期"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（颜色）刺目的，晃眼的;（声音）刺耳的，难听的","en":"Hard colours or sounds are harsh or bright and unpleasant to see or hear.","ex":{"en":"The sea was a hard blue.","cn":"大海呈一片耀眼的蓝色。"}},{"pos":"ADJ 形容词","cn":"（证据、资料）可靠的，确凿的","en":"Hard evidence or facts are definitely true and do not need to be questioned.","ex":{"en":"He wanted more hard evidence","cn":"他想要更多确凿的证据。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（水质）硬的（指含钙化合物较多）","en":"Hard water contains a lot of calcium compounds that stop soap making bubbles and sometimes appear as a deposit in kettles and baths."},{"pos":"ADJ 形容词","cn":"（毒品）毒性强的，烈性的","en":"Hard drugs are very strong illegal drugs such as heroin or cocaine."},{"pos":"ADJ 形容词","cn":"（语音）发硬音的","en":"In phonetics, a hard sound is one such as 'c' or 'g' as pronounced in the words 'cat' or 'give', and not as in the words 'cinema' or 'general'."},{"pos":"PREP-PHRASE 短语介词","cn":"离…很近的","en":"If one thing is hard by another, it is very close to it.","ex":{"en":"Paradise Street was a short, crowded street near the railway station and hard by the factory.","cn":"天堂街是火车站附近一条拥挤的小街道，离该工厂很近。"}},{"pos":"PHRASE 短语","cn":"受到不公平待遇的;委屈的","en":"If you feel hard done by, you feel that you have not been treated fairly.","ex":{"en":"The hall porter was feeling hard done by at having to extend his shift.","cn":"酒店行李搬运工因为被迫延长当班时间而愤愤不平。"}},{"pos":"PHRASE 短语","cn":"困难的;艰难的","en":"If you say that something is hard going, you mean it is difficult and requires a lot of effort.","ex":{"en":"The talks had been hard going at the start.","cn":"会谈从一开始就举步维艰。"}},{"pos":"PHRASE 短语","cn":"受到沉重打击的;受严重影响的","en":"To be hard hit by something means to be affected very severely by it.","ex":{"en":"California's been particularly hard hit by the recession.","cn":"加利福尼亚受经济衰退的影响尤为严重。"}},{"pos":"PHRASE 短语","cn":"佯装不感兴趣;故意摆谱","en":"If someone plays hard to get, they pretend not to be interested in another person or in what someone is trying to persuade them to do.","ex":{"en":"I wanted her and she was playing hard to get.","cn":"我想得到她，但她却故意装出不感兴趣的样子。"}},{"pos":"PHRASE 短语","cn":"十分困难的;处于困境的","en":"If someone is hard put to do something or, in British English if they are hard pushed to do something, they have great difficulty doing it.","ex":{"en":"Mr Morton is undoubtedly cleverer than Mr Kirkby, but he will be hard put to match his popularity.","cn":"莫顿先生无疑比柯克比先生更聪明，但他将很难像柯克比先生那样受人欢迎。"}},{"pos":"PHRASE 短语","cn":"为…而非常苦恼（或难受）；因…而沮丧","en":"If you take something hard, you are very upset or depressed by it.","ex":{"en":"Maybe I just took it too hard.","cn":"可能我真的对此事太过耿耿于怀。"}}]},"examples":[{"en":"She won't listen to my advice so she'll just have to learn the hard way.","cn":"她不肯听我的忠告，所以只好吃了苦头才知道厉害。"},{"en":"Looking at a computer screen all day can be very hard on the eyes.","cn":"成天盯着计算机屏幕可能会对眼睛造成严重损害。"}]},"habitats":{"oxford":{"phon":"ˈhæbɪtæt","pos":"noun","senses":[{"en":"the place where a particular type of animal or plant is normally found （","cn":"动植物的）生活环境，栖息地"}]},"media":{"uk":"media/uk/habitat__gb_1.mp3","us":"media/us/habitat__us_1.mp3"}},"habitat":{"media":{"uk":"media/uk/habitat__gb_1.mp3","us":"media/us/habitat__us_1.mp3"},"oxford":{"phon":"ˈhæbɪtæt","pos":"noun","senses":[{"en":"the place where a particular type of animal or plant is normally found","cn":"（动植物的）生活环境，栖息地","lab":"especially British English","ex":{"en":"The panda's natural habitat is the bamboo forest.","cn":"大熊猫的天然栖息地是竹林。"}},{"en":"a group of shops selling furniture and other things for the home like cushions, china and lamps. It was started in Britain in 1964 by Terence Conran, with some shops opening later in other countries, including France, Spain and Germany. It was especially successful in the 1960s and 1970s when it was one of the first companies to sell original designs of furniture, etc. that many people could afford. By 2011 many of the shops had been closed.","cn":"住所：一组商店，出售家具和其他家居用品，例如靠垫，瓷器和灯具。它于1964年在英国由Terence Conran创立，后来在法国，西班牙和德国等其他国家开设了一些商店。它在1960年代和1970年代特别成功，当时它是最早销售许多人买得起的家具等原始设计的公司之一。到2011年，许多商店都关门了。","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（动植物的）生境，栖生地，产地","en":"The habitat of an animal or plant is the natural environment in which it normally lives or grows.","ex":{"en":"In its natural habitat, the hibiscus will grow up to 25ft","cn":"在原生境中，木槿能长到25英尺高。"}}]},"examples":[{"en":"The panda's natural habitat is the bamboo forest.","cn":"大熊猫的天然栖息地是竹林。"},{"en":"the destruction of wildlife habitat","cn":"野生动植物生存环境的破坏"}]},"half":{"media":{"uk":"media/uk/half__gb_1.mp3","us":"media/us/half__us_1.mp3"},"oxford":{"phon":"hɑːf","pos":"noun","senses":[{"en":"either of two equal parts into which something is or can be divided","cn":"一半；半","ex":{"en":"two and a half kilos (= 2½)","cn":"两公斤半"}},{"en":"either of two periods of time into which a sports game, concert, etc. is divided","cn":"（比赛、音乐会等的）半场，半局","ex":{"en":"No goals were scored in the first half.","cn":"上半场没有得分。"}},{"en":"one of the defending players in hockey or rugby whose position is between those who play at the front of a team and those who play at the back","cn":"（曲棍球或橄榄球）前卫","lab":"North American English"},{"en":"one of the two attacking players in american football whose position is behind the quarterback and next to the full backs","cn":"（美式足球的）半卫","lab":"North American English"},{"en":"the position a half back plays at (also called a tailback in american football)","cn":"半卫的位置","g":"[uncountable]","lab":"North American English"},{"en":"half a pint (= 0.568 of a litre in the UK and some other countries, and 0.473 of a litre in the US) of beer or a similar drink","cn":"（啤酒等饮料的）半品脱","lab":"British English, informal，，","ex":{"en":"Two halves of bitter, please.","cn":"请来两杯半品脱的苦啤酒。"}},{"en":"an amount equal to half of something/somebody","cn":"半数","ex":{"en":"I'll see you in half an hour.","cn":"半小时后见。"},"pos":"determiner, pronoun"},{"en":"the largest part of something","cn":"绝大部分（时间、乐趣、麻烦等）","ex":{"en":"Half the time you don't even listen to what I say.","cn":"你大部分时间甚至没听我说的话。"},"pos":"determiner, pronoun"},{"en":"to the extent of half","cn":"到一半程度；半","ex":{"en":"The glass was half full.","cn":"玻璃杯半满。"},"pos":"adverb"},{"en":"partly","cn":"部分地","ex":{"en":"The chicken was only half cooked.","cn":"鸡只煮了半熟。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"FRACTION 分数词","cn":"半;二分之一","en":"Half of an amount or object is one of two equal parts that together make up the whole number, amount, or object.","ex":{"en":"They need an extra two and a half thousand pounds to complete the project","cn":"他们还需要2,500英镑才能完成该项目。"}},{"pos":"ADV 副词","cn":"部分地;在某种程度上;有点","en":"You use half to say that something is only partly the case or happens to only a limited extent.","ex":{"en":"His eyes were half closed","cn":"他双眼半闭。"}},{"pos":"N-COUNT 可数名词","cn":"（足球、橄榄球、篮球比赛等的）半场，半时，半局","en":"In games such as football, rugby, and basketball, matches are divided into two equal periods of time which are called halves.","ex":{"en":"The only goal was scored by Jakobsen early in the second half.","cn":"唯一的一粒进球是由雅各布森在下半场刚开始时打进的。"}},{"pos":"N-COUNT 可数名词","cn":"（啤酒、苹果酒等的）半品脱","en":"A half is half a pint of a drink such as beer or cider.","ex":{"en":"...a half of lager and a sandwich.","cn":"半品脱淡啤酒和一份三明治"}},{"pos":"N-COUNT 可数名词","cn":"(儿童乘坐公共汽车或火车时的）半（价）票","en":"A half is a half-price bus or train ticket for a child."},{"pos":"ADV 副词","cn":"一半…血统地","en":"You use half to say that someone has parents of different nationalities. For example, if you are half German, one of your parents is German but the other is not.","ex":{"en":"She was half Italian and half English.","cn":"她是半意大利半英国血统。"}},{"pos":"PREP-PHRASE 短语介词","cn":"（时间）…点半","en":"You use half past to refer to a time that is thirty minutes after a particular hour.","ex":{"en":"'What time were you planning lunch?'—'Half past twelve, if that's convenient.'","cn":"“你打算什么时候吃午饭？”“如果方便的话，12点半。”"}},{"pos":"PREP 介词","cn":"同 half past","en":"Half means the same as half past .","ex":{"en":"They are supposed to be here at about half four.","cn":"他们应该在4点半左右到达这里。"}},{"pos":"ADV 副词","cn":"（用于形容词前，表示强调或夸张）非常，极其","en":"You can use half before an adjective describing an extreme quality, as a way of emphasizing and exaggerating something.","ex":{"en":"He felt half dead with tiredness","cn":"他已经累得半死不活了。"}},{"pos":"ADV 副词","cn":"（有时用在否定句中，表示非常肯定的意思）","en":"Half is sometimes used in negative statements, with a positive meaning, to emphasize a particular fact or quality. For example, if you say 'he isn't half lucky', you mean that he is very lucky.","ex":{"en":"You don't half sound confident","cn":"你听起来非常有信心。"}},{"pos":"ADV 副词","cn":"一点也不;差得远","en":"You use not half or not half as to show that you do not think something is as good or impressive as it is meant to be.","ex":{"en":"You're not half the man you think you are","cn":"你根本不是你自己想象的那种人。"}},{"pos":"PHRASE 短语","cn":"非常…的;更…的;非同寻常的","en":"When you use an expression such as a problem and a half or a meal and a half, you are emphasizing that your reaction to it is either very favourable or very unfavourable.","ex":{"en":"It becomes clear that Montgomerie has a job and half on his hands.","cn":"很显然，蒙哥马利手头有一大堆事情要做。"}},{"pos":"PHRASE 短语","cn":"妻子;丈夫;另一半","en":"If you talk about your better half or your other half you mean your wife, your husband, or the person of the opposite sex that you live with.","ex":{"en":"I was worried that my career, my children and my other half might become too much to cope with.","cn":"我担心我的事业、我的孩子们和我的那口子可能会让我应付不过来。"}},{"pos":"PHRASE 短语","cn":"以一半;一半地","en":"If you increase something by half, half of the original amount is added to it. If you decrease it by half, half of the original amount is taken away from it.","ex":{"en":"The number of 7 year olds who read poorly has increased by half over the past 5 years","cn":"不识字的7岁儿童的人数在过去5年里增加了一半。"}},{"pos":"PHRASE 短语","cn":"做事不认真;做事马虎","en":"If you say that someone never does things by halves, you mean that they always do things very thoroughly.","ex":{"en":"In Italy they rarely do things by halves. Designers work thoroughly, producing the world's most wearable clothes in the most beautiful fabrics.","cn":"在意大利，人们很少马虎从事。设计师们精益求精，用最美丽的布料制造出世界上最适合穿着的衣服。"}},{"pos":"PHRASE 短语","cn":"（两人）平均分摊，平分（费用）","en":"If two people go halves, they divide the cost of something equally between them.","ex":{"en":"He's constantly on the phone to his girlfriend. We have to go halves on the phone bill which drives me mad.","cn":"他总和女友煲电话粥。令我抓狂的是电话费可是我们俩平摊的。"}},{"pos":"","cn":"","en":"half the battle→see: ; half an ear→see: ; too clever by half→see: ;"}]},"examples":[{"en":"‘It sounds very difficult.’ ‘ You don't know the half of it. ’ “","cn":"这事听起来很难。” “你还未了解更困难的一面呢。”"},{"en":"You're expecting twins? Well, you never did do anything by halves.","cn":"你要生对双胞胎？唔，你做事倒从来不会只做一半。"}]},"halves":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"to share the cost of something between two people or groups","cn":""},{"en":"if two people go halves , they each pay half of the cost of something they are buying together","cn":""}]},"media":{"uk":"media/uk/halves__gb_1.mp3","us":"media/us/halves__us_1.mp3"}},"have":{"media":{"uk":"media/uk/have__gb_1.mp3","us":"media/us/have__us_1.mp3"},"oxford":{"phon":"həv","pos":"verb","senses":[{"en":"to own, hold or possess something","cn":"有；持有；占有","lab":"British English","sc":"own/hold","ex":{"en":"He had a new car and a boat.","cn":"他有一辆新车和一条船。"}},{"en":"be made up of","cn":"由…组成","sc":"consist of","ex":{"en":"In 2018 the party had 10 000 members.","cn":"2018 年时该党有 1 万名党员。"}},{"en":"to show a quality or feature","cn":"显示出，带有（性质、特征）","sc":"quality/feature","ex":{"en":"The ham had a smoky flavour.","cn":"这火腿散发着一种烟熏的香味。"}},{"en":"to show a particular quality by your actions","cn":"（通过行动）表现出（品质）","sc":"quality/feature","ex":{"en":"Surely she didn't have the nerve to say that to him?","cn":"她一定没有胆量跟他这样说吧？"}},{"en":"used to show a particular relationship","cn":"（表示关系）有","sc":"relationship","ex":{"en":"He's got three children.","cn":"他有三个孩子。"}},{"en":"to be able to make use of something because it is available","cn":"能用","sc":"something available","ex":{"en":"Have you got time to call him?","cn":"你有时间给他打电话吗？"}},{"en":"to be in a position where you ought to do something","cn":"有责任（或义务）","sc":"should/must","ex":{"en":"We have a duty to care for the refugees.","cn":"我们有义务关怀这些难民。"}},{"en":"to be in a position of needing to do something","cn":"须要，有必要（做某事）","sc":"should/must","ex":{"en":"I've got a lot of homework tonight.","cn":"我今晚有很多家庭作业要做。"}},{"en":"to let a feeling or thought come into your mind","cn":"感到；想到","lab":"informal","sc":"feeling/thought","ex":{"en":"He had the strong impression that someone was watching him.","cn":"他强烈地感觉到有人在监视他。"}},{"en":"to suffer from an illness or a disease","cn":"患病；得病；染病","sc":"illness","ex":{"en":"I've got a headache.","cn":"我头痛。"}},{"en":"to hold somebody/something in the way mentioned","cn":"抓住；握着；支承","sc":"hold","ex":{"en":"She'd got him by the collar.","cn":"她抓住了他的衣领。"}},{"en":"to place or keep something in a particular position","cn":"使放在；使保持（在）","sc":"put/keep in a position","ex":{"en":"Mary had her back to me.","cn":"玛丽背对着我。"}},{"en":"to experience something","cn":"经受；经历；经验","sc":"experience","ex":{"en":"I went to a few parties and had a good time.","cn":"我参加了几次聚会，过得很愉快。"}},{"en":"to organize or hold an event","cn":"组织；举办","sc":"event","ex":{"en":"Let's have a party.","cn":"我们办一次聚会吧。"}},{"en":"to eat, drink or smoke something","cn":"吃；喝；吸（烟等）","sc":"eat/drink/smoke","ex":{"en":"to have breakfast/lunch/dinner","cn":"吃早饭；吃午饭；吃正餐"}},{"en":"to perform a particular action","cn":"进行（活动）","lab":"British English","sc":"do something","ex":{"en":"I had a swim to cool down.","cn":"我游了泳，凉快凉快。"}},{"en":"to give birth to somebody/something","cn":"生；生产","sc":"give birth","ex":{"en":"She's going to have a baby.","cn":"她快生孩子了。"}},{"en":"to produce a particular effect","cn":"产生（效果）","sc":"effect","ex":{"en":"His paintings had a strong influence on me as a student.","cn":"我当学生时，他的画对我产生过强烈的影响。"}},{"en":"to receive something from somebody","cn":"收到；接到","lab":"North American English","sc":"receive","ex":{"en":"I had a letter from my brother this morning.","cn":"我今天早晨收到了弟弟的一封信。"}},{"en":"to be given something; to have something done to you","cn":"得到；接受；受到","sc":"receive","ex":{"en":"I'm having treatment for my back problem.","cn":"我正接受背部疾患的治疗。"}},{"en":"to experience the effects of somebody’s actions","cn":"接受（某人行为的效果）","sc":"receive","ex":{"en":"We have orders coming in from all over the world.","cn":"我们接到来自世界各地的订单。"}},{"en":"to suffer the effects of what somebody else does to you","cn":"蒙受（他人所为的后果）","sc":"have something done","ex":{"en":"She had her bag stolen.","cn":"她的包被偷了。"}},{"en":"to cause something to be done for you by somebody else","cn":"让（他人）为你做（某事）","sc":"have something done","ex":{"en":"You've had your hair cut!","cn":"你理发了！"}},{"en":"to tell or arrange for somebody to do something for you","cn":"要（或安排）（某人）做（某事）","lab":"informal","sc":"have something done","ex":{"en":"He had the bouncers throw them out of the club.","cn":"他叫保安人员把他们轰出了俱乐部。"}},{"en":"to cause somebody/something to be in a particular state; to make somebody react in a particular way","cn":"使处于（某状态）；使做出（某种反应）","sc":"put somebody/something in a condition","ex":{"en":"I want to have everything ready in good time.","cn":"我要求一切都得准时备妥。"}},{"en":"to be with somebody","cn":"同（某人）在一起","sc":"be with","ex":{"en":"She had some friends with her.","cn":"她和几个朋友在一起。"}},{"en":"to take care of somebody/something in your home, especially for a limited period","cn":"（尤指短期在自己家中）照料，照看","g":"[no passive]","sc":"guests","ex":{"en":"We're having the kids for the weekend.","cn":"这个周末孩子们要到我们家来由我们照料。"}},{"en":"to entertain somebody in your home","cn":"（在家中）招待，款待","g":"[no passive]","sc":"guests","ex":{"en":"We had some friends to dinner last night.","cn":"我们昨晚请了几位朋友来家里吃饭了。"}},{"en":"to allow something; to accept something without complaining","cn":"允许；容忍","sc":"allow","ex":{"en":"I'm sick of your rudeness—I won't have it any longer!","cn":"你的无礼我已经受够了，我不会再容忍下去了！"}},{"en":"to put somebody at a disadvantage in an argument","cn":"辩过；胜过","lab":"informal","sc":"in argument","ex":{"en":"You've got me there. I hadn't thought of that.","cn":"你把我问住了。我没想过这个。"}},{"en":"to have sex with somebody","cn":"（与某人）发生性关系","lab":"slang","sc":"sex","ex":{"en":"He had her in his office.","cn":"他在他的办公室里和她搞上了。"}},{"en":"to trick or cheat somebody","cn":"欺骗；蒙骗","g":"[usually passive]","lab":"informal","sc":"trick","ex":{"en":"I'm afraid you've been had.","cn":"恐怕你上当了。"}},{"en":"to take or accept somebody for a particular role","cn":"让，接受（某人承担职务）","g":"[no passive]","sc":"for a job","ex":{"en":"Who can we have as treasurer?","cn":"我们让谁来主管财务？"}},{"en":"used with the past participle to form perfect tenses","cn":"（与过去分词连用构成完成时）","lab":"formal","ex":{"en":"I've finished my work.","cn":"我干完我的活儿了。"},"pos":"auxiliary verb"}]},"collins":{"senses":[{"pos":"AUX 助动词","cn":"(have 和 has 与过去分词连用构成动词的现在完成时)","en":"You use the forms have and has with a past participle to form the present perfect tense of verbs.","ex":{"en":"Alex has already gone","cn":"亚历克斯已经走了。"}},{"pos":"AUX 助动词","cn":"(had 与过去分词连用构成动词的过去完成时)","en":"You use the form had with a past participle to form the past perfect tense of verbs.","ex":{"en":"When I met her, she had just returned from a job interview","cn":"我遇见她时，她刚参加完一场求职面试回来。"}},{"pos":"AUX 助动词","cn":"(用于附加疑问句中)","en":"Have is used in question tags.","ex":{"en":"You haven't sent her away, have you?","cn":"你还没有把她送走，是吗？"}},{"pos":"AUX 助动词","cn":"(用于对带有 have,has 或 had 的句子作肯定或否定回答)","en":"You use have when you are confirming or contradicting a statement containing 'have', 'has', or 'had', or answering a question.","ex":{"en":"'You'd never seen the Marilyn Monroe film?' — 'No I hadn't.'","cn":"“你从未看过玛丽莲·梦露的电影？”“对，没有。”"}},{"pos":"AUX 助动词","cn":"（having 和过去分词连用，所引导的分句中提到的动作发生在另一个动作开始之前）","en":"The form having with a past participle can be used to introduce a clause in which you mention an action which had already happened before another action began.","ex":{"en":"He arrived in San Francisco, having left New Jersey on January 19th","cn":"1月19日离开新泽西后，他到了旧金山。"}},{"pos":"VERB 动词","cn":"（have 后接名词代替该名词作动词的用法，描述某一动作或事件）","en":"You can use have followed by a noun to talk about an action or event, when it would be possible to use the same word as a verb. For example, you can say 'I had a look at the photos' instead of 'I looked at the photos.'","ex":{"en":"I went out and had a walk around","cn":"我出去在周围散了一会儿步。"}},{"pos":"VERB 动词","cn":"（在英语口语或书面语中，have可以和很多名词连用以代替某个具体的动词，描述某一动作或事件）","en":"In normal spoken or written English, people use have with a wide range of nouns to talk about actions and events, often instead of a more specific verb. For example people are more likely to say 'we had ice cream' or 'he's had a shock' than 'we ate ice cream', or 'he's suffered a shock'.","ex":{"en":"Come and have a meal with us tonight","cn":"今晚来和我们一起吃饭吧。"}},{"pos":"VERB 动词","cn":"有;拥有","en":"You use have to say that someone or something owns a particular thing, or when you are mentioning one of their qualities or characteristics.","ex":{"en":"Oscar had a new bicycle","cn":"奥斯卡有一辆新自行车。"}},{"pos":"VERB 动词","cn":"有…要（做）；必须（做）","en":"If you have something to do, you are responsible for doing it or must do it.","ex":{"en":"He had plenty of work to do","cn":"他有很多工作要做。"}},{"pos":"VERB 动词","cn":"（用于代替 there is, 表示某事物存在或发生了某事）","en":"You can use have instead of 'there is' to say that something exists or happens. For example, you can say 'you have no alternative' instead of 'there is no alternative', or 'he had a good view from his window' instead of 'there was a good view from his window'.","ex":{"en":"He had two tenants living with him","cn":"有两位房客和他同住。"}},{"pos":"VERB 动词","cn":"（使）保持;（使）处于","en":"If you have something such as a part of your body in a particular position or state, it is in that position or state.","ex":{"en":"Mary had her eyes closed","cn":"玛丽双目紧闭。"}},{"pos":"VERB 动词","cn":"请人做;让人做","en":"If you have something done, someone does it for you or you arrange for it to be done.","ex":{"en":"I had your rooms cleaned and aired","cn":"我请人打扫了你的房间并通了风。"}},{"pos":"VERB 动词","cn":"遭遇（不愉快的事）","en":"If someone has something unpleasant happen to them, it happens to them.","ex":{"en":"We had our money stolen","cn":"我们的钱被偷了。"}},{"pos":"VERB 动词","cn":"劝说;让;命令","en":"If you have someone do something, you persuade, cause, or order them to do it.","ex":{"en":"If you happen to talk to him, have him call me","cn":"如果你碰巧能和他说话，让他给我打个电话。"}},{"pos":"VERB 动词","cn":"抓住（某人身体的某部位）","en":"If someone has you by a part of your body, they are holding you there and they are trying to hurt you or force you to go somewhere.","ex":{"en":"When the police came, Larry had him by the ear and was beating his head against the pavement.","cn":"警方赶到时，拉里正揪着他的耳朵，把他的头往人行道上撞。"}},{"pos":"VERB 动词","cn":"（从某人那里）得到","en":"If you have something from someone, they give it to you.","ex":{"en":"You can have my ticket","cn":"我可以把我的票给你。"}},{"pos":"VERB 动词","cn":"患有（疾病、残疾）","en":"If you have an illness or disability, you suffer from it.","ex":{"en":"I had a headache","cn":"我头疼。"}},{"pos":"VERB 动词","cn":"生（孩子）/怀（孩子）","en":"If a woman has a baby, she gives birth to it. If she is having a baby, she is pregnant.","ex":{"en":"My wife has just had a baby boy","cn":"我妻子刚生了个男孩。"}},{"pos":"VERB 动词","cn":"不允许;不容忍","en":"You can use have in expressions such as 'I won't have it' or 'I'm not having that', to mean that you will not allow or put up with something.","ex":{"en":"She wanted to be alone. They wouldn't have it","cn":"她想一个人呆着。他们不允许。"}},{"pos":"PHRASE 短语","cn":"根据谣传/传说","en":"You can use has it in expressions such as 'rumour has it that' or 'as legend has it' when you are quoting something that you have heard, but you do not necessarily think it is true.","ex":{"en":"Rumour has it that tickets were being sold for £300","cn":"据谣传，票卖到了300英镑。"}},{"pos":"PHRASE 短语","cn":"跟…过不去;总想找…的茬儿","en":"If someone has it in for you, they do not like you and they want to make life difficult for you.","ex":{"en":"He's always had it in for the Dawkins family.","cn":"他老是跟道金斯一家过不去。"}},{"pos":"PHRASE 短语","cn":"深藏不露;有两下子","en":"If you have it in you, you have abilities and skills which you do not usually use and which only show themselves in a difficult situation.","ex":{"en":"'You were brilliant!' he said. 'I didn't know you had it in you.'","cn":"“你真厉害！”他说，“我不知道你还有这两下子。”"}},{"pos":"PHR-RECIP相互短语","cn":"和…发生性关系","en":"To have it off with someone or have it away with someone means to have sex with them.","ex":{"en":"He reckons she's having it off with the gardener.","cn":"他认为她和园丁有一腿。"}},{"pos":"PHRASE 短语","cn":"捉弄;戏弄","en":"If you are having someone on, you are pretending that something is true when it is not true, for example as a joke or in order to tease them.","ex":{"en":"Malone's eyes widened. 'You're having me on, Liam.'","cn":"马隆瞪大了双眼。“你在戏弄我吧，利亚姆。”"}},{"pos":"PHRASE 短语","cn":"和…讲个明白;和…争论出个结果","en":"If you have it out or have things out with someone, you discuss a problem or disagreement very openly with them, even if it means having an argument, because you think this is the best way to solve the problem.","ex":{"en":"Why not have it out with your critic, discuss the whole thing face to face?","cn":"为什么不和批评你的人讲个明白，面对面地把整件事情谈一谈呢？"}},{"pos":"","cn":"","en":"to be had→see: ; to have had it→see: ;"},{"pos":"PHR-MODAL 情态动词短语","cn":"需要;必须;不得不","en":"You use have to when you are saying that something is necessary or required, or must happen. If you do not have to do something, it is not necessary or required.","ex":{"en":"He had to go to Germany","cn":"他不得不去德国。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"肯定;一定","en":"You can use have to in order to say that you feel certain that something is true or will happen.","ex":{"en":"There has to be some kind of way out","cn":"一定会有某种解决办法的。"}}]},"examples":[{"en":"It was no surprise when she left him — everyone knew he had it coming to him.","cn":"她离开了他，这丝毫不奇怪。大家都知道是他自己造成的。"},{"en":"‘Does your brother have brown hair?’ ‘No, he’s got blond hair.’ “","cn":"你弟弟的头发是棕色的吗？” “不，他有一头金发。”"}]},"happening":{"media":{"uk":"media/uk/happening__gb_1.mp3","us":"media/us/happening__us_1.mp3"},"oxford":{"phon":"ˈhæpənɪŋ","pos":"noun","senses":[{"en":"an event; something that happens, often something unusual","cn":"事件；发生的事情（常指不寻常的）","g":"[usually plural]","ex":{"en":"There have been strange happenings here lately.","cn":"这儿最近发生了一些怪事。"}},{"en":"an artistic performance or event that is not planned","cn":"即兴艺术表演"},{"en":"where there is a lot of exciting activity; fashionable","cn":"热闹的；时髦的","ex":{"en":"a happening place","cn":"时髦的地方"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发生的事情;意外事件;难以解释的事","en":"Happenings are things that happen, often in a way that is unexpected or hard to explain.","ex":{"en":"The Budapest office plans to hire freelance reporters to cover the latest happenings.","cn":"布达佩斯办事处计划聘用自由撰稿记者来报道最近发生的一些事件。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热闹的;活跃的;新潮的","en":"If you describe something or someone as happening, you mean that they are exciting or lively, and involved in the newest fashions or trends.","ex":{"en":"...a definitive area-by-area guide to the hip and happening bands.","cn":"介绍各个地区新潮流行乐队的权威指南"}}]},"examples":[{"en":"There have been strange happenings here lately.","cn":"这儿最近发生了一些怪事。"},{"en":"a happening place","cn":"时髦的地方"}]},"handling":{"oxford":{"phon":"ˈhændlɪŋ","pos":"noun","senses":[{"en":"the way that somebody deals with or treats a situation, a person, an animal, etc.","cn":"（对形势、人、动物等的）处理，对付，对待","ex":{"en":"I was impressed by his handling of the affair.","cn":"他对此事的处理方式我甚感佩服。"}},{"en":"the action of touching, feeling or holding something with your hands","cn":"（手的）触摸，触摸感觉，握，拿","ex":{"en":"toys that can stand up to rough handling","cn":"经得起摔打的玩具"}},{"en":"the action of organizing or controlling something","cn":"组织；控制；管理","ex":{"en":"data handling on computer","cn":"计算机的数据处理"}},{"en":"the cost of dealing with an order, delivering goods, booking tickets, etc.","cn":"（订货、送货、订票等的）费用，手续费","ex":{"en":"a small handling charge","cn":"少许手续费"}},{"en":"the way in which a vehicle can be controlled by the driver","cn":"（车辆的）驾驶，操纵","ex":{"en":"a car designed for easy handling","cn":"为驾驶简便而设计的汽车"}},{"en":"the act or cost of transporting goods from one place to another","cn":"运输；运费","lab":"British English also"}]},"media":{"uk":"media/uk/handling__gb_1.mp3","us":"media/us/handling__us_1.mp3"},"examples":[{"en":"I was impressed by his handling of the affair.","cn":"他对此事的处理方式我甚感佩服。"},{"en":"a car designed for easy handling","cn":"为驾驶简便而设计的汽车"}]},"handicap":{"media":{"uk":"media/uk/handicap__gb_1.mp3","us":"media/us/handicap__us_1.mp3"},"oxford":{"phon":"ˈhændikæp","pos":"noun","senses":[{"en":"a permanent physical or mental condition that makes it difficult to do some things that most other people can do","cn":"生理缺陷；弱智；残疾","g":"[countable, uncountable]","lab":"old-fashioned, usually offensive，，","ex":{"en":"She was born with what was then called a handicap.","cn":"她生来就患有当时所谓的残疾。"}},{"en":"something that makes it difficult for somebody to do something","cn":"障碍；阻碍","g":"[countable]","ex":{"en":"Not speaking the language proved to be a bigger handicap than I'd imagined.","cn":"事实证明，不会讲这种语言所造成的障碍比我想象的大。"}},{"en":"a race or competition in which those who have most skill must run further, carry extra weight, etc. in order to give all those taking part an equal chance of winning; the disadvantage that is given to somebody you are competing against in such a race or competition","cn":"让赛，让步赛（使参赛的优势方跑得更远、增加负重等）；（让步赛中给优势方施加的）障碍，不利条件","g":"[countable]","lab":"sport"},{"en":"the number of strokes (= hits) over par (= the expected number of strokes for a good player) that a player usually needs to complete a course. Handicaps are used to give an advantage to weaker players so that competition is more equal when they play against stronger players.","cn":"差点（给弱者减少的杆数）","g":"[countable]","ex":{"en":"He plays off a handicap of 5.","cn":"他的让分盘为5。"}},{"en":"to make something more difficult for somebody to do","cn":"妨碍；阻碍","ex":{"en":"Smaller parties are seriously handicapped by the electoral system.","cn":"小党派受到这种选举制度的严重制约。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（生理或智力上的）残障，残疾","en":"A handicap is a physical or mental disability.","ex":{"en":"He lost his leg when he was ten, but learnt to overcome his handicap.","cn":"他10岁时失去了一条腿，但他学会了克服自己的残疾。"}},{"pos":"N-COUNT 可数名词","cn":"不利条件;障碍","en":"A handicap is an event or situation that places you at a disadvantage and makes it harder for you to do something.","ex":{"en":"She was away from school for 15 weeks, a handicap she could have done without","cn":"她有15周没上学，这给她带来了本不该有的障碍。"}},{"pos":"VERB 动词","cn":"妨碍;使不利","en":"If an event or a situation handicaps someone or something, it places them at a disadvantage.","ex":{"en":"Greater levels of stress may seriously handicap some students","cn":"压力的加重可能会给一些学生带来严重的负面影响。"}},{"pos":"N-COUNT 可数名词","cn":"（高尔夫运动中的）给弱者增加的杆数，差点","en":"In golf, a handicap is an advantage given to someone who is not a good player, in order to make the players more equal. As you improve, your handicap gets lower.","ex":{"en":"I see your handicap is down from 16 to 12.","cn":"我发现你的差点已从16杆降到了12杆。"}},{"pos":"N-COUNT 可数名词","cn":"（赛马比赛的）让步赛","en":"In horse racing, a handicap is a race in which some competitors are given a disadvantage of extra weight in an attempt to give everyone an equal chance of winning."}]},"examples":[{"en":"Not speaking the language proved to be a bigger handicap than I'd imagined.","cn":"事实证明不会讲这种语言造成的障碍比我所想像的大。"},{"en":"Despite her handicap, Jane is able to hold down a full-time job.","cn":"简尽管有生理缺陷，却能够保住一份全职工作。"}]},"hallucination":{"media":{"uk":"media/uk/hallucination__gb_1.mp3","us":"media/us/hallucination__us_1.mp3"},"oxford":{"phon":"həˌluːsɪˈneɪʃn","pos":"noun","senses":[{"en":"the fact of seeming to see or hear somebody/something that is not really there, especially because of illness or drugs","cn":"幻觉，幻视，幻听（尤指生病或吸毒所致）","g":"[countable, uncountable]","ex":{"en":"to have hallucinations","cn":"产生幻觉"}},{"en":"something that is seen or heard when it is not really there","cn":"幻视（或幻听）到的东西；幻觉；幻象","g":"[countable]","ex":{"en":"Was the figure real or just a hallucination?","cn":"那个人影是真的呢，还是幻象？"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（因生病或吸毒所致的）幻觉（体验）","en":"A hallucination is the experience of seeing something that is not really there because you are ill or have taken a drug.","ex":{"en":"The drug induces hallucinations at high doses","cn":"大剂量地服用该药会致幻。"}},{"pos":"N-COUNT 可数名词","cn":"（因生病或吸毒所见到的）幻象","en":"A hallucination is something that is not real that someone sees because they are ill or have taken a drug.","ex":{"en":"Perhaps the footprint was a hallucination.","cn":"脚印可能只是幻象。"}}]},"examples":[{"en":"Was the figure real or just a hallucination?","cn":"那个人影是真的呢，还是幻象？"},{"en":"High temperatures can cause hallucination.","cn":"高烧可使人产生幻觉。"}]},"harming":{"oxford":{"phon":"hɑːm","pos":"noun","senses":[{"en":"damage or injury that is caused by a person or an event","cn":"伤害；损害"},{"en":"used to suggest that it would be a good idea for sb to do sth （","cn":"做某事）不会对某人有坏处；不妨"}]}},"harshly":{"oxford":{"phon":"ˈhɑːʃli","pos":"adverb","senses":[{"en":"in a cruel, severe and unkind way","cn":"残酷的；严酷的；严厉的","ex":{"en":"She was treated very harshly.","cn":"她受到了苛刻的对待。"}},{"en":"in a way that is too strong and bright; in a way that is ugly or unpleasant to look at","cn":"强烈刺眼的；丑陋的","ex":{"en":"harshly lit supermarkets","cn":"灯光昏暗的超市"}},{"en":"in a way that is unpleasant to listen to","cn":"刺耳的；难听的","ex":{"en":"The bell sounded, ringing harshly in the quiet classroom.","cn":"铃声响起，在安静的教室里响起。"}},{"en":"in a way that is too strong and rough and likely to damage something","cn":"粗糙的；毛糙的；刺激性强的","ex":{"en":"The shovel scraped harshly over the floor.","cn":"铲子狠狠地刮过地板。"}}]},"media":{"uk":"media/uk/harshly__gb_1.mp3","us":"media/us/harshly__us_1.mp3"},"examples":[{"en":"She was treated very harshly.","cn":"她受到了苛刻的对待。"},{"en":"Alec laughed harshly.","cn":"亚历克刺耳地大笑。"}]},"hardship":{"media":{"uk":"media/uk/hardship__gb_1.mp3","us":"media/us/hardship__us_1.mp3"},"oxford":{"phon":"ˈhɑːdʃɪp","pos":"noun","senses":[{"en":"a situation that is difficult and unpleasant because you do not have enough money, food, clothes, etc.","cn":"艰难；困苦；拮据","ex":{"en":"economic/financial, etc. hardship","cn":"经济、财政等困难"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"艰难;艰苦;贫困","en":"Hardship is a situation in which your life is difficult or unpleasant, often because you do not have enough money.","ex":{"en":"Many people are suffering economic hardship","cn":"很多人正处于经济困难之中。"}}]},"examples":[{"en":"It was no hardship to walk home on such a lovely evening.","cn":"在这么一个宜人的傍晚步行回家一点也不辛苦。"},{"en":"People suffered many hardships during that long winter.","cn":"在那个漫长的冬季，人们吃了很多苦头。"}]},"harmful":{"oxford":{"phon":"ˈhɑːmfl","pos":"adjective","senses":[{"en":"causing damage or injury to somebody/something, especially to a person’s health or to the environment","cn":"（尤指对健康或环境）有害的，导致损害的","ex":{"en":"the harmful effects of alcohol","cn":"酒精的害处"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有害的;（尤指）有损健康的","en":"Something that is harmful has a bad effect on something else, especially on a person's health.","ex":{"en":"...the harmful effects of smoking","cn":"吸烟的危害"}}]},"media":{"uk":"media/uk/harmful__gb_1.mp3","us":"media/us/harmful__us_1.mp3"},"examples":[{"en":"Many household products are potentially harmful.","cn":"很多家用产品有潜在的危害。"},{"en":"Fruit juices can be harmful to children's teeth.","cn":"果汁可能损坏儿童的牙齿。"}]},"hands-off":{"oxford":{"phon":"ˌhændz ˈɒf","pos":"adjective","senses":[{"en":"dealing with people or a situation by not becoming involved and by allowing people to do what they want to","cn":"不介入的；放手的","ex":{"en":"a hands-off approach to staff management","cn":"不干涉的职员管理方法"}}]},"media":{"uk":"media/uk/hands_off_1_gb_1.mp3","us":"media/us/hands_off_1_us_1.mp3"},"examples":[{"en":"a hands-off approach to staff management","cn":"不干涉的职员管理方法"},{"en":"The government has a hands-off approach to the industry.","cn":"政府对这一行业采取不干涉的政策。"}]},"hardly":{"media":{"uk":"media/uk/hardly__gb_1.mp3","us":"media/us/hardly__us_1.mp3"},"oxford":{"phon":"ˈhɑːdli","pos":"adverb","senses":[{"en":"almost no; almost not; almost none","cn":"几乎不；几乎没有","ex":{"en":"There's hardly any tea left.","cn":"没有剩什么茶了。"}},{"en":"used especially after ‘can’ or ‘could’ and before the main verb, to emphasize that it is difficult to do something","cn":"（尤用于 can 或 could 之后，主要动词之前，强调做某事很难）","ex":{"en":"I can hardly keep my eyes open (= I'm almost falling asleep).","cn":"我困得都快睁不开眼了。"}},{"en":"used to suggest that something is unlikely or unreasonable or that somebody is silly for saying or doing something","cn":"（表示不大可能、不合理或愚蠢）","ex":{"en":"He is hardly likely to admit he was wrong.","cn":"他不大可能承认自己错了。"}},{"en":"used to say that something has just begun, happened, etc.","cn":"刚刚；才","lab":"formal","ex":{"en":"We can't stop for coffee now, we've hardly started.","cn":"现在不能停下来喝咖啡，我们才刚刚开始工作呢。"}}]},"collins":{"senses":[{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"（用于修正作出的陈述，表示不大可能）几乎不，几乎没有","en":"You use hardly to modify a statement when you want to emphasize that it is only a small amount or detail which makes it true, and that therefore it is best to consider the opposite statement as being true.","ex":{"en":"I hardly know you","cn":"我不太认识你。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"几乎不;几乎没有","en":"You use hardly in expressions such as hardly ever ,hardly any, and hardly anyone to mean almost never, almost none, or almost no-one.","ex":{"en":"We ate chips every night, but hardly ever had fish","cn":"我们每晚吃炸薯条，但几乎从不吃鱼。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"（用在否定句中构成双重否定，用于强调某事属实或经常发生）几乎不","en":"You use hardly before a negative statement in order to emphasize that something is usually true or usually happens.","ex":{"en":"Hardly a day goes by without a visit from someone.","cn":"几乎每天都有人来。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"（用于can之后，表示强调）很难","en":"When you say you can hardly do something, you are emphasizing that it is very difficult for you to do it.","ex":{"en":"I can hardly believe it's been over eight years since you used to go camping at Cedar Creek","cn":"我几乎无法相信现在距离你过去常常去松溪露营的日子已经有8年多了。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"（表示两件事情紧接着发生）刚刚，才","en":"If you say hardly had one thing happened when something else happened, you mean that the first event was followed immediately by the second.","ex":{"en":"He had hardly collected the papers on his desk when the door burst open","cn":"他刚收起桌上的文件，门就猛地开了。"}},{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"（表示希望听者或读者赞同自己）并不，丝毫不","en":"You use hardly to mean 'not' when you want to suggest that you are expecting your listener or reader to agree with your comment.","ex":{"en":"We have not seen the letter, so we can hardly comment on it","cn":"我们还没有看到这封信，所以无从发表意见。"}},{"pos":"CONVENTION 惯用语","cn":"（尤用于对不赞同的说法表示惊奇或不满）不可能，不会吧","en":"You use 'hardly' to mean 'no', especially when you want to express surprise or annoyance at a statement that you disagree with.","ex":{"en":"'They all thought you were marvellous!' —'Well, hardly.'","cn":"“他们都认为你很棒！”“哦，不可能吧！”"}}]},"examples":[{"en":"‘Couldn't you have just said no?’ ‘Well, hardly (= of course not), she's my wife's sister.’ “","cn":"你不能就说声不吗？” “喔，不可能，她是我小姨子。”"},{"en":"We can't stop for coffee now, we've hardly started.","cn":"现在不能停下来喝咖啡，我们刚刚才开始工作呢。"}]},"hardware":{"media":{"uk":"media/uk/hardware__gb_1.mp3","us":"media/us/hardware__us_1.mp3"},"oxford":{"phon":"ˈhɑːdweə(r)","pos":"noun","senses":[{"en":"the machines and electronic parts in a computer or other electronic system","cn":"硬件","lab":"computing","ex":{"en":"We supply computer hardware to businesses.","cn":"我们向公司提供计算机硬件。"}},{"en":"tools and equipment that are used in the house and garden","cn":"（家庭及园艺用）工具，设备，五金制品","lab":"also British English, old-fashioned，，","ex":{"en":"a hardware shop/store","cn":"五金店"}},{"en":"the equipment, machines and vehicles used to do something","cn":"硬件设备；机器；车辆","ex":{"en":"tanks and other military hardware","cn":"坦克和其他军事装备"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（计算机）硬件","en":"In computer systems, hardware refers to the machines themselves as opposed to the programs which tell the machines what to do."},{"pos":"N-UNCOUNT 不可数名词","cn":"重武器;军事装备","en":"Military hardware is the machinery and equipment that is used by the armed forces, such as tanks, aircraft, and missiles."},{"pos":"N-UNCOUNT 不可数名词","cn":"（家庭和园艺用的）五金制品，金属器具","en":"Hardware refers to tools and equipment that are used in the home and garden, for example saucepans, screwdrivers, and lawnmowers."}]},"examples":[{"en":"tanks and other military hardware","cn":"坦克和其他军事装备"},{"en":"a hardware shop","cn":"五金店"}]},"half-brother":{"oxford":{"phon":"ˈhɑːf brʌðə(r)","pos":"noun","senses":[{"en":"a person’s half-brother is a boy or man with either the same mother or the same father as they have","cn":"同母异父（或同父异母）的兄弟"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同母异父（或同父异母）兄弟","en":"Someone's half-brother is a boy or man who has either the same mother or the same father as they have."}]},"media":{"uk":"media/uk/half_brother_1_gb_1.mp3","us":"media/us/half_brother_1_us_1.mp3"}},"hastily":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"quickly, perhaps too quickly","cn":"飞快地﹔仓促地"}]},"examples":[{"en":"‘Don’t worry,’ Jenny added hastily. ‘I checked with Lizzie first.’ “","cn":"别担心﹐”珍妮赶紧补充﹐“我先和莉齐核实过了。”","src":"ld"},{"en":"a hastily arranged news conference","cn":"仓促安排的记者招待会","src":"ld"}],"media":{"uk":"media/uk/hastily__gb_1.mp3","us":"media/us/hastily__us_1.mp3"},"oxford":{"phon":"ˈheɪstɪli","pos":"adverb","senses":[{"en":"very quickly, because you are in a hurry, especially when this has bad results","cn":"非常快，因为你很着急，尤其是当有不好的结果时","ex":{"en":"She hastily changed the subject.","cn":"她匆匆换了个话题。"}},{"en":"too quickly, without giving enough thought","cn":"操之过急，不加思索","ex":{"en":"Perhaps I spoke too hastily.","cn":"也许我说话太过草率了。"}}]}},"handshake":{"media":{"uk":"media/uk/handshake__gb_1.mp3","us":"media/us/handshake__us_1.mp3"},"oxford":{"phon":"ˈhændʃeɪk","pos":"noun","senses":[{"en":"an act of shaking somebody’s hand with your own, used especially to say hello or goodbye or when you have made an agreement","cn":"握手","ex":{"en":"Fawcett gave me a hearty handshake.","cn":"福西特和我亲切地握了握手。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"握手","en":"If you give someone a handshake, you take their right hand with your own right hand and hold it firmly or move it up and down, as a sign of greeting or to show that you have agreed about something such as a business deal.","ex":{"en":"John smiled and gave him a hearty handshake","cn":"约翰微笑着和他热情地握手。"}}]},"examples":[{"en":"He greeted me with a handshake and a glass of wine.","cn":"他与我握手问候﹐并递给我一杯酒。"},{"en":"Her handshake was warm and firm.","cn":"她的握手温暖而有力。"}]},"haven't":{"media":{"uk":"media/uk/haven_t_1_gb_1.mp3","us":"media/us/haven_t_1_us_1.mp3"},"oxford":{"phon":"ˈhævnt","pos":"short form","senses":[{"en":"have not","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（have not 的常用口语形式）","en":"Haven't is the usual spoken form of 'have not'."}]}},"hamburger":{"media":{"uk":"media/uk/hamburger__gb_1.mp3","us":"media/us/hamburger__us_1.mp3"},"oxford":{"phon":"ˈhæmbɜːɡə(r)","pos":"noun","senses":[{"en":"beef cut into small pieces and made into a flat round shape that is then fried, often served in a bread roll","cn":"汉堡包；汉堡牛肉饼","g":"[countable]","lab":"British English also"},{"en":"beef that has been cut very small in a special machine","cn":"绞碎的牛肉；牛肉末","g":"[uncountable]","lab":"all North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"汉堡牛肉饼;汉堡包","en":"A hamburger is minced meat which has been shaped into a flat circle. Hamburgers are fried or grilled and then eaten, often in a bread roll."}]}},"handwriting":{"oxford":{"phon":"ˈhændraɪtɪŋ","pos":"noun","senses":[{"en":"writing that is done with a pen or pencil, not printed or typed","cn":"手写；书写","ex":{"en":"I didn't recognize the handwriting on the envelope.","cn":"我认不出信封上的字迹。"}},{"en":"a person’s particular style of writing in this way","cn":"笔迹；书法","ex":{"en":"I can't read his handwriting.","cn":"我看不懂他写的字。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"笔迹;字迹;笔法","en":"Your handwriting is your style of writing with a pen or pencil.","ex":{"en":"The address was in Anna's handwriting","cn":"地址是安娜的笔迹。"}}]},"media":{"uk":"media/uk/handwriting__gb_1.mp3","us":"media/us/handwriting__us_1.mp3"},"examples":[{"en":"I can't read his handwriting.","cn":"我看不懂他写的字。"},{"en":"I recognised her handwriting on the envelope.","cn":"我认出了信封上她的笔迹。"}]},"hamburgers":{"oxford":{"phon":"ˈhæmbɜːɡə(r)","pos":"noun","senses":[{"en":"finely chopped beef made into a flat round shape that is then fried, often served in a bread roll","cn":"汉堡包；汉堡牛肉饼"},{"en":"beef that has been finely chopped in a special machine","cn":"绞碎的牛肉；牛肉末"}]},"media":{"uk":"media/uk/hamburger__gb_1.mp3","us":"media/us/hamburger__us_1.mp3"}},"hatch":{"media":{"uk":"media/uk/hatch__gb_1.mp3","us":"media/us/hatch__us_1.mp3","img":["media/ldoce/img/hatch.jpg"]},"oxford":{"phon":"hætʃ","pos":"verb","senses":[{"en":"to come out of an egg","cn":"孵出；出壳","g":"[intransitive]","ex":{"en":"Ten chicks hatched (out) this morning.","cn":"今早有十只小鸡出壳了。"}},{"en":"to break open so that a young bird, fish, insect, etc. can come out","cn":"孵化；破壳","g":"[intransitive]","ex":{"en":"The eggs are about to hatch.","cn":"这些蛋就要孵化了。"}},{"en":"to make a young bird, fish, insect, etc. come out of an egg","cn":"使（小鸟、小鱼、小虫等）孵出","g":"[transitive]","ex":{"en":"The female must find a warm place to hatch her eggs.","cn":"雌性必须找个温暖的地方孵蛋。"}},{"en":"to create a plan or an idea, especially in secret","cn":"策划；（尤指）密谋","g":"[transitive]","ex":{"en":"Have you been hatching up a deal with her?","cn":"你是不是在和她密谋什么交易？"}},{"en":"an opening or a door in a ship, aircraft or spacecraft","cn":"（飞机或航天器的）舱门","ex":{"en":"The engineer was peering into the service hatch.","cn":"工程师正透过维修舱口往里看。"},"pos":"noun"},{"en":"an opening in a wall between two rooms, especially a kitchen and a dining room, through which food can be passed","cn":"（尤指厨房和餐厅之间供传递食物的）传菜窗口","ex":{"en":"a serving hatch","cn":"传递饭菜的窗口"},"pos":"noun"},{"en":"an opening or a door in a floor or ceiling","cn":"（地面或天花板的）开口，门，盖子","ex":{"en":"a hatch to the attic","cn":"通往阁楼的门"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"孵出;出壳","en":"When a baby bird, insect, or other animal hatches, or when it is hatched, it comes out of its egg by breaking the shell.","ex":{"en":"As soon as the two chicks hatch, they leave the nest burrow","cn":"两只小鸟一出壳就离开了巢穴。"}},{"pos":"V-ERG 及物/不及物动词","cn":"破壳;孵化;孵（蛋）","en":"When an egg hatches or when a bird, insect, or other animal hatches an egg, the egg breaks open and a baby comes out.","ex":{"en":"The eggs hatch after a week or ten days","cn":"蛋在1周或10天后孵化。"}},{"pos":"VERB 动词","cn":"筹划;策划;谋划","en":"If you hatch a plot or a scheme, you think of it and work it out.","ex":{"en":"He has accused opposition parties of hatching a plot to assassinate the Pope.","cn":"他指控反对党密谋暗杀教皇。"}},{"pos":"N-COUNT 可数名词","cn":"（船甲板上的）舱口，舱口盖","en":"A hatch is an opening in the deck of a ship, through which people or cargo can go. You can also refer to the door of this opening as a hatch.","ex":{"en":"He stuck his head up through the hatch","cn":"他从舱口探出头来。"}},{"pos":"N-COUNT 可数名词","cn":"（墙上或屋顶的）小窗口;（尤指厨房和餐厅间传递菜肴等的）小窗口，传菜口","en":"A hatch is an opening in a ceiling or a wall, especially between a kitchen and a dining room, which you can pass something such as food through."},{"pos":"PHRASE 短语","cn":"做好准备（迎接挑战）；未雨绸缪","en":"If someone battens down the hatches, they prepare themselves so that they will be able to survive a coming difficulty or crisis.","ex":{"en":"Many firms are battening down the hatches and preparing to ride out the storm.","cn":"很多公司正在加紧准备，希望能挺过这场暴风雨。"}},{"pos":"","cn":"","en":"相关词组：hatch out"}]},"examples":[{"en":"The female must find a warm place to hatch her eggs.","cn":"母的必须找个温暖的地方孵蛋。"},{"en":"Have you been hatching up a deal with her?","cn":"你是不是在和她密谋什么交易？"}]},"harmonizes":{"oxford":{"phon":"ˈhɑːmənaɪz","pos":"verb","senses":[{"en":"if two or more things harmonize with each other or one thing harmonizes with the other, the things go well together and produce an attractive result （","cn":"和某事物）协调，和谐"},{"en":"to make systems or rules similar in different countries or organizations","cn":"使（不同国家或组织的体制或规则）相一致；使协调"}]}},"hat":{"media":{"img":["media/pic/hats_comp.jpg","media/thumb/panama.jpg"],"uk":"media/uk/hat__gb_1.mp3","us":"media/us/hat__us_1.mp3"},"oxford":{"phon":"hæt","pos":"noun","senses":[{"en":"a piece of clothing made to fit the head, often with a brim (= a flat edge that sticks out), usually worn out of doors","cn":"（常指带檐的）帽子","ex":{"en":"a straw/woolly hat","cn":"草帽；毛线帽"}},{"en":"a position or role, especially an official or professional role, when you have more than one such role","cn":"（双重的）职位，角色（尤指官职或职业角色）","lab":"informal","ex":{"en":"I'm wearing two hats tonight—parent and teacher.","cn":"我今晚身兼两职，既是家长又是老师。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（常指带檐的）帽子","en":"A hat is a head covering, often with a brim round it, which is usually worn out of doors to give protection from the weather."},{"pos":"N-COUNT 可数名词","cn":"角色;职位;工作","en":"If you say that someone is wearing a particular hat, you mean that they are performing a particular role at that time. If you say that they wear several hats, you mean that they have several roles or jobs.","ex":{"en":"...putting on my nationalistic hat.","cn":"扮演我的民族主义角色"}},{"pos":"PHRASE 短语","cn":"毫不犹豫地;非常乐意地","en":"If you say that you are ready to do something at the drop of a hat, you mean that you are willing to do it immediately, without hesitating.","ex":{"en":"India is one part of the world I would go to at the drop of a hat.","cn":"印度是世界上我迫不及待想要去的一个地方。"}},{"pos":"PHRASE 短语","cn":"保守秘密","en":"If you tell someone to keep a piece of information under their hat, you are asking them not to tell anyone else about it.","ex":{"en":"Look, if I tell you something, will you promise to keep it under your hat?","cn":"喂，如果我告诉你一件事，你能答应保守秘密吗？"}},{"pos":"PHRASE 短语","cn":"陈腐;陈旧;老式;过时","en":"If you say that something or someone is old hat, you mean that they have existed or been known for a long time, and they have become uninteresting and boring.","ex":{"en":"The younger generation tell me that religion is 'old hat' and science has proved this.","cn":"年轻的一代告诉我，宗教已经过时了，科学已证明了这一点。"}},{"pos":"PHRASE 短语","cn":"募捐，凑份子（美国英语用 pass the hat）","en":"In British English, if you pass the hat around, you collect money from a group of people, for example in order to give someone a present. In American English, you just say pass the hat .","ex":{"en":"Professors are passing the hat to help staff in their department.","cn":"教授们正在凑钱帮助系里的同事。"}},{"pos":"PHRASE 短语","cn":"赞赏;钦佩","en":"If you say that you take your hat off to someone, you mean that you admire them for something that they have done.","ex":{"en":"I take my hat off to Mr Clarke for taking this action","cn":"我很钦佩克拉克先生的这一举动。"}},{"pos":"CONVENTION 惯用语","cn":"向…致敬","en":"If you say 'Hats off to someone', you are expressing admiration for them.","ex":{"en":"Hats off to them for supporting the homeless.","cn":"向他们帮扶无家可归者的善举致敬！"}},{"pos":"PHRASE 短语","cn":"（常指没落时）出乎意料地获取（胜利、成功）","en":"To pull something out of the hat means to do something unexpected which helps you to succeed, often when you are failing.","ex":{"en":"Southampton had somehow managed to pull another Cup victory out of the hat.","cn":"南安普敦队最终还是出乎意料地又一次获得了足总杯赛的胜利。"}},{"pos":"PHRASE 短语","cn":"（比赛中挑选胜出者时）随机地，任意地","en":"In competitions, if you say that the winners will be drawn or picked out of the hat, you mean that they will be chosen randomly, so everyone has an equal chance of winning.","ex":{"en":"The first 10 correct entries drawn out of the hat will win a pair of tickets, worth £20 each.","cn":"随机抽出的前10位答对问题者将获得两张票，每张价值20英镑。"}},{"pos":"","cn":"","en":"to knock something into a cocked hat→see: ;"}]},"examples":[{"en":"I'm telling you this with my lawyer's hat on, you understand.","cn":"你要明白，我是以律师的身分告诉你这事。"},{"en":"I'm wearing two hats tonight — parent and teacher.","cn":"我今晚身兼两职，既是家长又是老师。"}]},"handled":{"oxford":{"phon":"ˈhændl","pos":"verb","senses":[{"en":"to deal with a situation, a person, an area of work or a strong emotion","cn":"处理，应付（局势、人、工作或感情）"},{"en":"to touch, hold or move sth with your hands （","cn":"用手）触，拿，搬动"}]}},"harem":{"media":{"uk":"media/uk/harem__gb_1.mp3","us":"media/us/harem__us_1.mp3"},"oxford":{"phon":"ˈhɑːriːm","pos":"noun","senses":[{"en":"the women or wives belonging to a rich man, especially in some Muslim societies in the past","cn":"哈来姆（尤指旧时某些穆斯林社会中富人的女眷）"},{"en":"the separate part of a traditional Muslim house where the women live","cn":"（穆斯林传统女眷居住的）内室，妇女住房"},{"en":"a group of female animals that share the same male for producing young","cn":"眷群（和同一雄性动物交配的一群雌性动物）","lab":"specialist"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指伊斯兰教徒的）妻妾，女眷","en":"If a man, especially a Muslim, has several wives or sexual partners living in his house, they can be referred to as his harem."},{"pos":"N-COUNT 可数名词","cn":"（妻妾居住的）闺房，内室","en":"A harem is a part of a building where a harem lives."}]}},"handbook":{"oxford":{"phon":"ˈhændbʊk","pos":"noun","senses":[{"en":"a book giving instructions on how to use something or information about a particular subject","cn":"手册；指南","ex":{"en":"A study skills handbook sets out to train the students in all these areas.","cn":"学习技能手册旨在对学生进行所有这些领域的培训。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手册;说明书","en":"A handbook is a book that gives you advice and instructions about a particular subject, tool, or machine.","ex":{"en":"If you have not kept a pet parrot before, it would be wise to purchase a handbook on the subject.","cn":"如果以前没有养过鹦鹉，最好买一本相关的饲养手册。"}}]},"media":{"uk":"media/uk/handbook__gb_1.mp3","us":"media/us/handbook__us_1.mp3"},"examples":[{"en":"the Fiction Writer’s Handbook 《","cn":"小说写作手册》"}]},"harmonious":{"media":{"uk":"media/uk/harmonious__gb_1.mp3","us":"media/us/harmonious__us_1.mp3"},"oxford":{"phon":"hɑːˈməʊniəs","pos":"adjective","senses":[{"en":"friendly, peaceful and without any arguments","cn":"友好和睦的；和谐的","ex":{"en":"a harmonious alliance between management and workers","cn":"管理层与工人的和谐联盟"}},{"en":"arranged together in a way that is pleasant because each part goes well with the others","cn":"协调的；和谐的","ex":{"en":"a harmonious combination of colours","cn":"协调的色彩搭配"}},{"en":"very pleasant when played or sung together","cn":"和谐的；谐调的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（关系、协定、讨论）融洽的，和睦的，友好的","en":"A harmonious relationship, agreement, or discussion is friendly and peaceful.","ex":{"en":"Their harmonious relationship resulted in part from their similar goals","cn":"他们关系融洽的部分原因是他们有着相似的目标。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（各组成部分）和谐的，协调的","en":"Something that is harmonious has parts which go well together and which are in proportion to each other.","ex":{"en":"The architecture is harmonious and no building is over five or six floors high.","cn":"这里的建筑风格和谐统一，没有哪座楼房高于五六层。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（音调）和谐的，悦耳的","en":"Musical notes that are harmonious produce a pleasant sound when played together.","ex":{"en":"...the mysterious skill involved in producing harmonious sounds.","cn":"发出悦耳声音的神秘技巧"}}]},"examples":[{"en":"They worked very harmoniously together.","cn":"他们合作得十分融洽。"},{"en":"a harmonious combination of colours","cn":"协调的色彩搭配"}]},"hardy":{"media":{"uk":"media/uk/hardy__gb_1.mp3","us":"media/us/hardy__us_1.mp3"},"oxford":{"phon":"ˈhɑːdi","pos":"adjective","senses":[{"en":"strong and able to survive difficult conditions and bad weather","cn":"能吃苦耐劳的；适应力强的","ex":{"en":"a hardy breed of sheep","cn":"适应力强的绵羊品种"}},{"en":"that can live outside through the winter","cn":"耐寒的；能越冬的","ex":{"en":"a hardy annual/perennial","cn":"耐寒的一年生/多年生植物"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（植物）耐寒的","en":"Plants that are hardy are able to survive cold weather.","ex":{"en":"The silver-leaved varieties of cyclamen are not quite as hardy.","cn":"银叶仙客来品种不太耐寒。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人或动物）强壮的，适应力强的","en":"People and animals that are hardy are strong and able to cope with difficult conditions.","ex":{"en":"It should not surprise us that such an environment has produced a hardy and independent people","cn":"这样的环境造就了一个吃苦耐劳、独立自主的民族，对此我们不应该感到意外。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚定不移的;非常忠诚的;顽强的","en":"If you describe a group of people as hardy, you mean that they have been very patient or loyal, or have been trying hard to do something in difficult conditions.","ex":{"en":"...the ten hardy supporters who had made the trek to Dublin from Riga.","cn":"从里加长途跋涉到都柏林的10名铁杆支持者"}}]},"examples":[{"en":"a hardy breed of sheep","cn":"适应力强的绵羊品种"},{"en":"hardy mountain goats","cn":"能适应恶劣环境的石山羊"}]},"halfpennies":{"oxford":{"phon":"ˈheɪpni","pos":"noun","senses":[{"en":"a British coin in use until 1971, worth half a penny. There were 480 halfpennies in a pound.","cn":"半便士硬币（1971 年前使用的英国硬币，480 半便士硬币为一英镑）"},{"en":"a British coin in use between 1971 and 1984, worth half a penny. There were 200 halfpennies in a pound.","cn":"半便士硬币（1971 至 1984 年间使用的英国硬币，200 半便士硬币为一英镑）"}]},"media":{"uk":"media/uk/halfpenny__gb_1.mp3","us":"media/us/halfpenny__us_1.mp3"}},"habitually":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"repeated actions are done on several occasions, especially because they do not have any effect at first","cn":""},{"en":"done often as a habit, especially when this is annoying to other people","cn":""}]},"examples":[{"en":"His drinking had become habitual.","cn":"","src":"ld"},{"en":"James took his habitual morning walk around the garden.","cn":"","src":"ld"}],"media":{"uk":"media/uk/habitually__gb_1.mp3","us":"media/us/habitually__us_1.mp3"},"oxford":{"phon":"həˈbɪtʃuəli","pos":"adverb","senses":[{"en":"in a way that is usual for or typical of somebody/something","cn":"惯常的；典型的","ex":{"en":"the dark glasses he habitually wore","cn":"他常戴的墨镜"}},{"en":"in a way that is annoying or difficult to stop, often because it has become a habit","cn":"习惯性地：以令人讨厌或难以停止的方式，通常是因为它已成为一种习惯","ex":{"en":"We are in an era where politicians habitually lie about everything.","cn":"我们正处在一个政客习惯于对一切事情撒谎的时代。"}}]}},"half-sister":{"oxford":{"phon":"ˈhɑːf sɪstə(r)","pos":"noun","senses":[{"en":"a person’s half-sister is a girl or woman who has either the same mother or the same father as them","cn":"同母异父（或同父异母）的姐妹"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同母异父（或同父异母）姐妹","en":"Someone's half-sister is a girl or woman who has either the same mother or the same father as they have."}]},"media":{"uk":"media/uk/half_sister_1_gb_1.mp3","us":"media/us/half_sister_1_us_1.mp3"}},"harsh":{"media":{"uk":"media/uk/harsh__gb_1.mp3","us":"media/us/harsh__us_1.mp3"},"oxford":{"phon":"hɑːʃ","pos":"adjective","senses":[{"en":"cruel, severe and unkind","cn":"残酷的；严酷的；严厉的","ex":{"en":"The punishment was harsh and unfair.","cn":"处罚很重而且不公平。"}},{"en":"very difficult and unpleasant to live in","cn":"恶劣的；艰苦的","ex":{"en":"a harsh winter/wind/climate","cn":"寒冷的冬天；凛冽的风；恶劣的气候"}},{"en":"too strong and bright; ugly or unpleasant to look at","cn":"强烈刺眼的；丑陋的","ex":{"en":"harsh colours","cn":"扎眼的色彩"}},{"en":"unpleasant to listen to","cn":"刺耳的；难听的","ex":{"en":"‘Stop it!’ she said in a harsh voice.","cn":"“停下来！”她用刺耳的嗓音说道。"}},{"en":"too strong and rough and likely to damage something","cn":"粗糙的；毛糙的；刺激性强的","ex":{"en":"harsh detergents","cn":"刺激性强的洗涤剂"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（气候或条件）艰苦的，恶劣的，严峻的","en":"Harsh climates or conditions are very difficult for people, animals, and plants to live in.","ex":{"en":"The weather grew harsh, chilly and unpredictable.","cn":"天气变得恶劣、寒冷且变化莫测。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（言行）严厉的，无情的","en":"Harsh actions or speech are unkind and show no understanding or sympathy.","ex":{"en":"...the cold, harsh cruelty of her husband","cn":"她丈夫冷酷无情的残忍"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗陋的;刺目的;粗糙的","en":"Something that is harsh is so hard, bright, or rough that it seems unpleasant or harmful.","ex":{"en":"Tropical colours may look rather harsh in our dull northern light.","cn":"热带色彩在我们北方暗淡的光线下可能显得有点刺目。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（声音）刺耳的，难听的","en":"Harsh voices and sounds are ones that are rough and unpleasant to listen to.","ex":{"en":"It's a pity she has such a loud harsh voice.","cn":"可惜她的嗓门太大太难听了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（现实、真相）残酷的，无情的","en":"If you talk about harsh realities or facts, or the harsh truth, you are emphasizing that they are true or real, although they are unpleasant and people try to avoid thinking about them.","ex":{"en":"The harsh truth is that luck plays a big part in who will live or die.","cn":"残酷的事实是，谁死谁活在很大程度上要靠运气。"}}]},"examples":[{"en":"We had to face up to the harsh realities of life sooner or later.","cn":"我们迟早都得正视生活的严酷现实。"},{"en":"He regretted his harsh words.","cn":"他对自己的刻薄言辞感到后悔。"}]},"hatred":{"oxford":{"phon":"ˈheɪtrɪd","pos":"noun","senses":[{"en":"a very strong feeling of dislike for somebody/something","cn":"仇恨；憎恨；厌恶","ex":{"en":"He looked at me with intense hatred.","cn":"他满怀敌意地看着我。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"仇恨;憎恶;敌意","en":"Hatred is an extremely strong feeling of dislike for someone or something.","ex":{"en":"Her hatred of them would never lead her to murder","cn":"她虽说仇恨他们，但绝不至于去杀人。"}}]},"media":{"uk":"media/uk/hatred__gb_1.mp3","us":"media/us/hatred__us_1.mp3"},"examples":[{"en":"The debate simply revived old hatreds.","cn":"这一辩论不过是再次挑起了夙仇。"},{"en":"There was fear and hatred in his voice.","cn":"他的声音里透露着恐惧和仇恨。"}]},"hate":{"media":{"uk":"media/uk/hate__gb_1.mp3","us":"media/us/hate__us_1.mp3"},"oxford":{"phon":"heɪt","pos":"verb","senses":[{"en":"to dislike somebody/something very much","cn":"极不喜欢；厌恶","g":"[transitive, intransitive]","ex":{"en":"The two boys hated each other.","cn":"那两个男孩相互厌恶。"}},{"en":"used when saying something that you would prefer not to have to say, or when politely asking to do something","cn":"（表示不愿说某事，或客气地请求）不愿，不想","g":"[no passive]","ex":{"en":"I hate to say it, but I don't think their marriage will last.","cn":"我不愿这么说，但我觉得他们的婚姻不会长久。"}},{"en":"a very strong feeling of dislike for somebody","cn":"憎恨；厌恶；仇恨","g":"[uncountable]","ex":{"en":"She gave him a look of real hate.","cn":"她给了他一个真正仇恨的眼神。"},"pos":"noun"},{"en":"a person or thing that you hate","cn":"所憎恶的人（或事物）","g":"[countable]","lab":"informal","ex":{"en":"Plastic flowers have always been a particular hate of mine.","cn":"我一向特别厌恶塑料花。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"仇恨;憎恨;憎恶","en":"If you hate someone or something, you have an extremely strong feeling of dislike for them.","ex":{"en":"Most people hate him, but they don't dare to say so, because he still rules the country","cn":"人们大多憎恨他，但不敢说，因为他仍在统治这个国家。"}},{"pos":"VERB 动词","cn":"讨厌;厌恶;不喜欢","en":"If you say that you hate something such as a particular activity, you mean that you find it very unpleasant.","ex":{"en":"Ted hated parties, even gatherings of people he liked individually","cn":"特德讨厌各种派对，即便是他自己喜欢的人的聚会也不例外。"}},{"pos":"VERB 动词","cn":"我真不愿麻烦你/我真不想打扰你","en":"You can use hate in expressions such as 'I hate to trouble you' or 'I hate to bother you' when you are apologizing to someone for interrupting them or asking them to do something.","ex":{"en":"I hate to rush you but I have another appointment later on.","cn":"我真不想催你，但我稍后还有一个约会。"}},{"pos":"VERB 动词","cn":"我很抱歉这么说/我很遗憾地通知你","en":"You can use hate in expressions such as 'I hate to say it' or 'I hate to tell you' when you want to express regret about what you are about to say, because you think it is unpleasant or should not be the case.","ex":{"en":"I hate to tell you this, but tomorrow's your last day","cn":"我很抱歉地通知你，明天是你的最后一天了。"}},{"pos":"","cn":"","en":"to hate someone's guts→see: ;"},{"pos":"VERB 动词","cn":"我很不愿意看到/我很不愿意想","en":"You can use hate in expressions such as 'I hate to see' or 'I hate to think' when you are emphasizing that you find a situation or an idea unpleasant.","ex":{"en":"I just hate to see you doing this to yourself.","cn":"我真不愿意看到你这样对待自己。"}},{"pos":"VERB 动词","cn":"真希望…不是真的（或不会发生）","en":"You can use hate in expressions such as 'I'd hate to think' when you hope that something is not true or that something will not happen.","ex":{"en":"I'd hate to think my job would not be secure if I left it temporarily.","cn":"希望我的工作不会因为我暂时休假而不保。"}}]},"examples":[{"en":"Whether you love or loathe their music, you can't deny their talent.","cn":"无论你是否喜欢他们的音乐，你都无法否认他们的才能。"},{"en":"I hate to say it, but I don't think their marriage will last.","cn":"我不愿这么说，但我觉得他们的婚姻不会长久。"}]},"hall":{"media":{"uk":"media/uk/hall__gb_1.mp3","us":"media/us/hall__us_1.mp3"},"oxford":{"phon":"hɔːl","pos":"noun","senses":[{"en":"a space or passage inside the entrance or front door of a building","cn":"门厅；正门过道","lab":"especially in British English","ex":{"en":"Her brother was standing in the front hall.","cn":"她哥哥站在前厅。"}},{"en":"a passage in a building with rooms down either side","cn":"（大楼内的）走廊","lab":"North American English","ex":{"en":"I headed for Scott's office down the hall.","cn":"我沿着走廊直奔斯科特的办公室。"}},{"en":"a building or large room for public meetings, meals, concerts, etc.","cn":"礼堂；大厅","lab":"British English","ex":{"en":"a concert/sports hall","cn":"音乐厅；体育馆"}},{"en":"a building for university or college students to live in","cn":"（大学）学生宿舍","lab":"North American English also","ex":{"en":"She's living in hall(s).","cn":"她住在学生宿舍。"}},{"en":"a large country house","cn":"大庄园府邸","lab":"British English","ex":{"en":"Haddon Hall","cn":"哈登府"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（房子或公寓的）门厅","en":"The hall in a house or flat is the area just inside the front door, into which some of the other rooms open.","ex":{"en":"The lights were on in the hall and in the bedroom.","cn":"门厅和卧室的灯都亮着。"}},{"pos":"N-COUNT 可数名词","cn":"（大楼里的）走廊，过道","en":"A hall in a building is a long passage with doors into rooms on both sides of it."},{"pos":"N-COUNT 可数名词","cn":"大厅;会堂;礼堂","en":"A hall is a large room or building which is used for public events such as concerts, exhibitions, and meetings.","ex":{"en":"Its 300 inhabitants will be celebrating with a dance in the village hall","cn":"300名村民将在村礼堂举行一场舞会以示庆祝。"}},{"pos":"N-COUNT 可数名词","cn":"（大学或学院的）学生宿舍","en":"If students live in hall in British English, or in a hall in American English, they live in a university or college building called a hall of residence."},{"pos":"N-IN-NAMES 名称名词","cn":"（乡间）大庄园，府第（用于住宅名称中）","en":"Hall is sometimes used as part of the name of a large house in the country.","ex":{"en":"He died at Holly Hall, his wife's family home.","cn":"他在妻子的娘家冬青府去世。"}},{"pos":"N-IN-NAMES 名称名词","cn":"厅，会堂，礼堂（尤用于礼堂、音乐厅等名称中）","en":"Hall is sometimes used as part of the name of a large building, especially one where public events or concerts take place","ex":{"en":"...New York's Carnegie Hall.","cn":"纽约的卡内基音乐厅"}}]},"examples":[{"en":"I headed for Scott's office down the hall.","cn":"我沿着走廊直奔斯科特的办公室。"},{"en":"( BrE ) A jumble sale will be held in the village hall on Saturday.","cn":"星期六将在村礼堂举行义卖。"}]},"hand":{"media":{"img":["media/ldoce/img/hand.jpg","media/pic/hand_body_comp.jpg"],"uk":"media/uk/hand__gb_1.mp3","us":"media/us/hand__us_1.mp3"},"oxford":{"phon":"hænd","pos":"noun","senses":[{"en":"the part of the body at the end of the arm, including the fingers and thumb","cn":"手","g":"[countable]","lab":"informal","sc":"part of body","ex":{"en":"Ian placed a hand on her shoulder.","cn":"伊恩把一只手搭在她的肩上。"}},{"en":"using the hand or number of hands mentioned","cn":"用…手的；用…只手的","sc":"-handed","ex":{"en":"a one-handed catch","cn":"单手抓接"}},{"en":"help in doing something","cn":"帮助；协助","g":"[singular]","lab":"informal","sc":"help","ex":{"en":"The neighbours are always willing to lend a hand.","cn":"邻居们总是乐于帮忙。"}},{"en":"the part or role that somebody/something plays in a particular situation; somebody’s influence in a situation","cn":"角色；作用；影响","g":"[singular]","sc":"role in situation","ex":{"en":"Early reports suggest the hand of rebel forces in the bombings.","cn":"早期的报道暗示叛乱武装插手了爆炸案。"}},{"en":"a part of a clock or watch that points to the numbers","cn":"指针","g":"[countable]","sc":"on clock/watch"},{"en":"a person who does physical work on a farm or in a factory","cn":"（农场或工厂的）体力劳动者，工人","g":"[countable]","sc":"worker","ex":{"en":"The farmer would bring in hired hands to help him harvest the crop.","cn":"农民会聘请雇工来帮助他收割庄稼。"}},{"en":"a sailor on a ship","cn":"船员","g":"[countable]","sc":"sailor","ex":{"en":"All hands on deck!","cn":"全体船员到甲板上集合！"}},{"en":"by a person rather than a machine","cn":"手工","sc":"hand-","ex":{"en":"hand-painted pottery","cn":"手绘陶器"}},{"en":"a set of playing cards given to one player in a game","cn":"（分给游戏者的）一手牌","g":"[countable]","lab":"figurative","sc":"in card games","ex":{"en":"to be dealt a good/bad hand","cn":"拿到一手好牌／烂牌"}},{"en":"one stage of a game of cards","cn":"（纸牌游戏的）一盘","g":"[countable]","sc":"in card games","ex":{"en":"I'll have to leave after this hand.","cn":"这一盘打完后我必须走了。"}},{"en":"a particular style of writing","cn":"书法","g":"[singular]","lab":"old use","sc":"writing"},{"en":"a unit for measuring the height of a horse, equal to 4 inches or 10.16 centimetres","cn":"一手之宽（测量马的高度的单位，等于 4 英寸或 10.16 厘米）","g":"[countable]","sc":"measurement for horse"},{"en":"to pass or give something to somebody","cn":"交；递；给","ex":{"en":"She handed the letter to me.","cn":"她把信交给我。"},"pos":"verb"},{"en":"to allow somebody to have something, sometimes too easily","cn":"拱手让给；轻易送给","lab":"sometimes disapproving","ex":{"en":"Missed chances by United players handed a surprise victory to Stoke.","cn":"曼联球员错失良机，斯托克城队意外获胜。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手","en":"Your hands are the parts of your body at the end of your arms. Each hand has four fingers and a thumb.","ex":{"en":"I put my hand into my pocket and pulled out the letter","cn":"我把手伸进口袋，掏出了那封信。"}},{"pos":"N-SING 单数名词","cn":"作用;影响","en":"The hand of someone or something is their influence in an event or situation.","ex":{"en":"The hand of the military authorities can be seen in the entire electoral process","cn":"整个选举过程中都能看出军方的介入。"}},{"pos":"N-PLURAL 复数名词","cn":"照顾;支配;掌管","en":"If you say that something is in a particular person's hands, you mean that they are looking after it, own it, or are responsible for it.","ex":{"en":"I feel that possibly the majority of these dogs are in the wrong hands","cn":"在我看来很可能这些狗大多数都没有人妥善照看。"}},{"pos":"N-SING 单数名词","cn":"帮助;援手","en":"If you ask someone for a hand with something, you are asking them to help you in what you are doing.","ex":{"en":"I could see you'd want a hand with the children","cn":"我能看出你需要有人帮着照看孩子。"}},{"pos":"N-COUNT 可数名词","cn":"（工厂或农场的）工人，体力劳动者（通常指男性）","en":"A hand is someone, usually a man, who does hard physical work, for example in a factory or on a farm, as part of a group of people who all do similar work.","ex":{"en":"He now works as a farm hand","cn":"他现在是一名农场工人。"}},{"pos":"N-SING 单数名词","cn":"（通常指演出前后的）鼓掌，掌声","en":"If someone asks an audience to give someone a hand, they are asking the audience to clap loudly, usually before or after that person performs.","ex":{"en":"Let's give 'em a big hand.","cn":"让我们为他们热烈鼓掌。"}},{"pos":"N-COUNT 可数名词","cn":"（女方的）允婚","en":"If a man asks for a woman's hand in marriage, he asks her or her parents for permission to marry her.","ex":{"en":"He came to ask Usha's father for her hand in marriage.","cn":"他来请求乌莎的父亲把女儿嫁给他。"}},{"pos":"N-COUNT 可数名词","cn":"（纸牌游戏中的）手中的牌，一手牌","en":"In a game of cards, your hand is the set of cards that you are holding in your hand at a particular time or the cards that are dealt to you at the beginning of the game.","ex":{"en":"He carefully inspected his hand.","cn":"他仔细地审视着自己手中的牌。"}},{"pos":"N-COUNT 可数名词","cn":"一手之宽（测量马匹高度的单位，等于4英寸）","en":"A hand is a measurement of four inches, which is used for measuring the height of a horse from its front feet to its shoulders.","ex":{"en":"I had a very good 14.2 hands pony, called Brandy.","cn":"我有一匹很棒的14.2手高的小马，名叫布朗迪。"}},{"pos":"N-COUNT 可数名词","cn":"（钟表上的）指针","en":"The hands of a clock or watch are the thin pieces of metal or plastic that indicate what time it is."},{"pos":"N-SING 单数名词","cn":"字迹;手迹;笔迹","en":"Your hand is the style in which you write with a pen or pencil.","ex":{"en":"The manuscripts were written in the composer's own hand.","cn":"手稿是作曲家亲笔写的。"}},{"pos":"PHRASE 短语","cn":"（空间或时间上）接近的，不远的","en":"If something is at hand ,near at hand, or close at hand, it is very near in place or time.","ex":{"en":"Having the right equipment at hand will be enormously helpful","cn":"手头上有合适的设备将会帮上大忙。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在…手中，从…那里（尤指受到不好的待遇）","en":"If someone experiences a particular kind of treatment, especially unpleasant treatment, at the hands of a person or organization, they receive it from them.","ex":{"en":"The civilian population were suffering greatly at the hands of the security forces.","cn":"老百姓吃尽了安全部队的苦头。"}},{"pos":"PHRASE 短语","cn":"用手工","en":"If you do something by hand, you do it using your hands rather than a machine.","ex":{"en":"Each pleat was stitched in place by hand.","cn":"每条褶裥都是手工缝制到位的。"}},{"pos":"PHRASE 短语","cn":"变换所有权;易主;易手","en":"When something changes hands, its ownership changes, usually because it is sold to someone else.","ex":{"en":"The firm has changed hands many times over the years.","cn":"该公司多年来已几易其主。"}},{"pos":"PHRASE 短语","cn":"完全受（某人）支配;完全听命于（某人）","en":"If you have someone eating out of your hand, they are completely under your control.","ex":{"en":"Parker could have customers eating out of his hand.","cn":"帕克能让顾客对自己言听计从。"}},{"pos":"PHRASE 短语","cn":"连手带脚地，手脚一起地（捆绑）","en":"If someone is bound hand and foot, both their hands and both their feet are tied together."},{"pos":"PHRASE 短语","cn":"迫使（某人）提前行动（或公开其所作所为）","en":"If you force someone's hand, you force them to act sooner than they want to, or to act in public when they would prefer to keep their actions secret.","ex":{"en":"He blamed the press for forcing his hand.","cn":"他指责新闻界迫使自己采取行动。"}},{"pos":"PHRASE 短语","cn":"（为…）忙得不可开交;（因…）应接不暇","en":"If you have your hands full with something, you are very busy because of it.","ex":{"en":"She had her hands full with new arrivals.","cn":"她忙于应付新来的人。"}},{"pos":"PHRASE 短语","cn":"自行决定权;自由行动权","en":"If someone gives you a free hand, they give you the freedom to use your own judgment and to do exactly as you wish.","ex":{"en":"He gave Stephanie a free hand in the decoration.","cn":"他放手让斯蒂芬妮全权负责装修一事。"}},{"pos":"PHRASE 短语","cn":"迅速而大量地（赚钱或花钱）","en":"If you say that someone is making or losing money hand over fist, you mean that they are getting or losing a lot of money very quickly."},{"pos":"PHRASE 短语","cn":"（通常指经过努力后）获得，得到","en":"If you get your hands on something or lay your hands on something, you manage to find it or obtain it, usually after some difficulty.","ex":{"en":"Patty began reading everything she could get her hands on.","cn":"帕蒂开始阅读她能找到的所有东西。"}},{"pos":"PHRASE 短语","cn":"（与某人）密切合作地","en":"If you work hand in glove with someone, you work very closely with them.","ex":{"en":"The UN inspectors work hand in glove with the Western intelligence agencies.","cn":"联合国观察员和西方情报机构之间密切合作。"}},{"pos":"PHRASE 短语","cn":"（常指为表示爱意而）手拉手的，携着手的","en":"If two people are hand in hand, they are holding each other's nearest hand, usually while they are walking or sitting together. People often do this to show their affection for each other.","ex":{"en":"I saw them making their way, hand in hand, down the path.","cn":"我看到他们手拉手沿着小路往前走去。"}},{"pos":"PHRASE 短语","cn":"（两件事）密切相关地，同时并进地","en":"If two things go hand in hand, they are closely connected and cannot be considered separately from each other.","ex":{"en":"For us, research and teaching go hand in hand","cn":"对我们而言，研究和教学是齐头并进的。"}},{"pos":"PHRASE 短语","cn":"参加;参与","en":"If you have a hand in something such as an event or activity, you are involved in it.","ex":{"en":"He thanked all who had a hand in his release.","cn":"他向所有帮助自己获得释放的人表示感谢。"}},{"pos":"PHRASE 短语","cn":"（统治者）用高压手段，严厉地","en":"If you say that someone such as the ruler of a country treats people with a heavy hand, you are criticizing them because they are very strict and severe with them.","ex":{"en":"Henry and Richard both ruled with a heavy hand.","cn":"亨利和理查都用高压手段实行统治。"}},{"pos":"PHR-RECIP 相互短语","cn":"（常指为表示爱意而）手拉手，牵手","en":"If two people are holding hands, they are holding each other's nearest hand, usually while they are walking or sitting together. People often do this to show their affection for each other.","ex":{"en":"She approached a young couple holding hands on a bench.","cn":"她走近一对手拉手坐在长椅上的年轻情侣。"}},{"pos":"PHRASE 短语","cn":"给…精神上的支持","en":"If you ask someone to hold your hand at an event that you are worried about, you ask them to support you by being there with you.","ex":{"en":"I don't need anyone to hold my hand.","cn":"我不需要任何人的精神安慰。"}},{"pos":"PHRASE 短语","cn":"（比赛）尚待进行","en":"In a competition, if someone has games or matches in hand, they have more games or matches left to play than their opponent and therefore have the possibility of scoring more points.","ex":{"en":"Wales are three points behind Romania in the group but have a game in hand.","cn":"威尔士队在小组中以3分之差落后于罗马尼亚队，但他们还有一场比赛没踢。"}},{"pos":"PHRASE 短语","cn":"（时间或金钱）宽余的","en":"If you have time or money in hand, you have more time or money than you need.","ex":{"en":"Hughes finished with 15 seconds in hand.","cn":"休斯提前了15秒完成。"}},{"pos":"PHRASE 短语","cn":"（工作或问题）办理中的，处理中的","en":"The job or problem in hand is the job or problem that you are dealing with at the moment.","ex":{"en":"The business in hand was approaching some kind of climax.","cn":"手头的生意似乎快到紧要关头了。"}},{"pos":"PHRASE 短语","cn":"（局势）在控制下，在掌握中","en":"If a situation is in hand, it is under control.","ex":{"en":"The Olympic organisers say that matters are well in hand.","cn":"奥运会的组织方说各项事务都在掌控之中。"}},{"pos":"PHRASE 短语","cn":"偶尔练习以保持熟练","en":"If you do something to keep your hand in, you practise a skill or hobby occasionally in order to remain fairly good at it.","ex":{"en":"He still plays keyboards for a local band to keep his hand in.","cn":"他仍在一个本地乐队里担任键盘手，以免技艺生疏。"}},{"pos":"PHRASE 短语","cn":"趴着;四肢着地","en":"If you are on your hands and knees, your knees and feet and the palms of your hands are touching the ground.","ex":{"en":"Chris crawled on his hands and knees out onto the highway.","cn":"克里斯手脚并用爬上了公路。"}},{"pos":"PHRASE 短语","cn":"向…伸出援手;给予…帮助","en":"If you lend someone a hand, you help them.","ex":{"en":"I'd be glad to lend a hand.","cn":"我很乐意帮忙。"}},{"pos":"PHRASE 短语","cn":"（不客气的警告语）别碰…，别干涉…","en":"If you tell someone to keep their hands off something or to take their hands off it, you are telling them in a rather aggressive way not to touch it or interfere with it.","ex":{"en":"Keep your hands off my milk.","cn":"不准打我的牛奶的主意。"}},{"pos":"PHRASE 短语","cn":"马上;立即;无需询问（或查证）","en":"If you do not know something off hand, you do not know it without having to ask someone else or look it up in a book.","ex":{"en":"I can't think of any off hand.","cn":"我现在一个也想不出来。"}},{"pos":"PHRASE 短语","cn":"由…负责/不再由…负责","en":"If you have a problem or responsibility on your hands, you have to deal with it. If it is off your hands, you no longer have to deal with it.","ex":{"en":"They now have yet another drug problem on their hands","cn":"他们现在又有个吸毒问题需要解决。"}},{"pos":"PHRASE 短语","cn":"在手头;在近处;现有","en":"If someone or something is on hand, they are near and able to be used if they are needed.","ex":{"en":"The Bridal Department will have experts on hand to give you all the help and advice you need","cn":"婚礼用品部会有现成的专家为您提供所需的一切帮助和建议。"}},{"pos":"PHRASE 短语","cn":"一方面…（另一方面…）","en":"You use on the one hand to introduce the first of two contrasting points, facts, or ways of looking at something. It is always followed later by on the other hand or 'on the other'.","ex":{"en":"On the one hand, if the body doesn't have enough cholesterol, we would not be able to survive. On the other hand, if the body has too much cholesterol, the excess begins to line the arteries.","cn":"一方面，如果体内没有足够的胆固醇，我们就无法存活下去。另一方面，如果体内胆固醇过高，多余的胆固醇就会附着在动脉内壁上。"}},{"pos":"PHRASE 短语","cn":"（从）另一方面（来说）（用于引出相对照的另一点）","en":"You use on the other hand to introduce the second of two contrasting points, facts, or ways of looking at something.","ex":{"en":"Well, all right, hospitals lose money. But, on the other hand, if people are healthy, don't think of it as losing money; think of it as saving lives.","cn":"嗯，好吧，医院是赔钱。但从另一个角度看，如果人们都健健康康的，就不能认为是在赔钱，而应该想成是在救死扶伤。"}},{"pos":"PHRASE 短语","cn":"失去控制;不可收拾","en":"If a person or a situation gets out of hand, you are no longer able to control them.","ex":{"en":"His drinking had got out of hand.","cn":"他酗酒的恶习已无法控制。"}},{"pos":"PHRASE 短语","cn":"立即，不假思索地（屏弃、拒绝等）","en":"If you dismiss or reject something out of hand, you do so immediately and do not consider believing or accepting it.","ex":{"en":"I initially dismissed the idea out of hand.","cn":"我起初不假思索地就否定了这个想法。"}},{"pos":"PHRASE 短语","cn":"因失算而让…占便宜;做对…有利的事","en":"If you play into someone's hands, you do something which they want you to do and which places you in their power.","ex":{"en":"He is playing into the hands of racists.","cn":"他这样做正中种族主义分子的下怀。"}},{"pos":"PHRASE 短语","cn":"摊牌;亮出底牌;表明自己的真实意图","en":"If you show your hand, you show how much power you have and the way you intend to act.","ex":{"en":"He has grown more serious about running for president, although he refuses to show his hand.","cn":"尽管他拒绝亮出自己的底牌，他对竞选总统一事却越来越认真了。"}},{"pos":"PHRASE 短语","cn":"（尤指为有所改善）接手，照管，担任起对…的责任","en":"If you take something or someone in hand, you take control or responsibility over them, especially in order to improve them.","ex":{"en":"I hope that Parliament will soon take the NHS in hand","cn":"我希望议会能很快接管国民医疗保健系统。"}},{"pos":"PHRASE 短语","cn":"（因愤怒、绝望或厌恶而）骤然举起双手","en":"If someone throws up their hands, they express their anger, frustration, or disgust when a situation becomes so bad that they can no longer accept it.","ex":{"en":"She threw up her hands in despair","cn":"她绝望地举起双手表示放弃。"}},{"pos":"PHRASE 短语","cn":"受到束缚;放不开手脚","en":"If you say that your hands are tied, you mean that something is preventing you from acting in the way that you want to.","ex":{"en":"Politicians are always saying that they want to help us but their hands are tied","cn":"政客们总是说想帮助我们，但却身不由己。"}},{"pos":"PHRASE 短语","cn":"在手边;在附近","en":"If you have something to hand or near to hand, you have it with you or near you, ready to use when needed.","ex":{"en":"You may want to keep this brochure safe, so you have it to hand whenever you may need it.","cn":"你应该保管好这份手册，这样随时想用都能马上在手边找到。"}},{"pos":"PHRASE 短语","cn":"（通常指初次）尝试，试身手","en":"If you try your hand at an activity, you attempt to do it, usually for the first time.","ex":{"en":"After he left school, he tried his hand at a variety of jobs—bricklayer, cinema usher, coal man.","cn":"离开学校后，他尝试过各种工作，如泥瓦匠、电影院引座员、运煤工。"}},{"pos":"PHRASE 短语","cn":"着手学做","en":"If you turn your hand to something such as a practical activity, you learn about it and do it for the first time.","ex":{"en":"...a person who can turn his hand to anything.","cn":"什么事都能学着做的人"}},{"pos":"PHRASE 短语","cn":"洗手不干;不再管;和…断绝关系","en":"If you wash your hands of someone or something, you refuse to be involved with them any more or to take responsibility for them.","ex":{"en":"He seems to have washed his hands of the job.","cn":"那份工作他好像已经洗手不干了。"}},{"pos":"PHRASE 短语","cn":"轻易取胜","en":"If you win hands down, you win very easily."},{"pos":"See also:","cn":"","en":"with one's bare hands→see: ; to overplay one's hand→see: ; to shake someone's hand→see: ; to shake hands→see: ;"},{"pos":"VERB 动词","cn":"递;交;给","en":"If you hand something to someone, you pass it to them.","ex":{"en":"He handed me a little rectangle of white paper","cn":"他递给我一张小小的长方形白纸片。"}},{"pos":"PHRASE 短语","cn":"你不得不佩服…","en":"You say things such as 'You have to hand it to her' or 'You've got to hand it to them' when you admire someone for their skills or achievements and you think they deserve a lot of praise.","ex":{"en":"You've got to hand it to Melissa, she certainly gets around.","cn":"你不得不佩服梅利莎，她到哪里都吃得开。"}},{"pos":"","cn":"","en":"相关词组：hand around hand back hand down hand in hand on hand out hand over hand round"}]},"examples":[{"en":"On the one hand they'd love to have kids, but on the other, they don't want to give up their freedom.","cn":"一方面，他们想要孩子，但另一方面，他们又不想放弃自由自在的生活。"},{"en":"The property is ideally located with all local amenities close at hand.","cn":"这处房地产的位置很理想，离当地的福利设施都近。"}]},"hanging":{"media":{"uk":"media/uk/hanging__gb_1.mp3","us":"media/us/hanging__us_1.mp3"},"oxford":{"phon":"ˈhæŋɪŋ","pos":"noun","senses":[{"en":"the practice of killing somebody as a punishment by tying a rope around their neck and allowing them to drop from a high place; an occasion when this happens","cn":"绞死；绞刑","g":"[uncountable, countable]","ex":{"en":"to sentence somebody to death by hanging","cn":"判处某人绞刑"}},{"en":"a large piece of material that is hung on a wall or around a bed for decoration","cn":"墙幔；床幔；帷幔","g":"[countable, usually plural]","ex":{"en":"wall hangings","cn":"挂在墙上的装饰织物"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（作装饰的）壁挂，墙幔，帷幔","en":"A hanging is a large piece of cloth that you put as a decoration on a wall.","ex":{"en":"...a giant antique embroidered hanging.","cn":"巨幅古董刺绣壁挂"}}]},"examples":[{"en":"to sentence sb to death by hanging","cn":"判处某人绞刑"},{"en":"wall hangings","cn":"挂在墙上的装饰织物"}]},"happy":{"media":{"uk":"media/uk/happy__gb_1.mp3","us":"media/us/happy__us_1.mp3"},"oxford":{"phon":"ˈhæpi","pos":"adjective","senses":[{"en":"feeling or showing pleasure; pleased","cn":"感到（或显得）快乐的；高兴的","sc":"feeling/giving pleasure","ex":{"en":"a happy family","cn":"幸福的家庭"}},{"en":"giving or causing pleasure","cn":"给予（或带来）快乐的；使人高兴的；幸福的","sc":"feeling/giving pleasure","ex":{"en":"She had a very happy life.","cn":"她有过非常幸福的生活。"}},{"en":"if you wish somebody a Happy Birthday, Happy New Year, etc. you mean that you hope they have a pleasant celebration","cn":"（表示祝愿，如 Happy Birthday 生日快乐、Happy New Year 新年好等）","sc":"at celebration"},{"en":"satisfied that something is good or right; not anxious","cn":"（对事物）满意的，放心的","sc":"satisfied","ex":{"en":"I don't know what you've done, but the boss isn't happy.","cn":"我不知道你做了什么，但老板不高兴。"}},{"en":"willing or pleased to do something","cn":"情愿，乐意（做某事）","lab":"formal","sc":"willing","ex":{"en":"I'm perfectly happy to leave it till tomorrow.","cn":"我非常愿意把它留到明天再做。"}},{"en":"lucky; successful","cn":"幸运的；成功的","sc":"lucky","ex":{"en":"By a happy coincidence, we arrived at exactly the same time.","cn":"碰巧运气好，我们恰恰同时到达。"}},{"en":"suitable and appropriate for a particular situation","cn":"合适的；恰当的","lab":"formal","sc":"suitable","ex":{"en":"That wasn't the happiest choice of words.","cn":"那样的措辞并不是十分恰当。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高兴的;快乐的","en":"Someone who is happy has feelings of pleasure, usually because something nice has happened or because they feel satisfied with their life.","ex":{"en":"Marina was a confident, happy child","cn":"玛丽娜是个自信、快乐的孩子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（时光、地点或关系）令人愉快的，幸福的","en":"A happy time, place, or relationship is full of happy feelings and pleasant experiences, or has an atmosphere in which people feel happy.","ex":{"en":"Except for her illnesses, she had had a particularly happy childhood","cn":"除了体弱多病外，她的童年特别幸福。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对情况或安排）满意的，放心的","en":"If you are happy about a situation or arrangement, you are satisfied with it, for example because you think that something is being done in the right way.","ex":{"en":"If you are not happy about a repair, go back and complain","cn":"如果你对修理效果不满意，可以再找他们投诉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乐意的;情愿的","en":"If you say you are happy to do something, you mean that you are very willing to do it.","ex":{"en":"I'll be happy to answer any questions if there are any","cn":"如果有问题，我很乐意回答。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表示祝福）…快乐","en":"Happy is used in greetings and other conventional expressions to say that you hope someone will enjoy a special occasion. many happy returns→see: ;","ex":{"en":"Happy Birthday!","cn":"生日快乐！"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（巧合）幸运的，令人愉快的","en":"A happy coincidence is one that results in something pleasant or helpful happening.","ex":{"en":"By happy coincidence, Robert met Richard and Julia and discovered they were experiencing similar problems.","cn":"幸运的是，罗伯特碰巧遇到了理查德和朱莉娅，发现原来他们也碰到了类似的问题。"}}]},"examples":[{"en":"We are happy to announce the engagement of our daughter.","cn":"我们高兴地宣布，我们的女儿已订婚。"},{"en":"If there's anything you're not happy about, come and ask.","cn":"你如果有什么不满意的，来说一声。"}]},"harden":{"oxford":{"phon":"ˈhɑːdn","pos":"verb","senses":[{"en":"to become or make something become solid or stiff","cn":"（使）变硬，硬化","g":"[intransitive, transitive]","ex":{"en":"The varnish takes a few hours to harden.","cn":"清漆需要几个小时才能干透。"}},{"en":"if your voice, face, etc. hardens, or you harden it, it becomes more serious or severe","cn":"（使声音、面孔等）更严肃，更严厉","g":"[intransitive, transitive]","ex":{"en":"Her face hardened into an expression of hatred.","cn":"她的脸沉下来，面带恨意。"}},{"en":"if somebody’s feelings or attitudes harden or somebody/something hardens them, they become more fixed and determined","cn":"（使）更坚定，更强硬","g":"[intransitive, transitive]","ex":{"en":"Public attitudes to the strike have hardened.","cn":"公众对这次罢工所持的态度已强硬起来。"}},{"en":"to make somebody less kind or less affected by extreme situations","cn":"使变得无情；使不被打动","g":"[transitive]","ex":{"en":"Joe sounded different, hardened by the war.","cn":"乔让人觉得他变了，因战争变得冷酷无情了。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）变硬;（使）硬化","en":"When something hardens or when you harden it, it becomes stiff or firm.","ex":{"en":"Mould the mixture into shape while hot, before it hardens","cn":"在混合物还没有变硬之前，趁热将它塑成形。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（态度、想法）变得更坚定;（使）变得更强硬","en":"When an attitude or opinion hardens or is hardened, it becomes harsher, stronger, or fixed.","ex":{"en":"Their action can only serve to harden the attitude of landowners","cn":"他们的行动只会让土地拥有者的态度变得更坚定。"}},{"pos":"VERB 动词","cn":"（价格、经济）变得更稳定","en":"When prices and economies harden, they become much more stable than they were.","ex":{"en":"Property prices are just beginning to harden again.","cn":"房地产价格刚开始重新趋于稳定。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）变得坚强;（使）变得冷酷无情;（使）变得麻木不仁","en":"When events harden people or when people harden, they become less easily affected emotionally and less sympathetic and gentle than they were before.","ex":{"en":"Her years of drunken bickering hardened my heart","cn":"她多年来醉酒寻衅的恶习让我变得麻木。"}},{"pos":"VERB 动词","cn":"（表情、眼神）变得严肃，变得不快","en":"If you say that someone's face or eyes harden, you mean that they suddenly look serious or angry.","ex":{"en":"His smile died and the look in his face hardened.","cn":"他的笑容消失了，脸上的表情严肃了起来。"}}]},"media":{"uk":"media/uk/harden__gb_1.mp3","us":"media/us/harden__us_1.mp3"},"examples":[{"en":"In this job you have to harden your heart to pain and suffering.","cn":"做这项工作面对伤痛和病患时你得保持沉着冷静。"},{"en":"Joe sounded different, hardened by the war.","cn":"乔让人觉得变了，因战争变得冷酷无情了。"}]},"handle":{"oxford":{"phon":"ˈhændl","pos":"verb","senses":[{"en":"to deal with a situation, a person, an area of work or a strong emotion","cn":"处理，应付（局势、人、工作或感情）","g":"[transitive]","lab":"informal","sc":"deal with","ex":{"en":"A new man was appointed to handle the crisis.","cn":"新指派了一个人来处理这场危机。"}},{"en":"to touch, hold or move something with your hands","cn":"（用手）触，拿，搬动","g":"[transitive]","sc":"touch with hands","ex":{"en":"Our cat hates being handled.","cn":"我们的猫不喜欢被人摸弄。"}},{"en":"to control a vehicle, an animal, a tool, etc.","cn":"控制，操纵（车辆、动物、工具等）","g":"[transitive]","sc":"control","ex":{"en":"I wasn't sure if I could handle such a powerful car.","cn":"我没有把握是否能驾驶功率这样大的车。"}},{"en":"to be easy/difficult to drive or control","cn":"（容易／难以）驾驶，操纵","g":"[intransitive]","sc":"control","ex":{"en":"The car handles well in any weather.","cn":"这辆车在任何天气下开起来都很灵便。"}},{"en":"to buy or sell something","cn":"买；卖","g":"[transitive]","sc":"buy/sell","ex":{"en":"They were arrested for handling stolen goods.","cn":"他们因收售赃物而遭逮捕。"}},{"en":"the part of a door, window, etc. that you use to open it","cn":"把手；拉手","sc":"of door/window","ex":{"en":"She turned the handle and opened the door.","cn":"她转动把手，打开了门。"},"pos":"noun"},{"en":"the part of an object, such as a cup, a bag or a tool, that you use to hold it or carry it","cn":"柄；把；提梁；把手","sc":"of cup/bag/tool","ex":{"en":"the handle of a knife","cn":"刀柄"},"pos":"noun"},{"en":"having the number or type of handle mentioned","cn":"有…个柄的；有…柄的","sc":"-handled","ex":{"en":"a long-handled spoon","cn":"一把长柄匙"},"pos":"noun"},{"en":"a name or nickname","cn":"名字；绰号","sc":"name","pos":"noun"},{"en":"a person's username on a social media site or online forum","cn":"（在社交媒体或网络论坛上的）用户名，网名","sc":"name","ex":{"en":"I added my handle at the top of my blog page so that readers could view my tweets as well as my blog posts.","cn":"我在我的博客页面顶部添加了推特账号，这样读者既能看到我的博客帖子，又可以查看我在推特发送的信息。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（门上的）拉手，把手","en":"A handle is a small round object or a lever that is attached to a door and is used for opening and closing it.","ex":{"en":"I turned the handle and found the door was open.","cn":"我转了一下门把手，发现门开着。"}},{"pos":"N-COUNT 可数名词","cn":"（工具、包、杯等的）柄，把手，提手","en":"A handle is the part of an object such as a tool, bag, or cup that you hold in order to be able to pick up and use the object.","ex":{"en":"The handle of a cricket bat protruded from under his arm.","cn":"一个板球拍柄从他的胳肢窝下面伸了出来。"}},{"pos":"VERB 动词","cn":"有能力应付;（成功地）处理","en":"If you say that someone can handle a problem or situation, you mean that they have the ability to deal with it successfully.","ex":{"en":"To tell the truth, I don't know if I can handle the job","cn":"说实话，我不知道自己是否能做好这份工作。"}},{"pos":"VERB 动词","cn":"（以…方式）应付，处理","en":"If you talk about the way that someone handles a problem or situation, you mention whether or not they are successful in achieving the result they want.","ex":{"en":"I think I would handle a meeting with Mr. Siegel very badly","cn":"我觉得和西格尔先生会谈我可能会搞得一团糟。"}},{"pos":"VERB 动词","cn":"负责（某项工作）","en":"If you handle a particular area of work, you have responsibility for it.","ex":{"en":"She handled travel arrangements for the press corps during the presidential campaign","cn":"她负责了总统竞选活动期间新闻报道团的行程安排。"}},{"pos":"VERB 动词","cn":"使用，操纵（武器、车辆等）;训练，使唤（动物）","en":"When you handle something such as a weapon, vehicle, or animal, you use it or control it, especially by using your hands.","ex":{"en":"I had never handled an automatic.","cn":"我从未用过自动手枪。"}},{"pos":"VERB 动词","cn":"（车辆等容易）操纵，驾驶","en":"If something such as a vehicle handles well, it is easy to use or control.","ex":{"en":"His ship had handled like a dream!","cn":"他的船操纵起来非常灵便。"}},{"pos":"VERB 动词","cn":"拿;抓;搬动","en":"When you handle something, you hold it or move it with your hands.","ex":{"en":"Wear rubber gloves when handling cat litter.","cn":"清理猫粪时要带上橡胶手套。"}},{"pos":"N-SING 单数名词","cn":"（理解、解决问题的）方法，途径","en":"If you have a handle on a subject or problem, you have a way of approaching it that helps you to understand it or deal with it.","ex":{"en":"When you have got a handle on your anxiety you can begin to control it.","cn":"一旦了解了自己焦虑的原因，你就开始能控制它了。"}},{"pos":"PHRASE 短语","cn":"大发脾气;勃然大怒","en":"If you fly off the handle, you suddenly and completely lose your temper.","ex":{"en":"He flew off the handle at the slightest thing.","cn":"他为一点小事就大发脾气。"}}]},"media":{"img":["media/pic/handle_comp.jpg","media/thumb/handle.jpg"],"uk":"media/uk/handle__gb_1.mp3","us":"media/us/handle__us_1.mp3"},"examples":[{"en":"We can handle up to 500 calls an hour at our new offices.","cn":"我们的新办公室每小时可处理 500 通电话。"},{"en":"( informal ) ‘Any problems?’ ‘Nothing I can't handle. ’ “","cn":"有问题吗？” “没有什么我不能对付的。”"}]},"harlequin":{"media":{"uk":"media/uk/harlequin__gb_1.mp3","us":"media/us/harlequin__us_1.mp3"},"oxford":{"phon":"ˈhɑːləkwɪn","pos":"noun","senses":[{"en":"a humorous character in some traditional plays, who wears special brightly coloured clothes with a diamond pattern","cn":"（传统戏剧中穿色彩斑斓菱形花纹服装的）滑稽角色"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（常为菱形图案组成的）五颜六色的","en":"You use harlequin to describe something that has a lot of different colours, often in a diamond pattern.","ex":{"en":"...the striking harlequin floor.","cn":"醒目的彩色地板"}}]}},"haul":{"media":{"uk":"media/uk/haul__gb_1.mp3","us":"media/us/haul__us_1.mp3"},"oxford":{"phon":"hɔːl","pos":"verb","senses":[{"en":"to pull something/somebody with a lot of effort","cn":"（用力）拖，拉，拽","ex":{"en":"The wagons were hauled by horses.","cn":"那些货车是马拉的。"}},{"en":"to move yourself somewhere slowly and with a lot of effort","cn":"用力缓慢挪动到（某处）","ex":{"en":"She hauled herself out of bed.","cn":"她费劲地下了床。"}},{"en":"to force somebody to go somewhere they do not want to go","cn":"强迫（某人）去某处","ex":{"en":"A number of suspects have been hauled in for questioning.","cn":"一批嫌疑犯被拘捕接受讯问。"}},{"en":"to make somebody appear in court in order to be judged","cn":"使某人出庭受审；把某人提交法庭","g":"[usually passive]","ex":{"en":"He was hauled up before the local magistrates for dangerous driving.","cn":"他因危险驾驶而被移交地方法庭审判。"}},{"en":"a large amount of something that has been stolen or that is illegal","cn":"大批赃物；大量非法物品","ex":{"en":"a haul of weapons","cn":"大批非法武器"},"pos":"noun"},{"en":"a large number of points, goals, etc.","cn":"很高的得分","ex":{"en":"His haul of 40 goals in a season is a record.","cn":"他在一个赛季中得了 40 分，创下了纪录。"},"pos":"noun"},{"en":"the distance covered in a particular journey","cn":"旅行的距离；旅程","g":"[usually singular]","ex":{"en":"They began the long slow haul to the summit.","cn":"他们踏上了攀登顶峰的漫长行程。"},"pos":"noun"},{"en":"a quantity of fish caught at one time","cn":"一次捕获的鱼；一网鱼","ex":{"en":"The fishermen had a good haul.","cn":"渔民捕得满满一网鱼。"},"pos":"noun"},{"en":"a hard pull","cn":"（用力的）拖，拉，拽","g":"[usually singular]","ex":{"en":"When I shout, give a haul on the rope.","cn":"听到我喊就用力拉绳子。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(用力地）拉，拖","en":"If you haul something which is heavy or difficult to move, you move it using a lot of effort.","ex":{"en":"A crane had to be used to haul the car out of the stream","cn":"只好用了起重机，才将轿车从河里拖出来。"}},{"pos":"VERB 动词","cn":"使出庭受审;使去见掌权者","en":"If someone is hauled before a court or someone in authority, they are made to appear before them because they are accused of having done something wrong.","ex":{"en":"She was hauled before magistrates for refusing to reveal her age to a policeman","cn":"她因拒绝告诉警察自己的年龄而被地方法院传讯。"}},{"pos":"N-COUNT 可数名词","cn":"（警方或海关查获的）一批赃物，一批违禁品","en":"A haul is a quantity of things that are stolen, or a quantity of stolen or illegal goods found by police or customs.","ex":{"en":"The size of the drugs haul shows that the international trade in heroin is still flourishing","cn":"本次查获的毒品量表明，海洛因在国际上的交易仍很猖獗。"}},{"pos":"PHRASE 短语","cn":"费时费力的事;耗时累人的行程","en":"If you say that a task or a journey is a long haul, you mean that it takes a long time and a lot of effort.","ex":{"en":"Revitalising the Romanian economy will be a long haul.","cn":"罗马尼亚经济的复兴将是一项长期而艰巨的工作。"}}]},"examples":[{"en":"His haul of 40 goals in a season is a record.","cn":"他在一个赛季中得了 40 分，创下了纪录。"},{"en":"He was hauled up before the local magistrates for dangerous driving.","cn":"他因危险驾驶而被移交地方法庭审判。"}]},"halfway":{"media":{"uk":"media/uk/halfway__gb_1.mp3","us":"media/us/halfway__us_1.mp3"},"oxford":{"phon":"ˌhɑːfˈweɪ","pos":"adjective","senses":[{"en":"at an equal distance between two points; in the middle of a period of time","cn":"在…的中间；在中途；到一半","ex":{"en":"I got the ball on the halfway line.","cn":"我在中场线拿到了球。"}},{"en":"part of the way towards doing or achieving something","cn":"部分地做（或达到）…","ex":{"en":"the halfway point/stage","cn":"中间点／阶段"}},{"en":"at an equal distance between two points; in the middle of a period of time","cn":"在…的中间；在中途；到一半","ex":{"en":"It's about halfway between London and Bristol.","cn":"它大约位于伦敦和布里斯托尔的中间。"},"pos":"adverb"},{"en":"part of the way towards doing or achieving something","cn":"部分地做（或达到）…","ex":{"en":"This only goes halfway to explaining what really happened.","cn":"这只是部分地解释了实际发生的事。"},"pos":"adverb"},{"en":"fairly, but not very, good","cn":"还不错的；过得去的","lab":"informal","ex":{"en":"Any halfway decent map will give you that information.","cn":"任何一张还算像样的地图都能提供那些信息。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（空间上）在中间，在中途","en":"Halfway means in the middle of a place or between two points, at an equal distance from each of them.","ex":{"en":"Half-way across the car-park, he noticed she was walking with her eyes closed","cn":"走到停车场中间时，他看到她在闭着眼走路。"}},{"pos":"ADV 副词","cn":"（时间）到一半;（事情）进行到中途","en":"Halfway means in the middle of a period of time or of an event.","ex":{"en":"By then, it was October and we were more than halfway through our tour.","cn":"那时已是10月，我们已经完成了行程的一大半了。"}},{"pos":"PHRASE 短语","cn":"对…作部分让步;与…妥协","en":"If you meet someone halfway, you accept some of the points they are making so that you can come to an agreement with them.","ex":{"en":"The Democrats are willing to meet the president halfway.","cn":"民主党人愿意向总统作部分让步。"}},{"pos":"ADV 副词","cn":"过得去地;大致上","en":"Halfway means reasonably.","ex":{"en":"You need hard currency to get anything halfway decent","cn":"你得有硬通货才能买到还算不错的东西。"}}]},"examples":[{"en":"Any halfway decent map will give you that information.","cn":"任何一张还算像样的地图都能提供那些信息。"},{"en":"It's about halfway between London and Bristol.","cn":"它大约位于伦敦和布里斯托尔的中间。"}]},"habit":{"media":{"uk":"media/uk/habit__gb_1.mp3","us":"media/us/habit__us_1.mp3"},"oxford":{"phon":"ˈhæbɪt","pos":"noun","senses":[{"en":"a thing that you do often and almost without thinking, especially something that is hard to stop doing","cn":"习惯","g":"[countable]","ex":{"en":"You need to change your eating habits.","cn":"你得改变你的饮食习惯。"}},{"en":"usual behaviour","cn":"惯常行为；习性","g":"[uncountable]","ex":{"en":"I only do it out of habit.","cn":"我这么做只是出于习惯。"}},{"en":"a strong need to keep using drugs, alcohol or cigarettes regularly","cn":"（吸毒、喝酒、抽烟的）瘾","g":"[countable]","lab":"informal","ex":{"en":"He began to finance his habit through burglary.","cn":"他开始靠盗窃来获取可满足他毒瘾的钱。"}},{"en":"a long piece of clothing worn by a monk or nun","cn":"（修道士或修女穿的）长袍；道袍；道服","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"习惯","en":"A habit is something that you do often or regularly.","ex":{"en":"He has an endearing habit of licking his lips when he's nervous","cn":"他有个一紧张就舔嘴唇的可爱习惯。"}},{"pos":"N-COUNT 可数名词","cn":"坏习惯;积习;恶习;陋习","en":"A habit is an action which is considered bad that someone does repeatedly and finds it difficult to stop doing.","ex":{"en":"A good way to break the habit of eating too quickly is to put your knife and fork down after each mouthful","cn":"改掉吃饭太快的坏习惯有一个好办法，那就是每吃一口就把刀叉放下。"}},{"pos":"N-COUNT 可数名词","cn":"（吸食海洛因、可卡因等的）毒瘾","en":"A drug habit is an addiction to a drug such as heroin or cocaine.","ex":{"en":"She became a prostitute in order to pay for her cocaine habit.","cn":"她以娼养吸。"}},{"pos":"N-COUNT 可数名词","cn":"（修道士或修女穿的）长袍，道袍，道服","en":"A habit is a piece of clothing shaped like a long loose dress, which a nun or monk wears."},{"pos":"PHRASE 短语","cn":"按习惯行事的人;习惯的奴隶","en":"If you say that someone is a creature of habit, you mean that they usually do the same thing at the same time each day, rather than doing new and different things."},{"pos":"PHRASE 短语","cn":"有/养成…的习惯;习惯于","en":"If you are in the habit of doing something, you do it regularly or often. If you get into the habit of doing something, you begin to do it regularly or often.","ex":{"en":"They were in the habit of giving two or three dinner parties a month","cn":"他们每月举办两三次宴会，都成习惯了。"}},{"pos":"PHRASE 短语","cn":"对做…习以为常;使…成为一种习惯","en":"If you make a habit of doing something, you do it regularly or often.","ex":{"en":"You can phone me at work as long as you don't make a habit of it.","cn":"你可以上班时给我打电话，只要别一来二去打上瘾了就成。"}},{"pos":"PHRASE 短语","cn":"思维习惯","en":"If someone has a particular habit of mind, they usually think in that particular way.","ex":{"en":"In accent, mannerism and habit of mind he appeared to be completely Eastern European.","cn":"从口音、举止和思维习惯上看，他完全是东欧人。"}}]},"examples":[{"en":"He began to finance his habit through burglary.","cn":"他开始靠盗窃来获取可满足他毒瘾的金钱。"},{"en":"It's all right to borrow money occasionally, but don't let it become a habit.","cn":"偶尔借点钱倒没关系，但不要养成习惯。"}]},"halo":{"media":{"uk":"media/uk/halo__gb_1.mp3","us":"media/us/halo__us_1.mp3"},"oxford":{"phon":"ˈheɪləʊ","pos":"noun","senses":[{"en":"(in paintings, etc.) a circle of light shown around or above the head of a holy person","cn":"（绘画等中环绕圣人头上的）光环，光轮","lab":"figurative","ex":{"en":"She played the part of an angel, complete with wings and a halo.","cn":"她扮演天使，身上的双翼和头上的光轮一应俱全。"}},{"en":"a corona (= a ring of light seen around the sun or moon, especially during an eclipse)","cn":"（日、月或其他发光体的）光晕，晕圈","lab":"informal"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（绘画中圣人、天使头上的）光环，光轮","en":"A halo is a circle of light that is shown in pictures round the head of a holy figure such as a saint or angel."},{"pos":"N-COUNT 可数名词","cn":"晕;晕状物","en":"A halo is a circle of light round a person or thing, or something that looks like a circle of light.","ex":{"en":"The sun had a faint halo round it","cn":"环绕太阳有圈淡淡的光晕。"}}]},"examples":[{"en":"She played the part of an angel, complete with wings and a halo.","cn":"她扮演天使，身上的双翼和头上的光轮一应俱全。"},{"en":"( figurative ) a halo of white frizzy hair","cn":"一圈白色鬈发"}]},"happiness":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling of being happy","cn":""},{"en":"the feeling you have when you enjoy doing something, or when something happens that you enjoy","cn":""}]},"examples":[{"en":"Juliet’s eyes shone with happiness.","cn":"朱丽叶的双眼闪耀着幸福的光芒。","src":"ld"},{"en":"We want our children to have the best possible chance of happiness.","cn":"我们希望自己的孩子得到追求幸福的最佳机会。","src":"ld"}],"media":{"uk":"media/uk/happiness__gb_1.mp3","us":"media/us/happiness__us_1.mp3"},"oxford":{"phon":"ˈhæpinəs","pos":"noun","senses":[{"en":"the state of feeling or showing pleasure","cn":"快乐；高兴","ex":{"en":"to find true happiness","cn":"找到真正的幸福"}},{"en":"the state of being satisfied that something is good or right","cn":"满意","ex":{"en":"The meeting expressed happiness about the progress made.","cn":"会上大家对进展表示满意。"}}]}},"harm":{"oxford":{"phon":"hɑːm","pos":"noun","senses":[{"en":"damage or injury that is caused by a person or an event","cn":"伤害；损害","ex":{"en":"He would never frighten anyone or cause them any harm.","cn":"他永远不会吓唬或伤害任何人。"}},{"en":"to hurt or injure somebody or to damage something","cn":"伤害；损害","ex":{"en":"He would never harm anyone.","cn":"他永远不会伤害任何人。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（通常为故意地）伤害，危害","en":"To harm a person or animal means to cause them physical injury, usually on purpose.","ex":{"en":"The hijackers seemed anxious not to harm anyone.","cn":"劫持犯似乎焦虑不安，不想伤害任何人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（通常为故意的）伤害，危害","en":"Harm is physical injury to a person or an animal which is usually caused on purpose.","ex":{"en":"All dogs are capable of doing harm to human beings.","cn":"只要是狗就可能会咬人。"}},{"pos":"VERB 动词","cn":"破坏;损害;对…产生不利影响","en":"To harm a thing, or sometimes a person, means to damage them or make them less effective or successful than they were.","ex":{"en":"...a warning that the product may harm the environment","cn":"该产品可能会危害环境的警告"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（某一行为造成的）损害，危害","en":"Harm is the damage to something which is caused by a particular course of action.","ex":{"en":"The abuse of your powers does harm to all other officers who do their job properly","cn":"滥用权力会对其他所有恪守职责的官员们造成伤害。"}},{"pos":"PHRASE 短语","cn":"不会受损害;不会受到伤害;会安然无恙","en":"If you say that someone or something will come to no harm or that no harm will come to them, you mean that they will not be hurt or damaged in any way.","ex":{"en":"There is always a lifeguard to ensure that no one comes to any harm","cn":"总是有一个救生员在场以确保无人受到伤害。"}},{"pos":"PHRASE 短语","cn":"也许值得（做某事）;不妨（做某事）","en":"If you say it does no harm to do something or there is no harm in doing something, you mean that it might be worth doing, and you will not be blamed for doing it.","ex":{"en":"They are not always willing to take on untrained workers, but there's no harm in asking.","cn":"他们并不总是乐意雇用未经培训的工人，但问问也无妨。"}},{"pos":"PHRASE 短语","cn":"（做某事）没有坏处，有益;不妨（做某事）","en":"If you say that something would do no harm, or do someone no harm, you are recommending a course of action which you think is worthwhile, helpful, or useful.","ex":{"en":"It would do her no harm to try them until we found the one which suited her best.","cn":"她不妨把这些都试试，直到我们找到最适合她的为止。"}},{"pos":"PHRASE 短语","cn":"没有产生危害;没有人受到伤害","en":"If you say that there is no harm done, you are telling someone not to worry about something that has happened because it has not caused any serious injury or damage.","ex":{"en":"There, now, you're all right. No harm done.","cn":"好了，你现在没事了，没人受伤。"}},{"pos":"PHRASE 短语","cn":"处于危险中","en":"If someone is put in harm's way, they are caused to be in a dangerous situation.","ex":{"en":"These men were never told how they'd been put in harm's way","cn":"从来没人告诉这些人他们是如何被置于险境的。"}},{"pos":"PHRASE 短语","cn":"在安全的地方;没有危险","en":"If someone or something is out of harm's way, they are in a safe place away from danger or from the possibility of being damaged.","ex":{"en":"For parents, it is an easy way of keeping their children entertained, or simply out of harm's way","cn":"对父母来说，这是一个能让孩子们开心或者说是让他们远离危险的简单方法。"}}]},"media":{"uk":"media/uk/harm__gb_1.mp3","us":"media/us/harm__us_1.mp3"},"examples":[{"en":"The accident could have been much worse; luckily no harm was done.","cn":"这次事故本来可能糟糕得多；所幸没有造成伤害。"},{"en":"I can't say I like Mark very much, but I don't wish him any harm.","cn":"我不能说我很喜欢马克，但我并不愿他遭到伤害。"}]},"haven":{"oxford":{"phon":"ˈheɪvn","pos":"noun","senses":[{"en":"a place that is safe and peaceful where people or animals are protected","cn":"安全的地方；保护区；避难所","ex":{"en":"The hotel is a haven of peace and tranquillity.","cn":"这家旅馆是一个安宁的去处。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"安全处所;庇护所;避难所","en":"A haven is a place where people or animals feel safe, secure, and happy.","ex":{"en":"It's a real haven at the end of a busy working day.","cn":"忙碌了一整天后，这真是一个安乐窝。"}}]},"media":{"uk":"media/uk/haven__gb_1.mp3","us":"media/us/haven__us_1.mp3"},"examples":[{"en":"The river banks are a haven for wildlife.","cn":"河的两岸是野生动物的自然栖息地。"},{"en":"The hotel is a haven of peace and tranquility.","cn":"这家旅馆是一处安宁的去处。"}]},"harvest":{"media":{"uk":"media/uk/harvest__gb_1.mp3","us":"media/us/harvest__us_1.mp3"},"oxford":{"phon":"ˈhɑːvɪst","pos":"noun","senses":[{"en":"the time of year when the crops are gathered in on a farm, etc.; the act of cutting and gathering crops","cn":"收获季节；收割；收获","g":"[countable, uncountable]","ex":{"en":"harvest time","cn":"收获季节"}},{"en":"the crops, or the amount of crops, cut and gathered","cn":"收成；收获量","g":"[countable]","lab":"figurative","ex":{"en":"the grain harvest","cn":"谷物的收成"}},{"en":"to cut and gather a crop; to catch a number of animals or fish to eat","cn":"收割（庄稼）；捕猎（动物、鱼）","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"The nuts are ready to harvest in September.","cn":"九月份坚果就可以收获了。"},"pos":"verb"},{"en":"to collect cells or tissue from somebody’s body for use in medical experiments or operations","cn":"采集（人体的细胞或组织，以供医学实验等）","g":"[transitive]","lab":"medical","ex":{"en":"She had her eggs harvested and frozen for her own future use.","cn":"她做了卵子采集，冷冻以备将来使用。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"收获;收割","en":"The harvest is the gathering of a crop.","ex":{"en":"There were about 300 million tons of grain in the fields at the start of the harvest.","cn":"收获伊始地里大概有3亿吨粮食。"}},{"pos":"N-COUNT 可数名词","cn":"收成;收获量","en":"A harvest is the crop that is gathered in.","ex":{"en":"...a bumper potato harvest","cn":"马铃薯大丰收"}},{"pos":"VERB 动词","cn":"收获;收割","en":"When you harvest a crop, you gather it in.","ex":{"en":"Many farmers are refusing to harvest the cane.","cn":"很多农民正拒绝收割甘蔗。"}},{"pos":"VERB 动词","cn":"获取;收获","en":"If you harvest a large number of things, you collect them, often by making great efforts.","ex":{"en":"In his new career as a restaurateur he has blossomed and harvested many awards.","cn":"转行经营餐饮之后，他在事业上大获成功并获得了许多奖项。"}},{"pos":"PHRASE 短语","cn":"获得成果;尝到苦果","en":"If you reap the harvest, you benefit or suffer from the results of your past actions or of someone else's past actions.","ex":{"en":"The Israeli Prime Minister must be convinced that he will reap a richer harvest of votes by going to the electorate well before October.","cn":"必须说服以色列总理，若在10月份前就尽早走近选民，他会赢得更多选票。"}}]},"examples":[{"en":"( figurative ) The appeal produced a rich harvest of blankets, medicines and clothing.","cn":"呼吁的成果颇丰，收到了大批毛毯、药物和衣服。"},{"en":"She had her eggs harvested and frozen for her own future use.","cn":"她的卵子已经采集下来，冷冻后以备她将来使用。"}]},"hayes":{"oxford":{"phon":"heɪ","pos":"noun","senses":[{"en":"grass that has been cut and dried and is used as food for animals （","cn":"用作饲料的）干草，草料"},{"en":"( NAmE ) ( informal ) a small amount of money","cn":"少量的钱"}]},"media":{"uk":"media/uk/hay__gb_1.mp3","us":"media/us/hay__us_1.mp3"}},"haunting":{"media":{"uk":"media/uk/haunting__gb_1.mp3","us":"media/us/haunting__us_1.mp3"},"oxford":{"phon":"ˈhɔːntɪŋ","pos":"adjective","senses":[{"en":"beautiful, sad or frightening in a way that cannot be forgotten","cn":"萦绕心头的；使人难忘的","ex":{"en":"a haunting melody/experience/image","cn":"难以忘怀的优美乐曲；痛苦难忘的经历；难忘的形象"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（声音、形象、话语等）令人难忘的，萦绕心头的","en":"Haunting sounds, images, or words remain in your thoughts because they are very beautiful or sad.","ex":{"en":"...the haunting calls of wild birds in the mahogany trees.","cn":"红木树林中野鸟令人难忘的鸣叫声"}}]},"examples":[{"en":"a haunting melody/experience/image","cn":"难以忘怀的优美乐曲；痛苦难忘的经历；吓人难忘的形象"},{"en":"a haunting melody","cn":"萦绕心头的旋律"}]},"haphazardly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done in a careless and lazy way - use this about someone's work or the way someone writes or speaks","cn":""},{"en":"done extremely carelessly and quickly, without paying any attention to the correct ways of working","cn":""}]},"media":{"uk":"media/uk/haphazardly__gb_1.mp3","us":"media/us/haphazardly__us_1.mp3"},"oxford":{"phon":"hæpˈhæzədli","pos":"adverb","senses":[{"en":"in a way that has no particular order or plan; in a way that is not organized well","cn":"没有特别的顺序或者计划；以一种没有组织好的方式","ex":{"en":"Vehicles are parked haphazardly on the narrow streets.","cn":"狭窄的街道上，车辆随意停放。"}}]}},"had":{"media":{"uk":"media/uk/had__gb_1.mp3","us":"media/us/had__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"Had is the past tense and past participle of have ."},{"pos":"AUX 助动词","cn":"（had 有时代替 if 用于从句句首，表示某种情况可能发生但并未发生）","en":"Had is sometimes used instead of 'if' to begin a clause which refers to a situation that might have happened but did not. For example, the clause 'had he been elected' means the same as 'if he had been elected'.","ex":{"en":"Had he succeeded, he would have acquired a monopoly","cn":"要是他当时成功了，他就会取得垄断地位。"}},{"pos":"PHRASE 短语","cn":"上当受骗","en":"If you have been had, someone has tricked you, for example by selling you something at too high a price.","ex":{"en":"If your customer thinks he's been had, you have to make him happy.","cn":"要是顾客感觉自己当了冤大头，你就得设法让他消气。"}},{"pos":"PHRASE 短语","cn":"遇到大麻烦;无望成功","en":"If you say that someone has had it, you mean they are in very serious trouble or have no hope of succeeding.","ex":{"en":"Unless she loses some weight, she's had it","cn":"除非她减点儿肥，否则她就没戏了。"}},{"pos":"PHRASE 短语","cn":"受够了;忍受不了","en":"If you say that you have had it, you mean that you are very tired of something or very annoyed about it, and do not want to continue doing it or it to continue happening.","ex":{"en":"I've had it. Let's call it a day","cn":"我受不了了。今天就到这儿吧。"}}]}},"handful":{"media":{"uk":"media/uk/handful__gb_1.mp3","us":"media/us/handful__us_1.mp3"},"oxford":{"phon":"ˈhændfʊl","pos":"noun","senses":[{"en":"the amount of something that can be held in one hand","cn":"一把（的量）；用手抓起的数量","g":"[countable]","ex":{"en":"a handful of rice","cn":"一把米"}},{"en":"a small number of people or things","cn":"少数人（或物）","g":"[singular]","ex":{"en":"Only a handful of people came.","cn":"只有少数几个人来了。"}},{"en":"a person or an animal that is difficult to control","cn":"难以控制的人（或动物）","g":"[singular]","lab":"informal","ex":{"en":"Her children can be a real handful.","cn":"她的孩子们有时很难管教。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"几个;少数","en":"A handful of people or things is a small number of them.","ex":{"en":"He surveyed the handful of customers at the bar","cn":"他打量着吧台那边零星的几个顾客。"}},{"pos":"N-COUNT 可数名词","cn":"一把","en":"A handful of something is the amount of it that you can hold in your hand.","ex":{"en":"She scooped up a handful of sand and let it trickle through her fingers.","cn":"她抓起一把沙子，让它从指缝里一点点漏下来。"}},{"pos":"N-SING 单数名词","cn":"难管的人（尤指孩子）","en":"If you say that someone, especially a child, is a handful, you mean that they are difficult to control.","ex":{"en":"Zara can be a handful sometimes.","cn":"扎拉有时很难管教。"}}]},"examples":[{"en":"Her children can be a real handful.","cn":"她的孩子们有时很难管教。"},{"en":"Only a handful of people came.","cn":"只有少数几个人来了。"}]},"hammered":{"media":{"uk":"media/uk/hammered__gb_1.mp3","us":"media/us/hammered__us_1.mp3"},"oxford":{"phon":"ˈhæməd","pos":"adjective","senses":[{"en":"very drunk","cn":"烂醉"}]}},"harmonize":{"oxford":{"phon":"ˈhɑːmənaɪz","pos":"verb","senses":[{"en":"if two or more things harmonize with each other or one thing harmonizes with the other, the things go well together and produce an attractive result","cn":"（和某事物）协调，和谐","g":"[intransitive]","ex":{"en":"The new building does not harmonize with its surroundings.","cn":"那栋新楼与周围环境不协调。"}},{"en":"to make systems or rules similar in different countries or organizations","cn":"使（不同国家或组织的体制或规则）相一致；使协调","g":"[transitive]","ex":{"en":"the need to harmonize tax levels across the European Union","cn":"使欧盟各国的税收标准相一致的必要"}},{"en":"to play or sing music that combines with the main tune to make a pleasant sound","cn":"为（主调）配和声","g":"[intransitive]","ex":{"en":"Sally sang the melody while I harmonized.","cn":"当我和声时，莎莉唱着旋律。"}}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"（与…）融洽，和谐，与…协调一致","en":"If two or more things harmonize with each other, they fit in well with each other.","ex":{"en":"...slabs of pink and beige stone that harmonize with the carpet","cn":"与地毯协调搭配的粉色和米色相间的石板"}},{"pos":"VERB 动词","cn":"使（法律、制度或规则）协调;使统一","en":"When governments or organizations harmonize laws, systems, or regulations, they agree in a friendly way to make them the same or similar.","ex":{"en":"How far will members have progressed towards harmonising their economies?","cn":"各成员国在使彼此经济协调一致的进程上会有多大进展？"}},{"pos":"VERB 动词","cn":"用和声唱（或演奏）;为（主调）配和声","en":"When people harmonize, they sing or play notes which are different from the main tune but which sound nice with it.","ex":{"en":"Bremer and Garland harmonize on the title song, 'Meet Me in St. Louis'.","cn":"布雷默和加兰为主题曲《相逢圣路易斯》配和声。"}}]},"media":{"uk":"media/uk/harmonize__gb_1.mp3","us":"media/us/harmonize__us_1.mp3"},"examples":[{"en":"the need to harmonize tax levels across the European Union","cn":"使欧盟各国的税收标准相一致的必要"},{"en":"The new building does not harmonize with its surroundings.","cn":"那栋新楼与周围环境不协调。"}]},"hacker":{"media":{"uk":"media/uk/hacker__gb_1.mp3","us":"media/us/hacker__us_1.mp3"},"oxford":{"phon":"ˈhækə(r)","pos":"noun","senses":[{"en":"a person who uses computers to get access to data in somebody else's computer or phone system without permission","cn":"黑客（在未经许可的情况下侵入他人计算机或手机系统以获取信息的人）"},{"en":"a person who uses or writes computer programs with enthusiasm and skill","cn":"黑客：以热情和技巧使用或编写计算机程序的人","lab":"informal","ex":{"en":"The software is so complicated that only experienced hackers can use it.","cn":"该软件非常复杂，只有经验丰富的黑客才能使用。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指盗取他人计算机系统中保密信息的）黑客","en":"A computer hacker is someone who tries to break into computer systems, especially in order to get secret information."},{"pos":"N-COUNT 可数名词","cn":"黑客（指沉迷于电脑之中，无暇顾及其他的电脑迷）","en":"A computer hacker is someone who uses a computer a lot, especially so much that they have no time to do anything else."}]},"examples":[{"en":"A hacker had managed to get into the system.","cn":"一个黑客设法侵入了系统。"}]},"hard-pressed":{"oxford":{"phon":"ˌhɑːd ˈprest","pos":"adjective","senses":[{"en":"having a lot of problems, especially too much work, and too little time or money","cn":"处于强大压力下的（尤指工作重、时间紧、资金少）","ex":{"en":"Hard-pressed junior doctors want shorter working hours.","cn":"实习医生压力太大，希望缩短工作时间。"}},{"en":"finding something very difficult to do","cn":"很难（做某事）","ex":{"en":"You would be hard-pressed to find a better secretary.","cn":"找一位更好的秘书很难。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"处于困境的;经济窘迫的;承受高压的","en":"If someone is hard-pressed, they are under a great deal of strain and worry, usually because they have not got enough money.","ex":{"en":"The region's hard-pressed consumers are spending less on luxuries.","cn":"该地区的消费者经济窘迫，在奢侈品上的开销比以前少了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很难做到的;（做…）有困难的","en":"If you will be hard-pressed to do something, you will have great difficulty doing it.","ex":{"en":"This year the airline will be hard-pressed to make a profit.","cn":"今年该航空公司将很难赢利。"}}]},"media":{"uk":"media/uk/hard_pressed_1_gb_1.mp3","us":"media/us/hard_pressed_1_us_1.mp3"},"examples":[{"en":"You would be hard-pressed to find a better secretary.","cn":"找一位更好的秘书很难。"},{"en":"The new exams will only add to the workload of already hard-pressed teachers.","cn":"新推出的考试只会给原本就承受巨大压力的老师们增加工作负担。"}]},"harmonized":{"oxford":{"phon":"ˈhɑːmənaɪz","pos":"verb","senses":[{"en":"if two or more things harmonize with each other or one thing harmonizes with the other, the things go well together and produce an attractive result （","cn":"和某事物）协调，和谐"},{"en":"to make systems or rules similar in different countries or organizations","cn":"使（不同国家或组织的体制或规则）相一致；使协调"}]}},"haunted":{"media":{"uk":"media/uk/haunted__gb_1.mp3","us":"media/us/haunted__us_1.mp3"},"oxford":{"phon":"ˈhɔːntɪd","pos":"adjective","senses":[{"en":"believed to be visited by ghosts","cn":"（被认为）闹鬼的，有鬼魂出没的","ex":{"en":"a haunted house","cn":"闹鬼的房子"}},{"en":"showing that somebody is very worried","cn":"忧心忡忡的；满面愁容的","ex":{"en":"There was a haunted look in his eyes.","cn":"他眼中透露出忧虑的神色。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（房屋等）有鬼魂出没的，闹鬼的","en":"A haunted building or other place is one where a ghost regularly appears.","ex":{"en":"Tracy said the cabin was haunted.","cn":"特蕾西说小木屋闹鬼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表情）焦虑的，忧心忡忡的","en":"Someone who has a haunted expression looks very worried or troubled.","ex":{"en":"She looked so haunted, I almost didn't recognize her.","cn":"她愁容满面，我差点儿没认出她来。"}}]},"examples":[{"en":"There was a haunted look in his eyes.","cn":"他眼中透露出忧虑的神色。"},{"en":"a haunted house","cn":"闹鬼的房子"}]},"hairless":{"media":{"uk":"media/uk/hairless__gb_1.mp3","us":"media/us/hairless__us_1.mp3"},"oxford":{"phon":"ˈheələs","pos":"adjective","senses":[{"en":"without hair","cn":"无发的；无毛的；秃的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（身体部位）无毛的，光秃秃的","en":"A part of your body that is hairless has no hair on it.","ex":{"en":"...a smooth and hairless body.","cn":"光滑无毛的身体"}}]},"examples":[{"en":"Young rabbits are born blind and hairless.","cn":"小兔子生下来时看不见东西﹐而且没有毛。"}]},"harmed":{"oxford":{"phon":"hɑːm","pos":"noun","senses":[{"en":"damage or injury that is caused by a person or an event","cn":"伤害；损害"},{"en":"used to suggest that it would be a good idea for sb to do sth （","cn":"做某事）不会对某人有坏处；不妨"}]}},"harbour":{"media":{"uk":"media/uk/harbour__gb_1.mp3","us":"media/us/harbour__us_1.mp3"},"oxford":{"phon":"ˈhɑːbə(r)","pos":"noun","senses":[{"en":"an area of water on the coast, protected from the open sea by strong walls, where ships can shelter","cn":"（海）港；港口；港湾","lab":"figurative","ex":{"en":"Several boats lay at anchor in the harbour.","cn":"港湾里停泊着几条船。"}},{"en":"to hide and protect somebody who is hiding from the police","cn":"窝藏，庇护（罪犯等）","ex":{"en":"Police believe someone must be harbouring the killer.","cn":"警方相信一定有人窝藏了杀人犯。"},"pos":"verb"},{"en":"to keep feelings or thoughts, especially negative ones, in your mind for a long time","cn":"怀有，心怀（尤指负面感情或想法）","ex":{"en":"The arsonist may harbour a grudge against the company.","cn":"纵火犯可能对公司怀恨在心。"},"pos":"verb"},{"en":"to contain something and allow it to develop","cn":"包含；藏有","ex":{"en":"Your dishcloth can harbour many germs.","cn":"洗碗布中可能藏有很多病菌。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"海港;港口;港湾","en":"A harbour is an area of the sea at the coast which is partly enclosed by land or strong walls, so that boats can be left there safely.","ex":{"en":"She led us to a room with a balcony overlooking the harbour","cn":"她把我们领进了一个带阳台的房间，从那里可以俯瞰海港。"}},{"pos":"VERB 动词","cn":"心怀，怀藏，怀有（情感、想法或秘密）","en":"If you harbour an emotion, thought, or secret, you have it in your mind over a long period of time.","ex":{"en":"He might have been murdered by a former client or someone harbouring a grudge","cn":"他可能已经被以前的客户或某个对他怀恨在心的人谋杀了。"}},{"pos":"VERB 动词","cn":"窝藏，庇护（罪犯）","en":"If a person or country harbours someone who is wanted by the police, they let them stay in their house or country and offer them protection.","ex":{"en":"Accusations of harbouring suspects were raised against the former Hungarian leadership.","cn":"匈牙利前领导层被指控窝藏嫌犯。"}}]},"examples":[{"en":"Police believe someone must be harbouring the killer.","cn":"警方相信一定有人窝藏了杀人犯。"},{"en":"The arsonist may harbour a grudge against the company.","cn":"纵火犯可能对公司怀恨在心。"}]},"hang":{"media":{"uk":"media/uk/hang__gb_1.mp3","us":"media/us/hang__us_1.mp3"},"oxford":{"phon":"hæŋ","pos":"verb","senses":[{"en":"to attach something, or to be attached, at the top so that the lower part is free or loose","cn":"悬挂；吊","g":"[transitive, intransitive]","lab":"British English","sc":"attach from top","ex":{"en":"Hang your coat on the hook.","cn":"把你的大衣挂在衣钩上。"}},{"en":"when something hangs in a particular way, it falls in that way","cn":"垂下；垂落","g":"[intransitive]","sc":"fall loosely","ex":{"en":"Her hair hung down to her waist.","cn":"她的长发垂及腰际。"}},{"en":"to bend or let something bend downwards","cn":"（使）低垂，下垂","g":"[intransitive, transitive]","sc":"bend downwards","ex":{"en":"The dog's tongue was hanging out.","cn":"狗的舌头耷拉在外面。"}},{"en":"to kill somebody by tying a rope around their neck and allowing them to drop; to be killed in this way","cn":"（被）绞死，施以绞刑","g":"[transitive, intransitive]","sc":"kill somebody","ex":{"en":"He was the last man to be hanged for murder in this country.","cn":"他是这个国家中最后一个被处以绞刑的谋杀犯。"}},{"en":"to spend time relaxing or enjoying yourself","cn":"休闲；玩耍","g":"[intransitive]","lab":"especially North American English, informal，，","sc":"relax","ex":{"en":"‘What are you all doing?’ ‘Just hanging.’","cn":"“你们都在做什么？”“只是挂着。”"}},{"en":"to attach something, especially a picture, to a hook (= a curved piece of metal) on a wall; to be attached in this way","cn":"（把…）挂在墙上","g":"[transitive, intransitive]","sc":"pictures","ex":{"en":"We hung her portrait above the fireplace.","cn":"我们把她的画像挂在壁炉上方。"}},{"en":"to decorate a place by placing paintings, etc. on a wall","cn":"挂图画等装饰（某处）","g":"[transitive, usually passive]","sc":"pictures","ex":{"en":"The rooms were hung with tapestries.","cn":"这些房间装饰着挂毯。"}},{"en":"to stick wallpaper to a wall","cn":"（在墙上）贴壁纸","g":"[transitive]","sc":"wallpaper"},{"en":"to attach a door or gate to a post so that it moves freely","cn":"把（门）装在门柱上；装（门）","g":"[transitive]","sc":"door/gate"},{"en":"to stay in the air","cn":"悬浮（在空中）","g":"[intransitive]","lab":"figurative","sc":"stay in the air","ex":{"en":"Smoke hung in the air above the city.","cn":"城市上空烟雾弥漫。"}},{"en":"the way in which a dress, piece of cloth, etc. falls or moves","cn":"（衣服、织物等的）悬挂方式，下垂","ex":{"en":"Small weights sewn into the hems will improve the hang of your curtains.","cn":"缝在下摆上的小重物可以改善窗帘的悬挂效果。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"悬挂;吊","en":"If something hangs in a high place or position, or if you hang it there, it is attached there so it does not touch the ground.","ex":{"en":"Notices painted on sheets hang at every entrance","cn":"写在纸上的告示悬挂在每个入口。"}},{"pos":"VERB 动词","cn":"（衣服或织物）下垂，披垂，飘垂","en":"If a piece of clothing or fabric hangs in a particular way or position, that is how it is worn or arranged.","ex":{"en":"...a ragged fur coat that hung down to her calves","cn":"她穿的一件长及小腿肚的破旧毛皮大衣"}},{"pos":"VERB 动词","cn":"（以某种方式）垂下，披下，悬挂","en":"If something hangs loose or hangs open, it is partly fixed in position, but is not firmly held, supported, or controlled, often in such a way that it moves freely.","ex":{"en":"...her long golden hair which hung loose about her shoulders","cn":"她那松散着披在肩上的长长的金发"}},{"pos":"VERB 动词","cn":"悬挂（画等）","en":"If something such as a wall is hung with pictures or other objects, they are attached to it.","ex":{"en":"The walls were hung with huge modern paintings.","cn":"墙上挂着巨幅的现代画。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（被）施以绞刑;（被）绞死","en":"If someone is hanged or if they hang, they are killed, usually as a punishment, by having a rope tied around their neck and the support taken away from under their feet.","ex":{"en":"The five were expected to be hanged at 7 am on Tuesday","cn":"那5个人将在周二早上7点被施以绞刑。"}},{"pos":"VERB 动词","cn":"悬浮","en":"If something such as someone's breath or smoke hangs in the air, it remains there without appearing to move or change position.","ex":{"en":"His breath was hanging in the air before him","cn":"他的哈气悬浮在自己面前。"}},{"pos":"VERB 动词","cn":"逼近;威胁;使忧心忡忡","en":"If a possibility hangs over you, it worries you and makes your life unpleasant or difficult because you think it might happen.","ex":{"en":"A constant threat of unemployment hangs over thousands of university researchers","cn":"持续存在的失业威胁困扰着数千名大学科研人员。"}},{"pos":"VERB 动词","cn":"对…毫不操心;对…满不在乎","en":"Hang is used in expressions such as hang it and hang the money to indicate that you are not concerned about something or the consequences of doing something.","ex":{"en":"Once the Americans decide to do a thing, they do it well, and hang the cost.","cn":"一旦美国人决定要做一件事，他们就会把它做好，且丝毫不计代价。"}},{"pos":"PHRASE 短语","cn":"掌握…的窍门;熟悉…的门道","en":"If you get the hang of something such as a skill or activity, you begin to understand or realize how to do it.","ex":{"en":"It's a bit tricky at first till you get the hang of it.","cn":"刚开始有点儿难，掌握窍门后就好了。"}},{"pos":"PHRASE 短语","cn":"坚持下去;别泄气","en":"If you tell someone to hang in there or to hang on in there, you are encouraging them to keep trying to do something and not to give up even though it might be difficult.","ex":{"en":"Hang in there and you never know what you might achieve.","cn":"坚持下去，你永远都无法预料会有什么样的收获。"}},{"pos":"PHRASE 短语","cn":"放松随便;不拘礼节","en":"If you let it all hang out, you relax completely and enjoy yourself without worrying about hiding your emotions or behaving politely."},{"pos":"","cn":"","en":"to hang by a thread→see: ; to hang on someone's every word→see: ;"},{"pos":"","cn":"","en":"相关词组：hang around hang back hang on hang out hang round hang together hang up"}]},"examples":[{"en":"I haven't heard if I've got the job yet — they've kept me hanging on for days.","cn":"我是否得到了那份工作的事还没消息，他们让我等了好几天了。"},{"en":"I was sure she knew the answer but for some reason she hung back.","cn":"我敢保证她知道答案，但不知为什么她不敢说出来。"}]},"hack":{"media":{"uk":"media/uk/hack__gb_1.mp3","us":"media/us/hack__us_1.mp3"},"oxford":{"phon":"hæk","pos":"verb","senses":[{"en":"to hit and cut somebody/something in a rough, heavy way","cn":"砍；劈","g":"[transitive, intransitive]","ex":{"en":"I hacked the dead branches off.","cn":"我把枯树枝砍掉了。"}},{"en":"to kick something roughly or without control","cn":"猛踢","g":"[transitive]","ex":{"en":"He hacked the ball away.","cn":"他把球一脚踢开。"}},{"en":"to secretly find a way of looking at and/or changing information on somebody else’s computer system without permission","cn":"非法侵入（他人的计算机系统）","g":"[intransitive, transitive]","lab":"computing","ex":{"en":"He hacked into the bank's computer.","cn":"他侵入了这家银行的计算机。"}},{"en":"to work together informally and often quickly with other people to create a program using different technologies","cn":"（多人合作用不同技术）快速编程","g":"[intransitive]","lab":"computing","ex":{"en":"We spent the morning hacking around with HTML and building web pages.","cn":"我们花了一上午的时间处理 HTML 问题和制作网页。"}},{"en":"to be able/not able to manage in a particular situation","cn":"能／不能应付（某情形）","g":"[transitive]","lab":"informal","ex":{"en":"Lots of people leave this job because they can't hack it.","cn":"很多人由于应付不了这项工作而放弃了。"}},{"en":"to ride a horse for pleasure","cn":"骑马消遣","g":"[intransitive]","lab":"especially British English"},{"en":"to drive a taxi","cn":"开出租车","g":"[intransitive]","lab":"North American English, informal，，"},{"en":"a writer, especially of newspaper articles, who does a lot of low quality work and does not get paid much","cn":"雇佣文人（尤指廉价受雇撰写报纸庸俗文章者）","lab":"disapproving","pos":"noun"},{"en":"a person who does the hard and often boring work for an organization, especially a politician","cn":"（受雇于组织，尤其是政客）从事艰苦乏味工作的人；杂务人员","lab":"disapproving","ex":{"en":"a party hack","cn":"政党杂务人员"},"pos":"noun"},{"en":"an ordinary horse or one that can be hired","cn":"马；可出租的马","pos":"noun"},{"en":"a taxi","cn":"出租车","lab":"North American English, informal，，","pos":"noun"},{"en":"an act of hitting something, especially with a cutting tool","cn":"砍；劈","ex":{"en":"I was sure he was going to take a hack at us.","cn":"我确信他会攻击我们。"},"pos":"noun"},{"en":"a piece of computer code that provides a quick solution to a problem by adding to the official function of a program","cn":"（解决计算机程序问题的）快速修正方法","pos":"noun"},{"en":"a strategy or technique that you use in order to manage an activity in a more efficient way","cn":"好方法；高招","lab":"informal","ex":{"en":"Have you got any clever parenting hacks?","cn":"你有什么育儿高招吗？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"劈;砍;乱劈;猛砍","en":"If you hack something or hack at it, you cut it with strong, rough strokes using a sharp tool such as an axe or knife.","ex":{"en":"An armed gang barged onto the train and began hacking and shooting anyone in sight","cn":"一伙持械歹徒闯上火车，开始见人就砍、举枪便射。"}},{"pos":"VERB 动词","cn":"（在丛林等中）开辟道路","en":"If you hack your way through an area such as a jungle or hack a path through it, you move forward, cutting back the trees or plants that are in your way.","ex":{"en":"We undertook the task of hacking our way through the jungle.","cn":"我们负责在丛林中开路。"}},{"pos":"VERB 动词","cn":"大幅缩减（大小、长度）;大幅降低（价格）","en":"If you hack at or hack something which is too large, too long, or too expensive, you reduce its size, length, or cost by cutting out or getting rid of large parts of it.","ex":{"en":"He hacked away at the story, eliminating one character entirely.","cn":"他大幅缩短了这篇故事，将其中一个人物彻底砍掉了。"}},{"pos":"N-COUNT 可数名词","cn":"（粗制滥造的）职业文人，雇佣文人","en":"If you refer to a professional writer, such as a journalist, as a hack, you disapprove of them because they write for money without worrying very much about the quality of their writing.","ex":{"en":"...tabloid hacks, always eager to find victims in order to sell newspapers.","cn":"为了使报纸好卖而总是急于寻找牺牲品的小报蹩脚记者们"}},{"pos":"N-COUNT 可数名词","cn":"二流政客;政治仆从","en":"If you refer to a politician as a hack, you disapprove of them because they are too loyal to their party and perhaps do not deserve the position they have.","ex":{"en":"Far too many party hacks from the old days still hold influential jobs.","cn":"太多以前的老党棍依然身居要职。"}},{"pos":"VERB 动词","cn":"（尤指为获取机密信息）侵入，非法进入（他人的计算机系统）","en":"If someone hacks into a computer system, they break into the system, especially in order to get secret information.","ex":{"en":"The saboteurs had demanded money in return for revealing how they hacked into the systems.","cn":"那些故意破坏者索要钱财，以作为透露自己是如何非法进入该电脑系统的交换条件。"}},{"pos":"VERB 动词","cn":"骑马","en":"If you hack or go hacking, you go out for a ride on horseback.","ex":{"en":"The children could be seen hacking across the hillside on their ponies.","cn":"可以看到孩子们正骑着小马穿过山坡。"}},{"pos":"N-COUNT 可数名词","cn":"骑马","en":"A hack is a ride on horseback."},{"pos":"N-COUNT 可数名词","cn":"供出租的骑用马","en":"A hack is a horse which people can hire from a stable to go out riding."},{"pos":"PHRASE 短语","cn":"做不来;无法应付","en":"If you say that someone can't hack it or couldn't hack it, you mean that they do not or did not have the qualities needed to do a task or cope with a situation.","ex":{"en":"You have to be strong and confident and never give the slightest impression that you can't hack it","cn":"你必须坚强自信，千万不要给人留下丝毫你应付不来的印象。"}},{"pos":"","cn":"","en":"相关词组：hack away hack off"}]},"examples":[{"en":"Lots of people leave this job because they can't hack it.","cn":"很多人由于应付不了这项工作而放弃了。"},{"en":"We had to hack our way through the jungle.","cn":"我们不得不在丛林中辟路穿行。"}]},"hairy":{"media":{"uk":"media/uk/hairy__gb_1.mp3","us":"media/us/hairy__us_1.mp3"},"oxford":{"phon":"ˈheəri","pos":"adjective","senses":[{"en":"covered with a lot of hair","cn":"多毛的","ex":{"en":"a hairy chest/monster","cn":"多毛的胸脯；全身长满毛的怪兽"}},{"en":"dangerous or frightening but often exciting","cn":"惊险的；可怕（但刺激）的","lab":"informal","ex":{"en":"Driving on icy roads can be pretty hairy.","cn":"在结冰的道路上开车很惊险。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多毛的;毛茸茸的","en":"Someone or something that is hairy is covered with hairs.","ex":{"en":"He was wearing shorts which showed his long, muscular, hairy legs","cn":"他穿着短裤，露出自己强壮多毛的长腿。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情况）惊险刺激的，令人担忧的，令人害怕的","en":"If you describe a situation as hairy, you mean that it is exciting, worrying, and rather frightening.","ex":{"en":"His driving was a bit hairy.","cn":"他的车技让人不放心。"}}]},"examples":[{"en":"Driving on icy roads can be pretty hairy.","cn":"在结冰的道路上开车很惊险。"},{"en":"a hairy chest/monster","cn":"多毛的胸脯；长满毛的怪兽"}]},"hammers":{"oxford":{"phon":"ˈhæmə(r)","pos":"noun","senses":[{"en":"a tool with a handle and a heavy metal head, used for breaking things or hitting nails","cn":"锤子；榔头:"},{"en":"a tool with a handle and a wooden head, used by a person in charge of an auction (= a sale at which things are sold to the person who offers the most money) in order to get people's attention when sth is just being sold （","cn":"拍卖用的）木槌"}]},"media":{"img":["media/pic/tools_diy_comp.jpg","media/thumb/hammer.jpg"],"uk":"media/uk/hammer__gb_1.mp3","us":"media/us/hammer__us_1.mp3"}},"harmony":{"oxford":{"phon":"ˈhɑːməni","pos":"noun","senses":[{"en":"a state of peaceful existence and agreement","cn":"融洽；和睦","g":"[uncountable]","lab":"approving","ex":{"en":"social/racial harmony","cn":"社会／种族融洽"}},{"en":"the way in which different notes that are played or sung together combine to make a pleasant sound","cn":"和声","g":"[uncountable, countable]","lab":"music","ex":{"en":"to sing in harmony","cn":"用和声唱"}},{"en":"an attractive combination of related things","cn":"和谐；协调","g":"[countable, uncountable]","lab":"approving","ex":{"en":"the harmony of colour in nature","cn":"自然界色彩的协调"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（人际关系的）融洽，和睦","en":"If people are living in harmony with each other, they are living together peacefully rather than fighting or arguing.","ex":{"en":"We must try to live in peace and harmony with ourselves and those around us","cn":"我们必须努力和我们自己及周围的人和睦相处。"}},{"pos":"N-VAR 可变名词","cn":"和声;和谐悦耳的音调","en":"Harmony is the pleasant combination of different notes of music played at the same time.","ex":{"en":"...complex vocal harmonies.","cn":"复杂的声乐和声"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（各组成部分的）协调，和谐，调和","en":"The harmony of something is the way in which its parts are combined into a pleasant arrangement.","ex":{"en":"...the ordered harmony of the universe","cn":"宇宙的有序和谐"}}]},"media":{"uk":"media/uk/harmony__gb_1.mp3","us":"media/us/harmony__us_1.mp3"},"examples":[{"en":"passionate lyrics and stunning vocal harmonies","cn":"充满激情的歌词和绝妙的和声演唱"},{"en":"the need to be in harmony with our environment","cn":"同我们的环境协调的必要"}]},"hasn't":{"media":{"uk":"media/uk/hasn_t_1_gb_1.mp3","us":"media/us/hasn_t_1_us_1.mp3"},"oxford":{"phon":"ˈhæznt","pos":"short form","senses":[{"en":"has not","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（has not 的常用口语形式）","en":"Hasn't is the usual spoken form of 'has not'."}]},"examples":[{"en":"Hasn’t she finished yet?","cn":""}]},"hangs":{"oxford":{"phon":"hæŋ","pos":"verb","senses":[{"en":"to attach sth, or to be attached, at the top so that the lower part is free or loose","cn":"悬挂；吊"},{"en":"when sth hangs in a particular way, it falls in that way","cn":"垂下；垂落"}]}},"hairs":{"oxford":{"phon":"heə(r)","pos":"noun","senses":[{"en":"the substance that looks like a mass of fine threads growing especially on the head; one of these threads growing on the body of people and some animals","cn":"毛发；（尤指）头发"},{"en":"( in adjectives","cn":"构成形容词 ) having the type of hair mentioned 有 … 毛发（或头发）的"}]}},"habits":{"oxford":{"phon":"ˈhæbɪt","pos":"noun","senses":[{"en":"a thing that you do often and almost without thinking, especially sth that is hard to stop doing","cn":"习惯"},{"en":"usual behaviour","cn":"惯常行为；习性"}]}},"handed":{"oxford":{"phon":"hænd","pos":"noun","senses":[{"en":"the part of the body at the end of the arm, including the fingers and thumb","cn":"手"},{"en":"( in adjectives","cn":"构成形容词 ) using the hand or number of hands mentioned 用 … 手的；用 … 只手的"}]}},"happens":{"oxford":{"phon":"ˈhæpən","pos":"verb","senses":[{"en":"to take place, especially without being planned （","cn":"尤指偶然）发生，出现"},{"en":"to take place as the result of sth （","cn":"作为结果）出现，发生"}]}},"harder":{"oxford":{"phon":"hɑːd","pos":"adjective","senses":[{"en":"solid, firm or stiff and difficult to bend or break","cn":"坚固的；坚硬的；结实的"},{"en":"difficult to do, understand or answer","cn":"难做的；难懂的；难以回答的"}]}},"hacked":{"oxford":{"phon":"hæk","pos":"verb","senses":[{"en":"to cut sb/sth with rough, heavy blows","cn":"砍；劈"},{"en":"to kick sth roughly or without control","cn":"猛踢"}]}},"hacking":{"oxford":{"phon":"ˈhækɪŋ","pos":"noun","senses":[{"en":"the activity of using computers to get access to data in somebody else's computer or phone system without permission","cn":"黑客行为；黑客攻击；非法侵入他人计算机（或手机）系统","ex":{"en":"The government tax website is vulnerable to hacking, putting taxpayers' information at risk.","cn":"政府税收网站容易遭到黑客入侵，使纳税人的信息受到威胁。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（咳嗽）干涩刺耳的","en":"A hacking cough is a dry, painful cough with a harsh, unpleasant sound.","ex":{"en":"The quiet was broken by Astley's hacking cough.","cn":"这片宁静被阿斯特利刺耳的干咳声打破了。"}}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41hacker.mp3","us":"media/ldoce/hwd/ame/7/hacker.mp3"},"examples":[{"en":"A hacker had managed to get into the system.","cn":""}]},"hats":{"oxford":{"phon":"hæt","pos":"noun","senses":[{"en":"a covering made to fit the head, often with a brim , (= a flat edge that sticks out) and worn out of doors （","cn":"常指带檐的）帽子"},{"en":"( informal ) a position or role, especially an official or professional role, when you have more than one such role （","cn":"双重的）职位，角色（尤指官职或职业角色）"}]},"media":{"img":["media/pic/hats_comp.jpg"]}},"haggling":{"oxford":{"phon":"ˈhæɡl","pos":"verb","senses":[{"en":"to argue with sb in order to reach an agreement, especially about the price of sth","cn":"争论；（尤指）讲价"}]},"media":{"uk":"media/ldoce/hwd/bre/f/haggle0205.mp3","us":"media/ldoce/hwd/ame/0/haggle.mp3"},"examples":[{"en":"tourists haggling over the price of souvenirs","cn":""},{"en":"Ted was haggling with the street vendors.","cn":""}]},"hangers":{"oxford":{"phon":"ˈhæŋə(r)","pos":"noun","senses":[{"en":"a curved piece of wood, plastic or wire, with a hook at the top, that you use to hang clothes up on","cn":"衣架"}]}},"happened":{"oxford":{"phon":"ˈhæpən","pos":"verb","senses":[{"en":"to take place, especially without being planned （","cn":"尤指偶然）发生，出现"},{"en":"to take place as the result of sth （","cn":"作为结果）出现，发生"}]}},"hands":{"oxford":{"phon":"hænd","pos":"noun","senses":[{"en":"the part of the body at the end of the arm, including the fingers and thumb","cn":"手"},{"en":"( in adjectives","cn":"构成形容词 ) using the hand or number of hands mentioned 用 … 手的；用 … 只手的"}]}},"haunts":{"oxford":{"phon":"hɔːnt","pos":"verb","senses":[{"en":"if the ghost of a dead person haunts a place, people say that they have seen it there （","cn":"鬼魂）出没"},{"en":"if sth unpleasant haunts you, it keeps coming to your mind so that you cannot forget it （","cn":"不快的事情）萦绕于脑际，难以忘却"}]}},"happier":{"oxford":{"phon":"ˈhæpi","pos":"adj.","senses":[{"en":"feeling or showing pleasure; pleased","cn":"感到（或显得）快乐的；高兴的"},{"en":"giving or causing pleasure","cn":"给予（或带来）快乐的；使人高兴的；幸福的"}]}},"hawkers":{"oxford":{"phon":"ˈhɔːkə(r)","pos":"noun","senses":[{"en":"a person who makes money by hawking goods","cn":"沿街叫卖者；小贩"}]}},"hackers":{"oxford":{"phon":"ˈhækə(r)","pos":"noun","senses":[{"en":"a person who secretly finds a way of looking at and/or changing information on sb else's computer system without permission","cn":"黑客，骇客（秘密窥视或改变他人计算机系统信息）"}]}},"handbrakes":{"oxford":{"phon":"ˈhændbreɪk","pos":"noun","senses":[{"en":"a brake in a vehicle that is operated by hand, used especially when the vehicle is not moving （","cn":"车辆的）手闸，手刹车"}]}},"hams":{"oxford":{"phon":"hæm","pos":"noun","senses":[{"en":"the top part of a pig's leg that has been cured (= preserved using salt or smoke) and is eaten as food; the meat from this","cn":"火腿；火腿肉"},{"en":"a person who sends and receives radio messages as a hobby rather than as a job","cn":"无线电通讯爱好者"}]}},"having":{"oxford":{"phon":"həv","pos":"verb","senses":[{"en":"( not used in the progressive tenses","cn":"不用于进行时 ) to own, hold or possess sth 有；持有；占有"},{"en":"( not used in the progressive tenses","cn":"不用于进行时 ) be made up of 由 … 组成"}]}},"hangars":{"oxford":{"phon":"ˈhæŋə(r)","pos":"noun","senses":[{"en":"a large building in which aircraft are kept","cn":"飞机库"}]}},"halls":{"oxford":{"phon":"hɔːl","pos":"noun","senses":[{"en":"a space or passage inside the entrance or front door of a building","cn":"门厅；正门过道"},{"en":"a passage in a building with rooms down either side （","cn":"大楼内的）走廊"}]}},"hated":{"oxford":{"phon":"heɪt","pos":"verb","senses":[{"en":"to dislike sth very much","cn":"厌恶，讨厌，憎恶（某事物）"},{"en":"to dislike sb very much","cn":"憎恨，憎恶，仇恨（某人）"}]},"media":{"uk":"media/ldoce/hwd/bre/d/hate_v0205.mp3","us":"media/ldoce/hwd/ame/c/hate1.mp3"},"examples":[{"en":"It’s the kind of movie you either love or hate.","cn":""},{"en":"He hates his job.","cn":""}]},"halt":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）停止行进;（使）停住","en":"When a person or a vehicle halts or when something halts them, they stop moving in the direction they were going and stand still.","ex":{"en":"They halted at a short distance from the house","cn":"他们在离房子不远处停了下来。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（生长、发展、活动等）停止（或中止）","en":"When something such as growth, development, or activity halts or when you halt it, it stops completely.","ex":{"en":"Striking workers halted production at the auto plant yesterday","cn":"罢工工人于昨日停止了汽车厂的生产。"}},{"pos":"VERB 动词","cn":"（军队口令）立定！站住！停止前进！","en":"'Halt!' is a military order to stop walking or marching and stand still.","ex":{"en":"The colonel ordered 'Halt!'","cn":"上校命令道：“立定！”"}},{"pos":"N-COUNT 可数名词","cn":"（只有小型站台、无建筑物的)小火车站","en":"A halt is a very small station on a country railway line, which often consists only of a short platform and no building."},{"pos":"PHRASE 短语","cn":"下令停止;叫停","en":"If someone calls a halt to something such as an activity, they decide not to continue with it or to end it immediately.","ex":{"en":"The Russian government had called a halt to the construction of a new project in the Rostov region.","cn":"俄罗斯政府已叫停了罗斯托夫地区的一个新工程。"}},{"pos":"PHRASE 短语","cn":"停止移动;停下","en":"If someone or something comes to a halt, they stop moving.","ex":{"en":"Sofia and Alex came to a halt and both tried to regain their breath","cn":"索菲娅和亚历克斯停了下来，两人都想喘口气。"}},{"pos":"PHRASE 短语","cn":"（使）（生长、发展、活动等）完全停止","en":"If something such as growth, development, or activity comes or grinds to a halt or is brought to a halt, it stops completely.","ex":{"en":"Her political career came to a halt in December 1988","cn":"她的政治生涯于1988年12月画上了句号。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to stop an activity, especially one that you consider to be harmful or unacceptable","cn":""},{"en":"to completely stop an illegal or harmful activity","cn":""},{"en":"to take severe action to stop an illegal activity","cn":""}]},"vocab":{"pos":"1 v n 2 adj","senses":[{"en":"Whether it's used as a noun or a verb, the word halt means stop . You can remember this by remembering that when you step on the brake to halt your car (verb), it comes to a halt (noun)."}]},"collocations":{"phrases":["ADJ. abrupt, sudden The bus came to an abrupt halt outside the school. | grinding, shuddering The strike brought the capital city to a grind","VERB + HALT come to, draw to, grind to, jolt to, lurch to, scream to, screech to, shudder to, skid to, slide to, slither to The economy seem","PREP. ~ in a halt in nuclear testing | ~ to The protesters are calling for a halt to the export of live animals."]},"media":{"uk":"media/ldoce/hwd/bre/2/halt_n0205.mp3","us":"media/ldoce/hwd/ame/b/halt1.mp3"},"examples":[{"en":"The police were halting traffic on the parade route.","cn":"警察正阻止游行路线上的车辆前行。"},{"en":"Work came to a halt when the machine broke down.","cn":"机器一坏，工作便停了下来。"}],"oxford":{"phon":"hɔːlt","pos":"verb","senses":[{"en":"to stop; to make somebody/something stop","cn":"（使）停止，停下","ex":{"en":"She walked towards him and then halted.","cn":"她向他走去，然后停下。"}},{"en":"an act of stopping the movement or progress of somebody/something","cn":"停止；阻止；暂停","g":"[singular]","ex":{"en":"Work came to a halt when the machine broke down.","cn":"机器一坏，工作便停了下来。"},"pos":"noun"},{"en":"a small train station in the country that has a platform but no buildings","cn":"小火车站（只有站台）","g":"[countable]","lab":"British English","pos":"noun"}]}},"harp":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"竖琴","en":"A harp is a large musical instrument consisting of a row of strings stretched from the top to the bottom of a frame. You play the harp by plucking the strings with your fingers."},{"pos":"","cn":"","en":"相关词组：harp on"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large musical instrument with strings that are stretched across a vertical frame with three corners, and that you play with your fingers","cn":"竖琴"},{"en":"to keep talking or complaining about something, in a way that is annoying or boring","cn":""},{"en":"to keep mentioning something in a way that other people find annoying","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"A harp is a large, stringed musical instrument with a beautiful sound. If you want to play an instrument that's portable, you should choose a ukulele instead of a harp ."}]},"collocations":{"phrases":["ADV. always, constantly He is always harping on about the war. | still","PREP. about","PHRASES keep harping on Don't keep harping on about my age!"]},"media":{"img":["media/ldoce/img/harp.jpg","media/thumb/harp.jpg"],"uk":"media/ldoce/hwd/bre/3/harp_v0205.mp3","us":"media/ldoce/hwd/ame/c/harp1.mp3"},"examples":[{"en":"My grandfather harps on about the war all the time.","cn":"我的祖父总是喋喋不休地说那场战争的事。"}],"oxford":{"phon":"hɑːp","pos":"noun","senses":[{"en":"a large musical instrument with strings stretched from top to bottom on a frame, played with the fingers","cn":"竖琴","ex":{"en":"By means of pedals, a harp can be set in any desired key.","cn":"利用踏板可以给竖琴调出任何一种调子。"}}]}},"harassment":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"骚扰;烦扰","en":"Harassment is behaviour which is intended to trouble or annoy someone, for example repeated attacks on them or attempts to cause them problems.","ex":{"en":"Another survey found that 51 per cent of women had experienced some form of sexual harassment in their working lives.","cn":"另一个调查发现，51%的女性在工作中曾遭遇过某种形式的性骚扰。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone behaves in an unpleasant or threatening way towards you","cn":"骚扰"}]},"vocab":{"pos":"n","senses":[{"en":"If someone is abusing, insulting, or otherwise harming you on a regular basis, it's called harassment . Cruel and usually really annoying, harassment is also illegal in some cases."}]},"collocations":{"phrases":["ADJ. racial, sexual | police | constant, continual","VERB + HARASSMENT be subject to, be subjected to, suffer She had been subjected to continual sexual harassment.","PREP. ~ by They are complaining about harassment by the police","PHRASES a victim of harassment • Note at CRIME (for more verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeharassment.mp3","us":"media/ldoce/hwd/ame/2/laadharassment.mp3"},"examples":[{"en":"racial/sexual harassment","cn":"种族侵扰；性骚扰"},{"en":"African-Americans have been complaining about police harassment for years.","cn":"非洲裔美国人多年来一直抱怨受到警察的骚扰。"}],"oxford":{"phon":"ˈhærəsmənt","pos":"noun","senses":[{"en":"the act of annoying or worrying somebody by putting pressure on them or saying or doing unpleasant things to them","cn":"侵扰；骚扰","ex":{"en":"sexual/racial harassment","cn":"性/种族骚扰"}},{"en":"the act of making repeated attacks on an enemy","cn":"（对敌人的）不断攻击","ex":{"en":"guerrilla harassment of the enemy","cn":"敌人的游击袭扰"}}]}},"ham":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"火腿","en":"Ham is meat from the top of the back leg of a pig, specially treated so that it can be kept for a long period of time.","ex":{"en":"...a huge baked ham.","cn":"巨大的烤火腿"}},{"pos":"N-COUNT 可数名词","cn":"无线电爱好者；“火腿”","en":"A ham is a person whose hobby consists of using special radio equipment to talk to other people with the same hobby, often people who are in other countries.","ex":{"en":"I became a ham radio operator at the age of eleven.","cn":"我在11岁时成了一名业余无线电操作员。"}},{"pos":"N-COUNT 可数名词","cn":"蹩脚演员;表演过火的演员","en":"A ham actor is someone who acts badly, exaggerating every emotion and gesture."},{"pos":"PHRASE 短语","cn":"（常指演员故意地）表演过火，夸张做作","en":"If actors or actresses ham it up, they exaggerate every emotion and gesture when they are acting, often deliberately because they think that the audience will be more amused.","ex":{"en":"Thrusting themselves into the spirit of the farce, they ham it up like mad.","cn":"他们全力投入到这部闹剧中去，极尽搞怪之能事。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the upper part of a pig’s leg, or the meat from this that has been preserved with salt or smoke","cn":"火腿﹐火腿肉"},{"en":"someone who receives and sends radio messages for fun rather than as their job","cn":"业余无线电爱好者"},{"en":"an actor who performs with too much false emotion","cn":"演技做作的演员﹐表演过火的演员"}]},"collocations":{"phrases":["ADJ. lean | baked, boiled, cooked, cured, honey-roast, Parma, smoked | cold cold ham and salad | sliced","QUANT. bit, piece, slice | joint, leg","VERB + HAM eat, have | boil, cook, roast | carve, slice","HAM + NOUN roll, salad, sandwich","PHRASES ham on the bone We had boiled ham on the bone for dinner. •"]},"media":{"uk":"media/ldoce/hwd/bre/1/ham_n0205.mp3","us":"media/ldoce/hwd/ame/9/ham1.mp3"},"examples":[{"en":"The hams were cooked whole.","cn":"这些火腿是整条烹制的。"},{"en":"a radio ham","cn":"无线电通讯爱好者"}],"oxford":{"phon":"hæm","pos":"noun","senses":[{"en":"meat from the top part of a pig’s leg that has been cured (= preserved using salt or smoke)","cn":"火腿；火腿肉","g":"[uncountable, countable]","ex":{"en":"a slice of ham","cn":"一片火腿"}},{"en":"a person who sends and receives radio messages as a hobby rather than as a job","cn":"无线电通信爱好者","g":"[countable]","ex":{"en":"a radio ham","cn":"无线电通信爱好者"}},{"en":"an actor who performs badly, especially by exaggerating emotions","cn":"拙劣演员（尤指表演过火者）","g":"[countable]","lab":"informal","ex":{"en":"a ham actor","cn":"表演过火的演员"}},{"en":"the back part of a person’s leg above the knee","cn":"（人的）大腿后部","g":"[countable, usually plural]","lab":"informal"}]}},"haunt":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（不愉快的事）萦绕在心头，缠绕","en":"If something unpleasant haunts you, you keep thinking or worrying about it over a long period of time.","ex":{"en":"The decision to leave her children now haunts her","cn":"抛下孩子们的决定现在总让她不安。"}},{"pos":"VERB 动词","cn":"长期困扰","en":"Something that haunts a person or organization regularly causes them problems over a long period of time.","ex":{"en":"The stigma of being a bankrupt is likely to haunt him for the rest of his life.","cn":"破产的耻辱可能会让他余生不得安宁。"}},{"pos":"N-COUNT 可数名词","cn":"常去的地方","en":"A place that is the haunt of a particular person is one which they often visit because they enjoy going there.","ex":{"en":"The Channel Islands are a favourite summer haunt for UK and French yachtsmen alike.","cn":"海峡群岛是英国和法国的帆船运动爱好者夏日最爱去的地方。"}},{"pos":"VERB 动词","cn":"（鬼魂等）常出没于","en":"A ghost or spirit that haunts a place or a person regularly appears in the place, or is seen by the person and frightens them.","ex":{"en":"His ghost is said to haunt some of the rooms, banging a toy drum.","cn":"据说他的鬼魂经常敲着玩具鼓出没在其中的一些房间里。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"a place that is haunted has ghosts in it","cn":""},{"en":"if a ghost haunts a place, it appears there often","cn":""},{"en":"a place that is spooky feels strange and makes you feel that there are ghosts there","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"The verb to haunt means to appear as a ghost or some kind of supernatural phenomenon. Ebenezer Scrooge was haunted by the Ghosts of Christmases Past, Present and Future."}]},"collocations":{"phrases":["ADV. reputedly, supposedly a Norman castle which is reputedly haunted","VERB + HAUNT come back to, return to He said he would come back to haunt her. (figurative) That decision came back to haunt him in later lif","ADV. still the great fear that still haunts her","VERB + HAUNT continue to These visions continued to haunt her for many years."]},"media":{"uk":"media/ldoce/hwd/bre/d/haunt_n0205.mp3","us":"media/ldoce/hwd/ame/a/haunt1.mp3"},"examples":[{"en":"A headless rider haunts the country lanes.","cn":"一个无头骑士常出没于乡间的小路上。"},{"en":"The memory of that day still haunts me.","cn":"我的脑海中常常回想起那天的情景。"}],"oxford":{"phon":"hɔːnt","pos":"verb","senses":[{"en":"if the ghost of a dead person haunts a place, people say that they have seen it there","cn":"（鬼魂）出没","ex":{"en":"A headless rider haunts the country lanes.","cn":"一个无头骑士常出没于乡间的小路上。"}},{"en":"if something unpleasant haunts you, it keeps coming to your mind so that you cannot forget it","cn":"（不快的事情）萦绕于脑际，使难以忘却","ex":{"en":"The memory of that day still haunts me.","cn":"我的脑海中还常常回想起那天的情景。"}},{"en":"to continue to cause problems for somebody for a long time","cn":"长期不断地缠扰（某人）","ex":{"en":"That decision came back to haunt him.","cn":"那个决定对他造成无法摆脱的困扰。"}},{"en":"a place that somebody visits often or where they spend a lot of time","cn":"常去的场所；消磨时光的去处","ex":{"en":"The pub is a favourite haunt of artists.","cn":"这家酒吧是艺术家最爱光顾的地方。"},"pos":"noun"}]}},"handy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有用的;方便的","en":"Something that is handy is useful.","ex":{"en":"The book gives handy hints on looking after indoor plants","cn":"这本书提供了一些关于如何照料室内花草的有用信息。"}},{"pos":"PHRASE 短语","cn":"派上用场","en":"If something comes in handy, it is useful in a particular situation.","ex":{"en":"That key will come in handy if you lock yourself out","cn":"要是你把自己锁在了屋外，那把钥匙就派上用场了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"手边的;附近的","en":"A thing or place that is handy is nearby and therefore easy to get or reach.","ex":{"en":"It would be good to have a pencil and paper handy","cn":"最好在手边准备好纸和笔。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"手巧的;有手艺的","en":"Someone who is handy with a particular tool is skilful at using it.","ex":{"en":"If you're handy with a needle you could brighten up your sweater with daisies.","cn":"如果你针线活做得好，可以在自己的毛衣上绣几朵雏菊做点缀。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is useful makes it easier for you to do something","cn":""},{"en":"useful – used especially about something that is convenient and easy to use","cn":""},{"en":"useful because it helps you to do something","cn":""}]},"collocations":{"phrases":["VERBS be | come in I advise you to buy one?it may come in handy one day.","ADV. very | quite","PREP. for The arrangement was handy for both of us. 2 nearby","VERBS be | keep sth Always keep a cloth handy to wipe up any mess.","ADV. very | quite","PREP. for The house was near Drury Lane, very handy for the theatre. 3 good at using sth","VERBS be","ADV. very | fairly, pretty, quite"]},"media":{"uk":"media/ldoce/hwd/bre/a/handy0205.mp3","us":"media/ldoce/hwd/ame/6/handy.mp3"},"examples":[{"en":"The extra money came in very handy.","cn":"这笔额外的钱正好派上了用场。"},{"en":"to be handy around the house","cn":"对家里敲打修理的杂事很在行"}],"oxford":{"phon":"ˈhændi","pos":"adjective","senses":[{"en":"easy to use or to do","cn":"易使用的；容易做的；便利的","ex":{"en":"a handy little tool","cn":"好用的小工具"}},{"en":"located near to somebody/something; located or stored in a convenient place","cn":"近便；便利","g":"[not before noun]","lab":"British English","ex":{"en":"Always keep a first-aid kit handy.","cn":"手边要常备急救箱。"}},{"en":"able to use your hands or tools to make or repair things well","cn":"手巧；有手艺","g":"[not before noun]","ex":{"en":"to be handy around the house","cn":"对家里制作、修理等杂事很在行"}}]}},"hardback":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"硬皮书;精装本 (Compare 比较 paperback.）","en":"A hardback is a book which has a stiff hard cover.","ex":{"en":"His autobiography has sold more than 36,000 copies in hardback.","cn":"他的自传精装本已经卖出了36,000多册。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a book about imaginary people and events","cn":""},{"en":"books that describe imaginary people and events","cn":""},{"en":"novels and plays that are considered to be important works of art","cn":""}]},"collocations":{"phrases":["VERB + HARDBACK publish | come out in His second book came out in hardback last month.","HARDBACK + NOUN book, edition","PREP. in ~ It's only available in hardback."]},"media":{"uk":"media/ldoce/hwd/bre/8/hardback0205.mp3","us":"media/ldoce/hwd/ame/9/hardback.mp3"},"examples":[{"en":"It was published in hardback last year.","cn":"这书去年以精装本出版。"},{"en":"What's the price of the hardback?","cn":"精装本多少钱？"}],"oxford":{"phon":"ˈhɑːdbæk","pos":"noun","senses":[{"en":"a book that has a stiff cover","cn":"精装书","ex":{"en":"What's the price of the hardback?","cn":"精装本多少钱？"}}]}},"hazard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"危险;危害","en":"A hazard is something which could be dangerous to you, your health or safety, or your plans or reputation.","ex":{"en":"A new report suggests that chewing-gum may be a health hazard","cn":"一份新报告指出，口香糖可能对健康有害。"}},{"pos":"VERB 动词","cn":"使冒风险;使处于危险中","en":"If you hazard someone or something, you put them into a situation which might be dangerous for them.","ex":{"en":"He could not believe that, had the Englishman known how much he was at risk, he would have hazarded his grandson.","cn":"他无法相信，如果当时那个英国人知道他冒的风险有多大，他还会让自己的孙子去冒这个险。"}},{"pos":"VERB 动词","cn":"斗胆提出;作无把握猜测","en":"If you hazard or if you hazard a guess, you make a suggestion about something which is only a guess and which you know might be wrong.","ex":{"en":"I would hazard a guess that they'll do fairly well in the next election","cn":"我斗胆猜测，他们在下一轮竞选中会有不错的表现。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the chance that something bad may happen","cn":""},{"en":"the possibility that something very bad will happen","cn":""},{"en":"something that may be dangerous or cause accidents or problems","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If something is a hazard , it is a potential source of danger. Balloons are fun, but they're a hazard for little kids who might put them in their mouths."}]},"collocations":{"phrases":["ADJ. big, great, major, real, serious | constant | possible, potential | hidden, unexpected, unseen | environmental, industrial, natural, oc","VERB + HAZARD cause, create, pose Production of these chemicals poses serious environmental hazards. | be exposed to, encounter, face, meet ","PREP. ~ for Holes in the pavement are a hazard for blind people. | ~ to The burning of industrial waste is a major hazard to human health.","PHRASES exposure to a hazard Try and reduce your exposure to hazards such as poor quality air."]},"media":{"uk":"media/ldoce/hwd/bre/1/hazard_v0205.mp3","us":"media/ldoce/hwd/ame/4/hazard1.mp3"},"examples":[{"en":"Growing levels of pollution represent a serious health hazard to the local population.","cn":"日益严重的污染对当地人民的健康构成了重大威胁。"},{"en":"Careless drivers hazard other people's lives as well as their own.","cn":"粗心大意的驾驶者拿他人和自己的生命冒险。"}],"oxford":{"phon":"ˈhæzəd","pos":"noun","senses":[{"en":"something that can be dangerous or cause damage","cn":"危险；危害","ex":{"en":"a fire/safety hazard","cn":"火灾／安全隐患"}},{"en":"to make a suggestion or guess that you know may be wrong","cn":"试着提出；大胆猜测","ex":{"en":"Would you like to hazard a guess?","cn":"你想猜猜看吗？"},"pos":"verb"},{"en":"to risk something or put it in danger","cn":"冒…的风险；使处于危险中","lab":"formal","ex":{"en":"Careless drivers hazard other people's lives as well as their own.","cn":"粗心大意的驾驶者拿他人和自己的生命冒险。"},"pos":"verb"}]}},"hazy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"雾气腾腾的;雾蒙蒙的","en":"Hazy weather conditions are those in which things are difficult to see, because of light mist, hot air, or dust.","ex":{"en":"The air was thin and crisp, filled with hazy sunshine and frost","cn":"空气稀薄清新，其间日光蒙眬，寒气逼人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对想法或细节）不太了解的;不确定的;不清楚的","en":"If you are hazy about ideas or details, or if they are hazy, you are uncertain or confused about them.","ex":{"en":"I'm a bit hazy about that","cn":"那件事我不太清楚。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"模糊的;看不清楚的","en":"If things seem hazy, you cannot see things clearly, for example because you are feeling ill.","ex":{"en":"She sipped the wine. Everything was hazy now, except for Nick's face","cn":"她小口地抿着酒。现在一切都变得模糊起来，除了尼克的脸。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"with a lot of clouds","cn":""},{"en":"grey in colour, because there are dark clouds – used especially in written descriptions","cn":""},{"en":"dark and completely covered with clouds","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If it's hazy , it's definitely not clear — there's fog, mist, smoke or something like that blurring the view."}]},"collocations":{"phrases":["VERBS be, look The distant mountains looked hazy and mysterious. | become | remain","ADV. very | a little, quite, rather, slightly Generally, it will be rather hazy today, with some hill fog.","PREP. with The summers were hazy with pollution. 2 confused","VERBS be | become | remain","ADV. extremely, very I have only a very hazy idea about how the economy works. | a bit, fairly, a little, rather, somewhat My memory of that","PREP. about I'm a bit hazy about my family history."]},"media":{"uk":"media/ldoce/hwd/bre/d/hazy0205.mp3","us":"media/ldoce/hwd/ame/1/hazy.mp3"},"examples":[{"en":"I'm a little hazy about what to do next.","cn":"我还有点拿不准下一步要做什么。"},{"en":"‘Why now?’ she wondered hazily. “","cn":"为什么是现在？”她困惑地思忖。"}],"oxford":{"phon":"ˈheɪzi","pos":"adjective","senses":[{"en":"not clear because of haze","cn":"朦胧的；薄雾蒙蒙的","ex":{"en":"a hazy afternoon/sky","cn":"雾蒙蒙的下午／天空"}},{"en":"not clear because of a lack of memory, understanding or detail","cn":"记不清的；模糊的","ex":{"en":"a hazy memory/idea","cn":"模糊不清的记忆／概念"}},{"en":"uncertain or confused about something","cn":"主意不定的；困惑的","ex":{"en":"I'm a little hazy about what to do next.","cn":"我还有点拿不准下一步要做什么。"}}]}},"handbag":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（女用）手提包，手袋","en":"A handbag is a small bag which a woman uses to carry things such as her money and keys in when she goes out."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small bag in which a woman carries money and personal things 〔","cn":"女用〕手提包﹔手袋"},{"en":"used humorously to describe a situation in which two people are fighting, but in a way that is so weak or lacking in force that the fight is funny to watch 〔","cn":"软弱无力的〕打闹〔幽默用法〕"}]},"collocations":{"phrases":["ADJ. big, capacious, large","VERB + HANDBAG clutch, hold | carry | swing | delve into, fish about/around in, fumble in, reach into, rummage (around) in, search (in/throu","PREP. from a/the ~, out of a/the ~ She took a pen out of her large leather handbag. | in a/the ~, into a/the ~ She put her purse into her ha","PHRASES the contents of a handbag"]},"media":{"img":["media/ldoce/img/handbag.jpg","media/thumb/handbag.jpg"],"uk":"media/ldoce/hwd/bre/1/handbag0205.mp3","us":"media/ldoce/hwd/ame/1/handbag1.mp3"},"examples":[{"en":"Dennis looked like he threw a punch, but it was just handbags.","cn":"丹尼斯看似挥了一拳﹐其实只是装样子。"}],"oxford":{"phon":"ˈhændbæɡ","pos":"noun","senses":[{"en":"a small bag for money, keys, etc., especially one carried by a woman","cn":"手提包；（尤指）坤包","ex":{"en":"She was rummaging in her handbag for her keys.","cn":"她正在手提包里翻找钥匙。"}}]}},"hawk":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鹰;隼","en":"A hawk is a large bird with a short, hooked beak, sharp claws, and very good eyesight. Hawks catch and eat small birds and animals."},{"pos":"N-COUNT 可数名词","cn":"（政治上的）鹰派人物，主战分子","en":"In politics, if you refer to someone as a hawk, you mean that they believe in using force and violence to achieve something, rather than using more peaceful or diplomatic methods.","ex":{"en":"Both hawks and doves have expanded their conditions for ending the war.","cn":"鹰派和鸽派都充分阐明了各自的停战条件。"}},{"pos":"VERB 动词","cn":"叫卖;兜售","en":"If someone hawks goods, they sell them by walking through the streets or knocking at people's houses, and asking people to buy them.","ex":{"en":"...vendors hawking trinkets.","cn":"沿街兜售小饰品的小贩"}},{"pos":"VERB 动词","cn":"（竭力）推销，兜售","en":"You can say that someone is hawking something if you do not like the forceful way in which they are asking people to buy it.","ex":{"en":"Developers will be hawking cut-price flats and houses.","cn":"开发商会竭力推销减价的公寓和房子。"}},{"pos":"VERB 动词","cn":"用力咳痰","en":"If someone hawks, they noisily clear mucus from their throat and spit it out.","ex":{"en":"He hawked and spat.","cn":"他用力咳了咳，吐了口痰。"}},{"pos":"PHRASE 短语","cn":"像鹰一样注视;警惕地监视","en":"If you watch someone like a hawk, you observe them very carefully, usually to make sure that they do not make a mistake or do something you do not want them to do."},{"pos":"","cn":"","en":"相关词组：hawk around"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, especially a politician or a military leader, who is too keen to start wars or to settle arguments by starting a war","cn":""},{"en":"someone, especially a politician or a military leader, who is too keen to increase the size and power of their country's armed forces so that it can attack other countries","cn":""},{"en":"a person, especially a politician, who supports the use of military force and strong action in order to settle arguments with other countries","cn":""}]},"collocations":{"phrases":["HAWK + VERB hover | swoop (down) The hawk swooped low over the field.","PHRASES watch (sb) like a hawk He waited, watching her like a hawk."]},"media":{"img":["media/ldoce/img/hawk.jpg"],"uk":"media/ldoce/hwd/bre/6/hawk_n0205.mp3","us":"media/ldoce/hwd/ame/7/hawk1.mp3"},"examples":[{"en":"He waited, watching her like a hawk (= watching her very closely).","cn":"他等待着，用鹰一样锐利的目光紧盯着她。"}],"oxford":{"phon":"hɔːk","pos":"noun","senses":[{"en":"a strong fast bird of prey (= a bird that kills other creatures for food). There are several different types of hawks.","cn":"鹰；隼","ex":{"en":"He waited, watching her like a hawk (= watching her very closely).","cn":"他等待着，用鹰一样锐利的目光紧盯着她。"}},{"en":"a person, especially a politician, who supports the use of military force to solve problems","cn":"鹰派分子；主战分子"},{"en":"to try to sell things by going from place to place asking people to buy them","cn":"沿街叫卖","g":"[transitive]","ex":{"en":"He made a living hawking cleaning products from door to door.","cn":"他以挨家挨户兜售清洁产品为生。"},"pos":"verb"},{"en":"to get phlegm (= a thick substance that forms in your nose and throat when you are ill) in your mouth when you cough","cn":"咳痰","g":"[intransitive, transitive]","pos":"verb"}]}},"handout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"救济金;救济物;施舍物","en":"A handout is a gift of money, clothing, or food, which is given free to poor people.","ex":{"en":"Soldiers oversee the food handouts","cn":"士兵们看管着救济食品。"}},{"pos":"N-COUNT 可数名词","cn":"白给的钱;不劳而获的钱","en":"If you call money that is given to someone a handout, you disapprove of it because you believe that the person who receives it has done nothing to earn or deserve it.","ex":{"en":"...the tendency of politicians to use money on vote-buying handouts rather than on investment in the future","cn":"政客把钱用于可以拉选票的福利上而不是用作未来投资的趋势"}},{"pos":"N-COUNT 可数名词","cn":"传单;宣传材料","en":"A handout is a document which contains news or information about something and which is given, for example, to journalists or members of the public.","ex":{"en":"Official handouts describe the Emperor as 'particularly noted as a scholar'.","cn":"官方印发的材料将皇帝描述为“尤以学识渊博而著称”。"}},{"pos":"N-COUNT 可数名词","cn":"（发给听众的）讲义，提纲","en":"A handout is a paper containing a summary of information or topics which will be dealt with in a lecture or talk."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something, especially money that is given to help people","cn":""},{"en":"money or help given to help the poor, the sick etc","cn":""},{"en":"money, food, medicine etc that is given by a government or organization to the people of another country or to people who are in a very difficult situation","cn":""}]},"collocations":{"phrases":["ADJ. free | government, state | cash","VERB + HANDOUT give (sb) | get, receive All those eligible will receive a cash handout.","PREP. ~ from a handout from the government | ~ to state handouts to the poor 2 sheet/leaflet","VERB + HANDOUT distribute, give sb, give out","PREP. in a/the ~ More information can be found in the handout. | ~ on We were given a handout on job hunting."]},"media":{"uk":"media/ldoce/hwd/bre/f/handout0205.mp3","us":"media/ldoce/hwd/ame/9/handout.mp3"},"examples":[{"en":"people who have to live on handouts from the state","cn":"必须依赖国家发放的救济金生活的人们"},{"en":"Please read the handout.","cn":"请看一下发下来的材料。"}],"oxford":{"phon":"ˈhændaʊt","pos":"noun","senses":[{"en":"food, money or clothes that are given to a person who is poor","cn":"捐赠品；救济品","lab":"sometimes disapproving","ex":{"en":"to be dependent on handouts","cn":"依赖施舍"}},{"en":"money that is given to a person or an organization by the government, etc., for example to encourage commercial activity","cn":"政府拨款（为促进商业活动）","lab":"often disapproving","ex":{"en":"a handout from the government","cn":"来自政府的救济"}},{"en":"a free document that gives information about an event or a matter of public interest, or that states the views of a political party, etc.","cn":"传单","ex":{"en":"We were given a handout on job hunting.","cn":"我们获发一份有关求职的印刷品。"}},{"en":"a document that is given to students in class or people attending a talk, etc. and that contains a summary of the lesson/talk, a set of exercises, etc.","cn":"（发给学生或参与讨论者等的）讲义，文字材料"}]}},"harass":{"collins":{"senses":[{"pos":"VERB 动词","cn":"骚扰;烦扰","en":"If someone harasses you, they trouble or annoy you, for example by attacking you repeatedly or by causing you as many problems as they can.","ex":{"en":"A woman reporter complained one of them sexually harassed her in the locker room","cn":"一名女记者投诉说，他们中有一人在更衣室里对她进行性骚扰。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone’s life unpleasant, for example by frequently saying offensive things to them or threatening them","cn":"骚扰"},{"en":"to keep attacking an enemy again and again","cn":"反复攻击﹐屡次侵扰〔敌人〕"}]},"vocab":{"pos":"v","senses":[{"en":"When you harass someone, you bother them to the point of exhaustion. It’s not that each attack is so severe, it’s the constant small attacks that wear someone out. If you harass your boss for a raise, you might end up getting fired instead!"}]},"collocations":{"phrases":["ADV. racially, sexually She had been sexually harassed at work."]},"media":{"uk":"media/ldoce/hwd/bre/1/harass_las3_br.mp3","us":"media/ldoce/hwd/ame/5/harass.mp3"},"examples":[{"en":"She claims she has been sexually harassed at work.","cn":"她声称在工作中受到性骚扰。"},{"en":"He has complained of being harassed by the police.","cn":"他投诉受到警方侵扰。"}],"oxford":{"phon":"ˈhærəs","pos":"verb","senses":[{"en":"to annoy or worry somebody by putting pressure on them or saying or doing unpleasant things to them","cn":"侵扰；骚扰","g":"[often passive]","ex":{"en":"He has complained of being harassed by the police.","cn":"他投诉受到警方侵扰。"}},{"en":"to make repeated attacks on an enemy","cn":"反复进攻；不断攻击（敌人）","ex":{"en":"Our convoys are being continually harassed by enemy submarines.","cn":"我们的船队不断受到敌方潜艇的攻击。"}}]}},"harvard":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a famous and respected university in Cambridge, Massachusetts, established in 1636, which is the oldest university in the US","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/p028-000005872.mp3","us":"media/ldoce/hwd/ame/a/p028-000005872.mp3"}},"handicapped":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"残疾的，有生理缺陷的，弱智的（可能具冒犯意味）","en":"Someone who is handicapped has a physical or mental disability that prevents them living a totally normal life. Many people who have a disability find this word offensive.","ex":{"en":"I'm going to work two days a week teaching handicapped kids to fish","cn":"我将每周工作两天，教残疾儿童钓鱼。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not able to use a part of your body properly or not able to learn normally, because of a permanent problem","cn":""},{"en":"if someone has special needs, they have physical or mental disabilities","cn":""},{"en":"if someone has learning difficulties, they have difficulty learning basic skills or information","cn":""}]},"collocations":{"phrases":["VERBS be, be born Steven was born severely handicapped. | leave sb An accident at birth left him badly handicapped.","ADV. badly, profoundly, seriously, severely | mildly, slightly | permanently | mentally, physically, visually special equipment for visually"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdehandicapped.mp3","us":"media/ldoce/hwd/ame/a/handicapped.mp3"},"examples":[{"en":"The accident left him physically handicapped.","cn":"那次事故使他落下了残疾。"},{"en":"a school for the physically handicapped","cn":"残疾人学校"}],"oxford":{"phon":"ˈhændikæpt","pos":"adjective","senses":[{"en":"having a condition that makes it difficult for you to do some things that most other people can do","cn":"丧失能力的；有残疾的；无能力的","lab":"old-fashioned, usually offensive，，","ex":{"en":"The accident left him physically handicapped.","cn":"那次事故使他落下了残疾。"}},{"en":"people who are handicapped","cn":"残疾人；弱智者","g":"[plural]","lab":"old-fashioned, offensive，，"}]}},"haphazard":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无计划的;杂乱无章的;任意的","en":"If you describe something as haphazard, you are critical of it because it is not at all organized or is not arranged according to a plan.","ex":{"en":"The investigation does seem haphazard","cn":"调查工作确实看起来缺乏计划。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done in a careless and lazy way - use this about someone's work or the way someone writes or speaks","cn":""},{"en":"done extremely carelessly and quickly, without paying any attention to the correct ways of working","cn":""},{"en":"done without any clear plan or system","cn":""}]},"vocab":{"pos":"1 adj 2 adj adv","senses":[{"en":"Anything haphazard is random, disorganized, slipshod, or hit-or-miss. A tent erected haphazardly might look more like a big nylon bag of dirty laundry than a place to sleep."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. very | entirely, totally The local authority's approach to health care seems totally haphazard. | fairly, rather, somewhat | apparently","PHRASES in a haphazard fashion/manner/way The town had grown in a somewhat haphazard way."]},"media":{"uk":"media/ldoce/hwd/bre/a/haphazard0205.mp3","us":"media/ldoce/hwd/ame/7/haphazard.mp3"},"examples":[{"en":"The government's approach to the problem was haphazard.","cn":"政府解决这一问题的方法缺乏计划。"},{"en":"The books had been piled on the shelves in a haphazard fashion.","cn":"书架上的书堆放得杂乱无序。"}],"oxford":{"phon":"hæpˈhæzəd","pos":"adjective","senses":[{"en":"with no particular order or plan; not organized well","cn":"无秩序的；无计划的；组织混乱的","ex":{"en":"The books had been piled on the shelves in a haphazard fashion.","cn":"书架上的书堆放得杂乱无序。"}}]}},"haste":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"急速;仓促;匆忙","en":"Haste is the quality of doing something quickly, sometimes too quickly so that you are careless and make mistakes.","ex":{"en":"In their haste to escape the rising water, they dropped some expensive equipment","cn":"他们在河水上涨仓促逃离时，丢掉了一些值钱的装备。"}},{"pos":"PHRASE 短语","cn":"匆忙地;急忙地;草率地","en":"If you do something in haste, you do it quickly and hurriedly, and sometimes carelessly.","ex":{"en":"Don't act in haste or be hot-headed.","cn":"不可草率行事，不可头脑发热。"}},{"pos":"PHRASE 短语","cn":"赶快;赶紧","en":"If someone is told to make haste, they are told to do something quickly and not waste time.","ex":{"en":"As Simon was under orders to make haste, some days they covered thirty miles.","cn":"西蒙接到命令要求抓紧行动，有些日子他们一走就是30英里。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to go somewhere or do something more quickly than usual, for example because you are late or because you must finish something by a particular time","cn":""},{"en":"to do something or go somewhere very quickly, often so quickly that you do not do it carefully or properly","cn":""},{"en":"to go somewhere very quickly, usually by running, especially because there is something important or urgent you must do","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When something is done in haste, it's done fast, and often with carelessness. In his haste to finish the paper, he didn't notice he had replaced \"taste\" with \"waste\" during spell-checking, so his title became, \"Foods of Our Home State: What a Waste!\""}]},"collocations":{"phrases":["ADJ. blind, breathless, frantic, great She worked with frantic haste. | indecent, reckless, undue He accused the government of undue haste i","VERB + HASTE make I had to make haste if I wasn't to be late.","PREP. in (your) ~ They obviously left in great haste. In his haste to get home, he forgot to go to the library. | with ~ He married again wi","PHRASES with all haste The ships were ordered to sea with all haste."]},"media":{"uk":"media/ldoce/hwd/bre/7/haste0205.mp3","us":"media/ldoce/hwd/ame/6/haste.mp3"},"examples":[{"en":"After his first wife died, he married again with almost indecent haste.","cn":"他的第一任妻子死后，他几乎是迫不及待地就再婚了。"},{"en":"In her haste to complete the work on time, she made a number of mistakes.","cn":"她急急忙忙想按时完工，结果出了不少错。"}],"oxford":{"phon":"heɪst","pos":"noun","senses":[{"en":"speed in doing something, especially because you do not have enough time","cn":"急速；匆忙；仓促","lab":"old-fashioned","ex":{"en":"In her haste to complete the work on time, she made a number of mistakes.","cn":"她急急忙忙想按时完工，结果出了不少错。"}}]}},"habitable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可居住的;适宜居住的","en":"If a place is habitable, it is good enough for people to live in.","ex":{"en":"Making the house habitable was a major undertaking.","cn":"把这所房子收拾得可以住人，那可是项大工程。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a building or area of land that is habitable is suitable for people to live in, for example because it is clean enough, warm enough, safe enough etc","cn":""},{"en":"if a building is fit to live in , it is in a suitable condition for people to live in it","cn":""},{"en":"not suitable for living in or on","cn":""}]},"collocations":{"phrases":["VERBS be | remain | make sth, render sth They've done their best to make the house habitable. | consider sth The houses were not considered ","ADV. barely The room was barely habitable."]},"media":{"uk":"media/ldoce/hwd/bre/7/habitable0205.mp3","us":"media/ldoce/hwd/ame/b/habitable.mp3"},"examples":[{"en":"The house should be habitable by the new year.","cn":"房子到新年时应该就可以住进去了。"},{"en":"It would cost a fortune to make the place habitable.","cn":"要想让这个地方可以住人得花一大笔钱。"}],"oxford":{"phon":"ˈhæbɪtəbl","pos":"adjective","senses":[{"en":"suitable for people to live in","cn":"适合居住的","ex":{"en":"The house should be habitable by the new year.","cn":"房子到新年时应该就可以住进去了。"}}]}},"handkerchief":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手帕","en":"A handkerchief is a small square piece of fabric which you use for blowing your nose."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of cloth that you use for drying your nose or eyes","cn":"手帕"}]},"collocations":{"phrases":["ADJ. clean | crumpled, dirty, grubby, used | pocket | lace, linen, paper, silk | embroidered","VERB + HANDKERCHIEF blow your nose on, use He blew his nose on a grubby handkerchief. | wave"]},"media":{"uk":"media/ldoce/hwd/bre/c/handkerchief0205.mp3","us":"media/ldoce/hwd/ame/7/handkerchief.mp3"},"oxford":{"phon":"ˈhæŋkətʃɪf","pos":"noun","senses":[{"en":"a small piece of material or paper that you use for blowing your nose, etc.","cn":"手帕；纸巾","ex":{"en":"He blew his nose on a dirty handkerchief.","cn":"他用一块脏兮兮的手帕擤鼻涕。"}}]}},"harmless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无害的;（尤指对健康）不造成伤害的","en":"Something that is harmless does not have any bad effects, especially on people's health.","ex":{"en":"Industry has been working at developing harmless substitutes for these gases","cn":"该行业一直在努力开发一些可以替代这些气体的无害物质。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无关紧要的;不讨人厌的;不会惹麻烦的","en":"If you describe someone or something as harmless, you mean that they are not important and therefore unlikely to annoy other people or cause trouble.","ex":{"en":"He seemed harmless enough","cn":"他看起来不会惹什么麻烦。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not harmful - use this especially when people have said or believe that something or someone is harmful","cn":""},{"en":"if an action, activity, experience etc does no harm , it does not harm someone or something and may even help","cn":""},{"en":"used especially about products in shops, meaning that they do not harm the environment etc","cn":""}]},"collocations":{"phrases":["VERBS appear, be, look, seem, sound | make sth, render sth chemical wastes which have to be rendered harmless | consider sth","ADV. absolutely, completely, perfectly, quite, totally | almost, virtually | enough He looks harmless enough. | comparatively, fairly, prett","PREP. to The substance is harmless to people."]},"media":{"uk":"media/ldoce/hwd/bre/9/harmless0205.mp3","us":"media/ldoce/hwd/ame/c/harmless.mp3"},"examples":[{"en":"The missile fell harmlessly into the sea.","cn":"导弹落到了海里，没有造成任何伤害。"},{"en":"It's just a bit of harmless fun.","cn":"开个小玩笑罢了，并无恶意的。"}],"oxford":{"phon":"ˈhɑːmləs","pos":"adjective","senses":[{"en":"unable or unlikely to cause damage or harm","cn":"无害的；不会导致损伤的","ex":{"en":"The bacteria is harmless to humans.","cn":"这种细菌对人类无害。"}},{"en":"unlikely to upset or offend anyone","cn":"不会引起不快的；无恶意的","ex":{"en":"It's just a bit of harmless fun.","cn":"开个小玩笑罢了，并无恶意的。"}}]}},"hamper":{"collins":{"senses":[{"pos":"VERB 动词","cn":"妨碍;阻碍;牵制;束缚","en":"If someone or something hampers you, they make it difficult for you to do what you are trying to do.","ex":{"en":"The bad weather hampered rescue operations","cn":"恶劣的天气阻碍了救援工作的进行。"}},{"pos":"N-COUNT 可数名词","cn":"（装有各种食品的）礼物篮","en":"A hamper is a basket containing food of various kinds that is given to people as a present.","ex":{"en":"...a luxury food hamper.","cn":"豪华食品礼物篮"}},{"pos":"N-COUNT 可数名词","cn":"（尤指装食品用的）带盖大篮","en":"A hamper is a large basket with a lid, used especially for carrying food in.","ex":{"en":"...a picnic hamper.","cn":"野餐篮子"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make it very difficult for an activity or plan to continue successfully","cn":""},{"en":"to cause problems and therefore delay the development or progress of something","cn":""},{"en":"to make progress or the development of something slower or more difficult","cn":""}]},"vocab":{"pos":"1 v n 2 n","senses":[{"en":"Use the verb hamper to describe an action that slows progress or makes it difficult to do something, like the presence of your parents that hamper your ability to look cool at the mall."}]},"collocations":{"phrases":["ADV. badly, greatly, seriously, severely Rescue efforts were severely hampered by the bad weather. | further"]},"media":{"img":["media/ldoce/img/picnic.jpg"],"uk":"media/ldoce/hwd/bre/a/hamper_n0205.mp3","us":"media/ldoce/hwd/ame/9/hamper1.mp3"},"examples":[{"en":"a Christmas hamper","cn":"圣诞礼品盒"},{"en":"a picnic hamper","cn":"野餐篮"}],"oxford":{"phon":"ˈhæmpə(r)","pos":"verb","senses":[{"en":"to prevent somebody from easily doing or achieving something","cn":"妨碍；阻止；阻碍","ex":{"en":"High winds hampered the rescue attempt.","cn":"大风阻碍了救援行动。"}},{"en":"a large basket with a lid (= cover), especially one used to carry food in","cn":"（尤指用于盛食物的）带盖大篮子","ex":{"en":"a picnic hamper","cn":"野餐篮"},"pos":"noun"},{"en":"a box or package containing food, sent as a gift","cn":"（作为礼品的）盒装食物，袋装食物","lab":"especially British English","ex":{"en":"a Christmas hamper","cn":"圣诞礼品盒"},"pos":"noun"},{"en":"a large basket that you keep your dirty clothes in until they are washed","cn":"盛脏衣服的大篮子","lab":"North American English","pos":"noun"}]}},"hazardous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指对健康或安全）有危险的，有危害的","en":"Something that is hazardous is dangerous, especially to people's health or safety.","ex":{"en":"They have no way to dispose of the hazardous waste they produce","cn":"他们没有办法处理掉自己产生的有害废料。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"likely to cause death or serious harm, or cause something bad to happen","cn":""},{"en":"if something is risky, something bad could easily happen or you could easily make a mistake","cn":""},{"en":"dangerous – used especially about substances, jobs, and journeys","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"The noun \"hazard\" means something dangerous, and the adjective hazardous refers to anything that involves danger. A golf course with lots of sand traps is especially hazardous for golfers. That's why those traps are called hazards."}]},"collocations":{"phrases":["VERBS be, prove | become | consider sth","ADV. extremely, highly, particularly, very | rather, somewhat | potentially burning potentially hazardous medical waste | environmentally en","PREP. for These conditions are very hazardous for shipping. | to chemicals that are hazardous to human beings"]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41hazardous.mp3","us":"media/ldoce/hwd/ame/a/hazardous.mp3"},"examples":[{"en":"a list of products that are potentially hazardous to health","cn":"对健康有潜在危害的产品清单"},{"en":"It would be hazardous to invest so much.","cn":"投资这么多会有风险。"}],"oxford":{"phon":"ˈhæzədəs","pos":"adjective","senses":[{"en":"involving risk or danger, especially to somebody’s health or safety","cn":"危险的；有害的","ex":{"en":"hazardous waste/materials/substances/chemicals","cn":"有害废物／物料／物质／化学品"}}]}},"halve":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"把…减半;减到一半","en":"When you halve something or when it halves, it is reduced to half its previous size or amount.","ex":{"en":"Dr Lee believes that men who exercise can halve their risk of cancer of the colon","cn":"李医生相信，锻炼身体能使患结肠癌的风险降低一半。"}},{"pos":"VERB 动词","cn":"将…对半分;把…二等分","en":"If you halve something, you divide it into two equal parts.","ex":{"en":"Halve the pineapple and scoop out the inside.","cn":"将菠萝对半切开，挖出里面的果肉。"}},{"pos":"","cn":"（half 的复数）","en":"Halves is the plural of half."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something less in amount or level","cn":""},{"en":"to reduce an amount, limit, or level - use this especially in writing about business or technical subjects","cn":""},{"en":"to reduce something by a lot, especially prices, time, or money","cn":""}]},"collocations":{"phrases":["ADV. more than | almost, nearly, virtually | approximately, roughly | effectively","PREP. in The shares have more than halved in value since the summer high of 572p. | to Overall operating profits halved to $24 million."]},"media":{"uk":"media/ldoce/hwd/bre/0/halve0205.mp3","us":"media/ldoce/hwd/ame/9/halve.mp3"},"examples":[{"en":"The company is halving its prices.","cn":"该公司正将产品半价出售。"},{"en":"The shares have halved in value.","cn":"股价已经跌了一半。"}],"oxford":{"phon":"hɑːv","pos":"verb","senses":[{"en":"to reduce by a half; to make something reduce by a half","cn":"（使）减半","g":"[intransitive, transitive]","ex":{"en":"The shares have halved in value.","cn":"股价已经跌了一半。"}},{"en":"to divide something into two equal parts","cn":"平分；把…对半分","g":"[transitive]"}]}},"hassle":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"麻烦;困难;争吵","en":"A hassle is a situation that is difficult and involves problems, effort, or arguments with people.","ex":{"en":"I don't think it's worth the money or the hassle","cn":"我认为不值得为此花费那么多金钱和精力。"}},{"pos":"VERB 动词","cn":"烦扰;纠缠","en":"If someone hassles you, they cause problems for you, often by repeatedly telling you or asking you to do something, in an annoying way.","ex":{"en":"Then my husband started hassling me","cn":"然后我丈夫开始不停地烦我。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a problem that stops you from making progress","cn":""},{"en":"a problem, especially one that you had not expected","cn":""},{"en":"a small problem that delays or prevents something","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Something that is bothersome or annoying can be called a hassle . It's a huge hassle to go back to the grocery story after unloading fifteen bags and realizing you forgot milk."}]},"collocations":{"phrases":["ADJ. legal They faced interminable legal hassles if they wanted to claim compensation.","VERB + HASSLE get, have I started to get all this hassle from my boss about increasing productivity. | give sb He gave me so much hassle I d","PREP. with no/without ~ She got the computer set up with no hassle at all. | ~ about/over I've had so much hassle over this business.","PHRASES take the hassle out of sth Package holidays take all the hassle out of travel arrangements."]},"media":{"uk":"media/ldoce/hwd/bre/8/hassle_n0205.mp3","us":"media/ldoce/hwd/ame/a/hassle1.mp3"},"examples":[{"en":"Send them an email — it's a lot less hassle than phoning.","cn":"给他们发个电邮吧，这比打电话省事多了。"},{"en":"Do as you're told and don't give me any hassle!","cn":"告诉你怎么做就怎么做，别跟我顶嘴！"}],"oxford":{"phon":"ˈhæsl","pos":"noun","senses":[{"en":"a situation that is annoying because it involves doing something difficult or complicated that needs a lot of effort","cn":"困难；麻烦","ex":{"en":"It’s a hassle having to travel with so many bags.","cn":"要带着这么多大包小包去旅行，真麻烦。"}},{"en":"a situation in which people disagree, argue or annoy you","cn":"分歧；争论；烦恼","lab":"North American English","ex":{"en":"Do as you're told and don't give me any hassle!","cn":"告诉你怎么做就怎么做，别跟我顶嘴！"}},{"en":"to annoy somebody or cause them trouble, especially by asking them to do something many times","cn":"（不断）烦扰，麻烦","ex":{"en":"Don't keep hassling me! I'll do it later.","cn":"别老烦我！我待会儿会做的。"},"pos":"verb"}]}},"haemorrhage":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"体内大出血","en":"A haemorrhage is serious bleeding inside a person's body.","ex":{"en":"Shortly after his admission into hospital he had a massive brain haemorrhage and died","cn":"住院后不久，他就死于大面积脑溢血。"}},{"pos":"VERB 动词","cn":"体内大出血","en":"If someone is haemorrhaging, there is serious bleeding inside their body.","ex":{"en":"I haemorrhaged badly after the birth of all three of my sons","cn":"生我3个儿子时，我每次都出现产后大出血。"}},{"pos":"N-SING 单数名词","cn":"（人员或资源的）严重流失","en":"A haemorrhage of people or resources is a rapid loss of them from a group or place, seriously weakening its position.","ex":{"en":"He said the move would definitely stem the haemorrhage of talent and enterprise from the colony.","cn":"他表示这一举措势必会抑制殖民地人才和企业严重流失的现象。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（人员或资源）严重流失","en":"To haemorrhage people or resources means to lose them rapidly and become weak. You can also say that people or resources haemorrhage from a place or organization.","ex":{"en":"Venice is haemorrhaging the very resource which could save it: its own people","cn":"威尼斯正在丧失它的立足之本，那就是它的人民。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a serious medical condition in which a person bleed s a lot, sometimes inside their body 〔","cn":"体内〕(大)出血"},{"en":"when a company or country loses a lot of money or people very quickly 〔","cn":"资金﹑人才的〕大量流失"},{"en":"to lose a lot of blood in a very short time","cn":"大出血"}]},"collocations":{"phrases":["ADJ. massive, severe | recurrent | acute The patient died from acute cerebral haemorrhage. | brain, cerebral","VERB + HAEMORRHAGE have, suffer Twelve hours later she suffered a massive brain haemorrhage. | die from/of | halt, stop (both usually figura"]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdehaemorrhage.mp3","us":"media/ldoce/hwd/ame/d/hemorrhage1.mp3"},"examples":[{"en":"Poor working conditions have led to a steady haemorrhage of qualified teachers from our schools.","cn":"工作条件欠佳导致各校大量合格教师不断流失。"},{"en":"He was checked for any signs of haemorrhage.","cn":"他接受检查，以确定是否有出血迹象。"}],"oxford":{"phon":"ˈhemərɪdʒ","pos":"noun","senses":[{"en":"a medical condition in which there is severe loss of blood from a damaged blood vessel inside a person’s body","cn":"体内（大）出血","g":"[countable, uncountable]","ex":{"en":"a massive brain/cerebral haemorrhage","cn":"重度脑出血"}},{"en":"a serious loss of people, money, etc. from a country, a group or an organization","cn":"（人、资金等的）大量流失","g":"[countable, usually singular]","ex":{"en":"Poor working conditions have led to a steady haemorrhage of qualified teachers from our schools.","cn":"工作条件欠佳导致各校大量合格教师不断流失。"}},{"en":"to lose blood heavily, especially from a damaged blood vessel inside the body; to have a haemorrhage","cn":"（尤指体内）大出血","g":"[intransitive]","ex":{"en":"After the operation she started to haemorrhage.","cn":"手术后，她开始流血。"},"pos":"verb"},{"en":"to lose money or people in large amounts at a fast rate","cn":"大量快速流失（资金、人等）","g":"[transitive]","ex":{"en":"The company has been haemorrhaging money for months.","cn":"该公司几个月来一直在亏损。"},"pos":"verb"}]}},"haze":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（阴）霾;雾霭","en":"Haze is light mist, caused by particles of water or dust in the air, which prevents you from seeing distant objects clearly. Haze often forms in hot weather.","ex":{"en":"They vanished into the haze near the horizon","cn":"他们消失在天边的雾霾中。"}},{"pos":"N-SING 单数名词","cn":"雾状物","en":"If there is a haze of something such as smoke or steam, you cannot see clearly through it.","ex":{"en":"Dan smiled at him through a haze of smoke and steaming coffee","cn":"丹透过烟雾和咖啡的热气朝他笑了笑。"}},{"pos":"N-SING 单数名词","cn":"迷糊;懵懂","en":"If someone is in a haze, they are not thinking clearly or not really noticing what is happening around them.","ex":{"en":"His mind was a haze of fear and confusion.","cn":"由于害怕和困惑，他当时处于一种混沌状态。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a white or grey mass in the sky that forms from very small drops of water","cn":""},{"en":"very thick cloud near the ground which is difficult to see through","cn":""},{"en":"light cloud near the ground that makes it difficult for you to see very far. Mist is usually not as thick as fog . You often get mist near areas of water or mountains","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"Haze is the fog or mist that's caused by small particles in the air. There is often a haze hovering over the city of Los Angeles."}]},"collocations":{"phrases":["ADJ. thick a thick haze of smoke | faint, thin The sun now had a faint golden haze around it. | shimmering | heat A heat haze shimmered abov","HAZE + VERB hang, shimmer In the evenings a blue haze hung in the valleys.","PREP. in a/the ~ Meetings are always conducted in a haze of cigarette smoke. | through a/the ~ He watched the world through a haze of tobacc"]},"media":{"uk":"media/ldoce/hwd/bre/7/haze_n0205.mp3","us":"media/ldoce/hwd/ame/e/haze1.mp3"},"examples":[{"en":"a haze of smoke/dust/steam","cn":"烟雾；尘雾；蒸汽雾"},{"en":"an alcoholic haze","cn":"喝醉酒的迷糊"}],"oxford":{"phon":"heɪz","pos":"noun","senses":[{"en":"air that is difficult to see through because it contains very small drops of water, especially caused by hot weather","cn":"（尤指热天引起的）薄雾，雾霭","g":"[countable, uncountable]","ex":{"en":"a heat haze","cn":"热天的雾气"}},{"en":"air containing something that makes it difficult to see through it","cn":"（烟尘等的）雾霭，烟雾","g":"[singular]","ex":{"en":"a haze of smoke/dust/steam","cn":"烟雾；尘雾；蒸汽雾"}},{"en":"a mental state in which your thoughts, feelings, etc. are not clear","cn":"迷蒙；迷糊","g":"[singular]","ex":{"en":"an alcoholic haze","cn":"喝醉酒的迷糊"}},{"en":"to become covered or to cover something in a haze","cn":"（使）笼罩在薄雾中","g":"[intransitive, transitive]","pos":"verb"},{"en":"to play tricks on somebody, especially a new student or somebody who has just joined the army, or to give them very unpleasant things to do, sometimes as a condition for entering a fraternity or sorority","cn":"戏弄，刁难（新生、新兵等）","g":"[transitive]","lab":"North American English","ex":{"en":"Rookies were mercilessly hazed.","cn":"新兵们被无情地折腾。"},"pos":"verb"}]}},"hanker":{"collins":{"senses":[{"pos":"VERB 动词","cn":"渴望;热望","en":"If you hanker after something, you want it very much.","ex":{"en":"I hankered after a floor-length brown suede coat.","cn":"我渴望有一件长及脚跟的棕色绒面革大衣。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to want something that you have wanted for a long time, but which you are unlikely to get","cn":""},{"en":"to very much want to have something or do something, especially when this used to happen or exist in the past, or when it may do in the future - used especially in stories or literature","cn":""},{"en":"to want something so much that you do not feel happy or complete without it","cn":""}]},"collocations":{"phrases":["ADV. secretly | always | still","PREP. after She's always hankering after excitement. | for I still hankered for the farm life."]},"media":{"uk":"media/ldoce/hwd/bre/e/hanker0205.mp3","us":"media/ldoce/hwd/ame/3/hanker.mp3"},"examples":[{"en":"She hankered to go back to Australia.","cn":"她渴望回到澳大利亚。"},{"en":"He had hankered after fame all his life.","cn":"他一生追求名望。"}],"oxford":{"phon":"ˈhæŋkə(r)","pos":"verb","senses":[{"en":"to have a strong desire for something","cn":"渴望，渴求（某事物）","ex":{"en":"He had hankered after fame all his life.","cn":"他一生追求名望。"}}]}},"haggle":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"（尤指就价格）争论;讨价还价","en":"If you haggle, you argue about something before reaching an agreement, especially about the cost of something that you are buying.","ex":{"en":"Ella taught her how to haggle with used furniture dealers","cn":"埃拉教她如何和旧家具经销商砍价。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to try to persuade someone to reduce the price of something by arguing with them about what it is worth","cn":""},{"en":"to try to persuade someone to reduce the price of something by discussing it with them","cn":""},{"en":"to persuade someone to reduce the price of something by arguing with them about it","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you want a great deal on a used TV, then you can try to haggle with the sellers to see if they’ll bring the price down. To haggle is to negotiate or argue over something, usually a price."}]},"media":{"uk":"media/ldoce/hwd/bre/f/haggle0205.mp3","us":"media/ldoce/hwd/ame/0/haggle.mp3"},"examples":[{"en":"I left him in the market haggling over the price of a shirt.","cn":"我扔下他自己在市场上就一件衬衫讨价还价。"},{"en":"tourists haggling over the price of souvenirs","cn":"对纪念品讨价还价的游客"}],"oxford":{"phon":"ˈhæɡl","pos":"verb","senses":[{"en":"to argue with somebody in order to reach an agreement, especially about the price of something","cn":"争论；（尤指）讲价","ex":{"en":"I left him in the market haggling over the price of a shirt.","cn":"我扔下他自己在市场上就一件衬衫讨价还价。"}}]}}});
